insert into lesson (id, ordinal, title_en, title_it, grammar_points, video_id) values
  ('が-が示す主語', 1, 'The subject with が, and the three kinds of predicate', 'Il soggetto con が e i tre tipi di predicato', array['「が」が示す主語', '述語の三つの形'], 'pSvH9vH60Ig'),
  ('ゼロ代名詞', 2, 'The unwritten subject (zero pronoun), and the object with を', 'Il soggetto sottinteso (pronome zero) e l''oggetto con を', array['ゼロ代名詞', '「を」で示す目的語'], 'P3n8n0u3LHA'),
  ('は-が示す主題', 3, 'The topic with は, and the destination with に', 'Il tema con は e la destinazione con に', array['「は」が示す主題', '到達点を示す「に」'], 'U9_T4eObNXg'),
  ('非過去形', 4, 'Verb tenses: future or habit, happening now, past; time words with or without に', 'I tempi del verbo: futuro o abitudine, azione in corso, passato; le parole di tempo con o senza に', array['非過去形', '「ている」の進行', '過去形の「た」', '時を示す「に」'], 'lU5rmrAORDY'),
  ('動詞の三つのグループ', 5, 'The three verb groups and how to make the て and た forms', 'I tre gruppi di verbi e come si fanno le forme in て e in た', array['動詞の三つのグループ', 'て形・た形の作り方'], 'GzEVLMDC8nw'),
  ('名詞を修飾する述語', 6, 'Describing a noun: adjectives, verbs, な and の', 'Descrivere un nome: aggettivi, verbi, な e の', array['名詞を修飾する述語', '名詞を修飾する「な」', '名詞を修飾する「の」'], 'iyVZlaEqU24'),
  ('否定の-ない', 7, 'Saying "not": ない and ません', 'Dire «non»: ない e ません', array['否定の「ない」', '名詞文の否定「ではない」', '形容詞の否定「くない」', '丁寧な否定「ません」'], 'KIPhvGxp43c'),
  ('動詞の語幹と助動詞', 8, 'The verb stem and its auxiliaries (ます, たい, せる, れる, よう)', 'Il radicale del verbo e i suoi ausiliari (ます, たい, せる, れる, よう)', array['動詞の語幹と助動詞', '連用形につく「ます」「たい」', '未然形につく「せる」「れる」', '意向形'], 'FhyrskGBKHE'),
  ('目的地を示す-に', 9, 'The particle に (where you go, why, where something is, what it becomes) and へ', 'La particella に (dove si va, per fare cosa, dove si trova, cosa diventa) e へ', array['目的地を示す「に」', '目的を示す「に」', '存在の場所を示す「に」', '変化の結果を示す「に」', '方向を示す「へ」'], 'uqlQYrE2oFM'),
  ('動作の場所を示す-で', 10, 'で for the place of an action and for the means; と to join nouns', 'で per il luogo di un''azione e per il mezzo; と per unire i nomi', array['動作の場所を示す「で」', '手段を示す「で」', '名詞をつなぐ「と」'], 'dwcTI9qvO-U'),
  ('感情-理解の述語と-が', 11, 'Likes, understanding and wishes with が; がる for other people''s feelings', 'Gusti, capire e desideri con が; がる per i sentimenti degli altri', array['感情・理解の述語と「が」', '欲求の「ほしい」と「たい」', '他人の感情を示す「がる」'], 'vk3aKqMQwhM'),
  ('可能形', 12, 'The potential form ("can do") and できる', 'La forma potenziale («posso fare») e できる', array['可能形', '不規則動詞の可能形', '可能形と「が」'], 'qcOhHmU0znI'),
  ('て形で節をつなぐ', 13, 'The te-form to join actions; favours with てくれる and てあげる', 'La forma in て per unire le azioni; i favori con てくれる e てあげる', array['て形で節をつなぐ', '恩恵を受ける「てくれる」', '恩恵を与える「てあげる」'], '3X2ZCWazrDw')
on conflict (id) do update set
  ordinal = excluded.ordinal,
  title_en = excluded.title_en,
  title_it = excluded.title_it,
  grammar_points = excluded.grammar_points,
  video_id = excluded.video_id;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('57975a13-e0c2-5eda-9d3f-5bb832248016', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"妹が毎朝歌います","kana":"いもうとがまいあさうたいます"},"answer":["妹が","毎朝","歌います"],"alsoAccepted":[["毎朝","妹が","歌います"]],"prompt":{"en":"Build: \"My younger sister sings every morning.\"","it":"Componi: «Mia sorella minore canta ogni mattina.»"},"translation":{"en":"My younger sister sings every morning.","it":"Mia sorella minore canta ogni mattina."},"glosses":[{"text":"妹が","reading":"いもうとが","meaning":{"en":"younger sister (subject)","it":"sorella minore (soggetto)"}},{"text":"毎朝","reading":"まいあさ","meaning":{"en":"every morning","it":"ogni mattina"}},{"text":"歌います","reading":"うたいます","meaning":{"en":"sings","it":"canta"}}]}'::jsonb, '「が」が示す主語', 'が marks the subject: the one who does the action (here 妹, younger sister). The predicate, the part that says something about the subject, is 歌います (sings). 毎朝 (every morning) only says when, so it takes no が. "毎朝妹が歌います" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'が segna il soggetto: chi compie l''azione (qui 妹, la sorella minore). Il predicato, cioè la parte che dice qualcosa del soggetto, è 歌います (canta). 毎朝 (ogni mattina) dice solo quando, quindi non prende が. Va bene anche «毎朝妹が歌います»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('2e47b85b-29ba-54d7-a09a-2533decd1cb3', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"妹が学生だ","kana":"いもうとががくせいだ"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part means \"is\"?","it":"Quale parte vuol dire «è»?"},"translation":{"en":"My younger sister is a student.","it":"Mia sorella minore è una studentessa."},"glosses":[{"text":"妹が学生","meaning":{"en":"younger sister (subject) + student","it":"sorella minore (soggetto) + studentessa"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '述語の三つの形', 'だ means "is". It works like "is" in "my sister is a student": it links the subject (妹) to a noun (学生, student). A predicate ends in one of three ways: a verb, a noun + だ, or an い-adjective.', 'だ vuol dire «è». Funziona come «è» in «mia sorella è una studentessa»: collega il soggetto (妹) a un nome (学生, studentessa). Un predicato finisce in uno di tre modi: con un verbo, con un nome + だ, oppure con un aggettivo in い.'),
  ('8347f682-389b-5c65-81af-6af0f0424823', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"水が冷たい","kana":"みずがつめたい"},"answer":"冷たい","distractors":["冷たいだ","冷だ","冷たくだ"],"gap":{"kanji":"水が＿","kana":"みずが＿"},"prompt":{"en":"\"The water is cold.\" Which predicate is correct?","it":"«L''acqua è fredda.» Qual è il predicato giusto?"},"translation":{"en":"The water is cold.","it":"L''acqua è fredda."},"glosses":[{"text":"冷たい","reading":"つめたい"},{"text":"冷たいだ","reading":"つめたいだ"},{"text":"冷だ","reading":"つめだ"},{"text":"冷たくだ","reading":"つめたくだ"}]}'::jsonb, '述語の三つの形', 'An い-adjective (an adjective that ends in い, like 冷たい) already contains "is": 冷たい means "is cold". So you never add だ ("is") after it. 冷だ and 冷たくだ do not exist.', 'Un aggettivo in い (un aggettivo che finisce in い, come 冷たい) contiene già «è»: 冷たい vuol dire «è freddo». Per questo dopo non si aggiunge mai だ («è»). 冷だ e 冷たくだ non esistono.'),
  ('95f788c5-e8de-5ee0-939f-ccb14bb33878', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"犬が走る","kana":"いぬがはしる"},"answer":"が","distractors":["を","の"],"gap":{"kanji":"犬＿走る","kana":"いぬ＿はしる"},"prompt":{"en":"\"The dog runs.\" Which particle marks who runs?","it":"«Il cane corre.» Quale particella segna chi corre?"},"translation":{"en":"The dog runs.","it":"Il cane corre."}}'::jsonb, '「が」が示す主語', 'A particle is a small word after a noun that shows its role in the sentence. The dog is the one who runs, so it is the subject and takes が. を would make the dog the thing something is done to, and の joins two nouns ("the dog''s …"), but here a verb follows.', 'Una particella è una piccola parola dopo un nome che ne indica il ruolo nella frase. Il cane è chi corre, quindi è il soggetto e prende が. を farebbe del cane la cosa su cui si agisce, e の unisce due nomi («il … del cane»), ma qui segue un verbo.'),
  ('96417561-b8b2-5859-a24b-bd3424eb35df', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"鳥が飛ぶ","kana":"とりがとぶ"},"answer":"飛ぶ","distractors":["飛ぶだ","飛びだ"],"gap":{"kanji":"鳥が＿","kana":"とりが＿"},"prompt":{"en":"\"The bird flies.\" Which predicate is correct?","it":"«L''uccello vola.» Qual è il predicato giusto?"},"translation":{"en":"The bird flies.","it":"L''uccello vola."},"glosses":[{"text":"飛ぶ","reading":"とぶ"},{"text":"飛ぶだ","reading":"とぶだ"},{"text":"飛びだ","reading":"とびだ"}]}'::jsonb, '述語の三つの形', 'A verb (a word for an action, like 飛ぶ, "to fly") is a complete predicate on its own. だ ("is") goes after a noun, never after a verb. So the sentence simply ends with 飛ぶ.', 'Un verbo (una parola che indica un''azione, come 飛ぶ, «volare») è da solo un predicato completo. だ («è») va dopo un nome, mai dopo un verbo. Quindi la frase finisce semplicemente con 飛ぶ.'),
  ('02123de7-b2e5-585e-ac74-e6acd9887a28', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"母が先生だ","kana":"ははがせんせいだ"},"answer":"だ","distractors":["が","を"],"gap":{"kanji":"母が先生＿","kana":"ははがせんせい＿"},"prompt":{"en":"\"My mother is a teacher.\" What goes at the end?","it":"«Mia madre è un''insegnante.» Che cosa va alla fine?"},"translation":{"en":"My mother is a teacher.","it":"Mia madre è un''insegnante."}}'::jsonb, '述語の三つの形', '先生 (teacher) is a noun, and a noun needs だ ("is") to become a predicate: 先生だ means "is a teacher". が and を are particles: they mark the role of a noun and cannot end the sentence.', '先生 (insegnante) è un nome, e un nome ha bisogno di だ («è») per diventare un predicato: 先生だ vuol dire «è un''insegnante». が e を sono particelle: indicano il ruolo di un nome e non possono chiudere la frase.'),
  ('ad39360b-8249-53f5-9c12-9470d788e82e', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"バスが来た","kana":"バスがきた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the subject?","it":"Quale parte è il soggetto?"},"translation":{"en":"The bus came.","it":"L''autobus è arrivato."},"glosses":[{"text":"バスが","meaning":{"en":"the bus (subject)","it":"l''autobus (soggetto)"}},{"text":"来","reading":"き","meaning":{"en":"come (kanji of 来る)","it":"venire (kanji di 来る)"}},{"text":"た","meaning":{"en":"past-tense ending","it":"desinenza del passato"}}]}'::jsonb, '「が」が示す主語', 'The subject is バスが: the bus is what came. が comes right after the subject and marks it. 来た (came) is the predicate, the part that says what the subject did.', 'Il soggetto è バスが: l''autobus è ciò che è arrivato. が viene subito dopo il soggetto e lo segna. 来た (è arrivato) è il predicato, la parte che dice che cosa ha fatto il soggetto.'),
  ('088b4f0c-3fc5-559c-a9eb-1f3423da41a7', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"スープが熱い","kana":"スープがあつい"},"answer":{"start":0,"end":1},"prompt":{"en":"What is hot? Select the subject.","it":"Che cosa è caldo? Seleziona il soggetto."},"translation":{"en":"The soup is hot.","it":"La zuppa è calda."},"glosses":[{"text":"スープが","meaning":{"en":"the soup (subject)","it":"la zuppa (soggetto)"}},{"text":"熱","reading":"あつ","meaning":{"en":"hot (kanji of 熱い)","it":"caldo (kanji di 熱い)"}},{"text":"い","meaning":{"en":"ending of the い-adjective","it":"finale dell''aggettivo in い"}}]}'::jsonb, '「が」が示す主語', 'The subject is スープが: the soup is what is hot. Here the predicate is 熱い ("is hot"), an い-adjective (an adjective that ends in い). It takes its subject with が, just like a verb does.', 'Il soggetto è スープが: la zuppa è ciò che è caldo. Qui il predicato è 熱い («è caldo»), un aggettivo in い (un aggettivo che finisce in い). Prende il soggetto con が, proprio come un verbo.'),
  ('4ccc8886-e854-5c55-a092-0969d474f1f1', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"兄が医者だ","kana":"あにがいしゃだ"},"answer":["兄が","医者","だ"],"prompt":{"en":"Build: \"My older brother is a doctor.\"","it":"Componi: «Mio fratello maggiore è medico.»"},"translation":{"en":"My older brother is a doctor.","it":"Mio fratello maggiore è medico."},"glosses":[{"text":"兄が","reading":"あにが","meaning":{"en":"older brother (subject)","it":"fratello maggiore (soggetto)"}},{"text":"医者","reading":"いしゃ","meaning":{"en":"doctor","it":"medico"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '述語の三つの形', 'The subject 兄 (older brother) comes first, with が. Then comes the noun 医者 (doctor) and だ, the word for "is" that links the subject to that noun. In Japanese the predicate always comes last.', 'Il soggetto 兄 (fratello maggiore) viene per primo, con が. Poi il nome 医者 (medico) e だ, la parola per «è» che collega il soggetto a quel nome. In giapponese il predicato va sempre alla fine.'),
  ('f18bbdf2-9a07-56f2-98e2-bf2125774963', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"この店のラーメンがおいしい","kana":"このみせのラーメンがおいしい"},"answer":["この","店の","ラーメンが","おいしい"],"prompt":{"en":"Build: \"The ramen at this restaurant is delicious.\"","it":"Componi: «Il ramen di questo locale è buonissimo.»"},"translation":{"en":"The ramen at this restaurant is delicious.","it":"Il ramen di questo locale è buonissimo."},"glosses":[{"text":"この","meaning":{"en":"this","it":"questo"}},{"text":"店の","reading":"みせの","meaning":{"en":"of the restaurant","it":"del locale"}},{"text":"ラーメンが","meaning":{"en":"ramen (subject)","it":"ramen (soggetto)"}},{"text":"おいしい","meaning":{"en":"is delicious (い-adjective)","it":"è buonissimo (aggettivo in い)"}}]}'::jsonb, '述語の三つの形', 'The subject is ラーメン, marked by が; この店の ("of this restaurant") comes before it and describes it. The predicate is おいしい, an い-adjective (an adjective that ends in い) that already means "is delicious". So no だ follows it.', 'Il soggetto è ラーメン, segnato da が; この店の («di questo locale») viene prima e lo descrive. Il predicato è おいしい, un aggettivo in い (un aggettivo che finisce in い) che vuol già dire «è buonissimo». Per questo dopo non c''è だ.'),
  ('29771fbf-ff64-5f0b-a51b-84d1134f51a9', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"風が強い","kana":"かぜがつよい"},"answer":"が","distractors":["を","で"],"gap":{"kanji":"風＿強い","kana":"かぜ＿つよい"},"prompt":{"en":"\"The wind is strong.\" Which particle marks what is strong?","it":"«Il vento è forte.» Quale particella segna ciò che è forte?"},"translation":{"en":"The wind is strong.","it":"Il vento è forte."}}'::jsonb, '「が」が示す主語', 'The wind is what is strong, so 風 (wind) is the subject and takes が. The predicate, the part that says something about the subject, is 強い ("is strong"): an い-adjective (an adjective that ends in い), and it takes its subject with が just like a verb. を marks the thing an action is done to, but 強い is not an action. で marks a place or a means ("at", "with"), which makes no sense here.', 'Il vento è ciò che è forte, quindi 風 (vento) è il soggetto e prende が. Il predicato, cioè la parte che dice qualcosa del soggetto, è 強い («è forte»): un aggettivo in い (un aggettivo che finisce in い), e prende il soggetto con が proprio come un verbo. を segna la cosa su cui si compie un''azione, ma 強い non è un''azione. で indica un luogo o un mezzo («in», «con»), e qui non ha senso.'),
  ('4ace08f8-064b-56e9-88f1-3f2322433a16', 'が-が示す主語', 'single-select', '{"sentence":{"kanji":"子猫が鳴いている","kana":"こねこがないている"},"answer":"が","distractors":["を","の"],"gap":{"kanji":"子猫＿鳴いている","kana":"こねこ＿ないている"},"prompt":{"en":"\"The kitten is meowing.\" Which particle marks who is meowing?","it":"«Il gattino sta miagolando.» Quale particella segna chi miagola?"},"translation":{"en":"The kitten is meowing.","it":"Il gattino sta miagolando."}}'::jsonb, '「が」が示す主語', 'Who is meowing? The kitten: it is the subject, so it takes が. 鳴いている means "is meowing" (an action going on right now). With を the kitten would become the thing being acted on, as if someone were "meowing the kitten". の links a noun to another noun ("the kitten''s ..."), but no noun follows here, only a verb.', 'Chi miagola? Il gattino: è il soggetto, quindi prende が. 鳴いている vuol dire «sta miagolando» (un''azione in corso adesso). Con を il gattino diventerebbe la cosa su cui si agisce, come se qualcuno «miagolasse il gattino». の lega un nome a un altro nome («il … del gattino»), ma qui non segue un nome: segue un verbo.'),
  ('63d65cb4-bb5e-5807-bbae-e9719fc4a814', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"朝から雨が降っている","kana":"あさからあめがふっている"},"answer":["朝から","雨が","降っている"],"alsoAccepted":[["雨が","朝から","降っている"]],"prompt":{"en":"Build: \"It has been raining since this morning.\"","it":"Componi: «Piove da stamattina.»"},"translation":{"en":"It has been raining since this morning.","it":"Piove da stamattina."},"glosses":[{"text":"朝から","reading":"あさから","meaning":{"en":"since the morning","it":"da stamattina"}},{"text":"雨が","reading":"あめが","meaning":{"en":"rain (subject)","it":"pioggia (soggetto)"}},{"text":"降っている","reading":"ふっている","meaning":{"en":"is falling","it":"sta cadendo"}}]}'::jsonb, '「が」が示す主語', 'In Japanese it is the rain itself that falls: 雨 (rain) is the subject, so it takes が, and 降っている (is falling) is the predicate, the part that says what the subject does. 朝から (since the morning) only says since when, so it takes no が. "雨が朝から降っている" is also correct: the verb has to stay at the end, but before it these pieces can change places.', 'In giapponese è la pioggia stessa che cade: 雨 (pioggia) è il soggetto, quindi prende が, e 降っている (sta cadendo) è il predicato, la parte che dice che cosa fa il soggetto. 朝から (da stamattina) dice solo da quando, quindi non prende が. Va bene anche «雨が朝から降っている»: il verbo deve restare in fondo, ma prima del verbo questi pezzi possono cambiare posto.'),
  ('03affcea-2864-54aa-ae55-d984d7397baf', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"急に電話が鳴った","kana":"きゅうにでんわがなった"},"answer":["急に","電話が","鳴った"],"alsoAccepted":[["電話が","急に","鳴った"]],"prompt":{"en":"Build: \"Suddenly the phone rang.\"","it":"Componi: «All''improvviso il telefono ha squillato.»"},"translation":{"en":"Suddenly the phone rang.","it":"All''improvviso il telefono ha squillato."},"glosses":[{"text":"急に","reading":"きゅうに","meaning":{"en":"suddenly","it":"all''improvviso"}},{"text":"電話が","reading":"でんわが","meaning":{"en":"the phone (subject)","it":"il telefono (soggetto)"}},{"text":"鳴った","reading":"なった","meaning":{"en":"rang","it":"ha squillato"}}]}'::jsonb, '「が」が示す主語', 'The phone is what rang, so 電話 (phone) is the subject and takes が. The verb 鳴った (rang) is the predicate, the part that says what the subject did, and it goes last. 急に (suddenly) only says how it happened, so it takes no が. "電話が急に鳴った" is also correct: the verb has to stay at the end, but before it these pieces can change places.', 'Il telefono è ciò che ha squillato, quindi 電話 (telefono) è il soggetto e prende が. Il verbo 鳴った (ha squillato) è il predicato, la parte che dice che cosa ha fatto il soggetto, e va alla fine. 急に (all''improvviso) dice solo come è successo, quindi non prende が. Va bene anche «電話が急に鳴った»: il verbo deve restare in fondo, ma prima del verbo questi pezzi possono cambiare posto.'),
  ('4fbbc3e8-e84f-5b8c-9b05-64fbdd0e9dbb', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"あれが富士山だ","kana":"あれがふじさんだ"},"answer":{"start":1,"end":2},"prompt":{"en":"\"That is Mount Fuji.\" Which part is the noun that says what \"that\" is?","it":"«Quello è il monte Fuji.» Quale parte è il nome che dice che cos''è «quello»?"},"translation":{"en":"That is Mount Fuji.","it":"Quello è il monte Fuji."},"glosses":[{"text":"あれが","meaning":{"en":"that one over there (subject)","it":"quello laggiù (soggetto)"}},{"text":"富士山","reading":"ふじさん","meaning":{"en":"Mount Fuji","it":"il monte Fuji"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '述語の三つの形', 'The answer is 富士山 (Mount Fuji). It is a noun, and a noun alone cannot close the sentence: it needs だ, the word for "is". Together, 富士山だ means "is Mount Fuji". This is one of the three ways a predicate (the part that says something about the subject) can end: noun + だ. あれが is the subject, "that one over there", marked by が.', 'La risposta è 富士山 (il monte Fuji). È un nome, e un nome da solo non può chiudere la frase: ha bisogno di だ, la parola per «è». Insieme, 富士山だ vuol dire «è il monte Fuji». È uno dei tre modi in cui può finire un predicato (la parte che dice qualcosa del soggetto): nome + だ. あれが è il soggetto, «quello laggiù», segnato da が.'),
  ('02e17e5f-f8a3-584d-b587-dd64ff1a548d', 'が-が示す主語', 'select-span', '{"sentence":{"kanji":"みかんが甘い","kana":"みかんがあまい"},"answer":{"start":2,"end":3},"prompt":{"en":"\"The mandarins are sweet.\" Which part shows that 甘い is an い-adjective (an adjective that ends in い)?","it":"«I mandarini sono dolci.» Quale parte mostra che 甘い è un aggettivo in い (un aggettivo che finisce in い)?"},"translation":{"en":"The mandarins are sweet.","it":"I mandarini sono dolci."},"glosses":[{"text":"みかんが","meaning":{"en":"the mandarins (subject)","it":"i mandarini (soggetto)"}},{"text":"甘","reading":"あま","meaning":{"en":"sweet (kanji of 甘い)","it":"dolce (kanji di 甘い)"}},{"text":"い","meaning":{"en":"ending of the い-adjective","it":"finale dell''aggettivo in い"}}]}'::jsonb, '述語の三つの形', 'The final い tells you that 甘い ("is sweet") is an い-adjective, one of the three ways a predicate (the part that says something about the subject) can end. An い-adjective already contains "is", so no だ follows it: 甘いだ would be wrong. みかんが is the subject, and 甘 is only the kanji at the start of the adjective.', 'La い finale ti dice che 甘い («è dolce») è un aggettivo in い, uno dei tre modi in cui può finire un predicato (la parte che dice qualcosa del soggetto). Un aggettivo in い contiene già «è», quindi dopo non va だ: 甘いだ sarebbe sbagliato. みかんが è il soggetto, e 甘 è solo il kanji all''inizio dell''aggettivo.'),
  ('1749beb5-add1-5e9e-be87-c384fdbff89a', 'が-が示す主語', 'assemble', '{"sentence":{"kanji":"庭の桜が咲いた","kana":"にわのさくらがさいた"},"answer":["庭の","桜が","咲いた"],"prompt":{"en":"Build: \"The cherry tree in the garden has bloomed.\"","it":"Componi: «Il ciliegio del giardino è fiorito.»"},"translation":{"en":"The cherry tree in the garden has bloomed.","it":"Il ciliegio del giardino è fiorito."},"glosses":[{"text":"庭の","reading":"にわの","meaning":{"en":"of the garden","it":"del giardino"}},{"text":"桜が","reading":"さくらが","meaning":{"en":"cherry tree (subject)","it":"ciliegio (soggetto)"}},{"text":"咲いた","reading":"さいた","meaning":{"en":"bloomed","it":"è fiorito"}}]}'::jsonb, '述語の三つの形', 'The subject is 桜 (cherry tree), marked by が; 庭の ("of the garden") comes right before it and says which tree. The predicate, the part that says something about the subject, is 咲いた (bloomed): a verb, one of the three ways a predicate can end. A verb is complete on its own, so no だ follows it.', 'Il soggetto è 桜 (ciliegio), segnato da が; 庭の («del giardino») viene subito prima e dice quale albero. Il predicato, cioè la parte che dice qualcosa del soggetto, è 咲いた (è fiorito): un verbo, uno dei tre modi in cui può finire un predicato. Un verbo è completo da solo, quindi dopo non va だ.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('0f32d14b-3435-526b-bbac-b35ac5c7db99', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"弟がパンを焼く","kana":"おとうとがパンをやく"},"answer":["弟が","パンを","焼く"],"prompt":{"en":"Build: \"My younger brother bakes bread.\"","it":"Componi: «Mio fratello minore cuoce il pane.»"},"translation":{"en":"My younger brother bakes bread.","it":"Mio fratello minore cuoce il pane."},"glosses":[{"text":"弟が","reading":"おとうとが","meaning":{"en":"younger brother (subject)","it":"fratello minore (soggetto)"}},{"text":"パンを","meaning":{"en":"bread (object)","it":"pane (oggetto)"}},{"text":"焼く","reading":"やく","meaning":{"en":"bakes","it":"cuoce"}}]}'::jsonb, '「を」で示す目的語', 'が marks the subject: who does the action (弟, younger brother). を marks the object: the thing the action is done to (パン, bread). The verb 焼く (bakes) comes last.', 'が segna il soggetto: chi compie l''azione (弟, il fratello minore). を segna l''oggetto: la cosa su cui si compie l''azione (パン, il pane). Il verbo 焼く (cuoce) va alla fine.'),
  ('3ac7b3aa-91eb-55f4-bd8b-99d8c49f8990', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"ピザを焼いた","kana":"ピザをやいた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the object (the thing the action is done to)?","it":"Quale parte è l''oggetto (la cosa su cui si compie l''azione)?"},"translation":{"en":"(I) baked a pizza.","it":"(Io) ho cotto una pizza."},"glosses":[{"text":"ピザを","meaning":{"en":"pizza (object)","it":"pizza (oggetto)"}},{"text":"焼","reading":"や","meaning":{"en":"bake (kanji of 焼く)","it":"cuocere (kanji di 焼く)"}},{"text":"いた","meaning":{"en":"past-tense ending of 焼く","it":"desinenza del passato di 焼く"}}]}'::jsonb, '「を」で示す目的語', 'The object is ピザを: を marks the pizza as the thing that was baked. The subject is not written, yet the sentence is complete: it is a zero pronoun, a subject that is left out but understood. With no other context it is the speaker: "I baked a pizza".', 'L''oggetto è ピザを: を segna la pizza come la cosa che è stata cotta. Il soggetto non è scritto, eppure la frase è completa: è un pronome zero, cioè un soggetto non scritto ma sottinteso. Senza altro contesto è chi parla: «ho cotto una pizza».'),
  ('aa3360be-653c-52cd-bcc5-aacdbd09a332', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"猫が魚を食べた","kana":"ねこがさかなをたべた"},"answer":"を","distractors":["が","の"],"gap":{"kanji":"猫が魚＿食べた","kana":"ねこがさかな＿たべた"},"prompt":{"en":"\"The cat ate the fish.\" Which particle marks what was eaten?","it":"«Il gatto ha mangiato il pesce.» Quale particella segna ciò che è stato mangiato?"},"translation":{"en":"The cat ate the fish.","it":"Il gatto ha mangiato il pesce."}}'::jsonb, '「を」で示す目的語', 'The fish is what gets eaten, so it is the object and takes を. が is already on 猫 (cat), the one who eats. の joins two nouns ("the fish''s …"), but here a verb follows.', 'Il pesce è ciò che viene mangiato, quindi è l''oggetto e prende を. が è già su 猫 (il gatto), chi mangia. の unisce due nomi («il … del pesce»), ma qui segue un verbo.'),
  ('0cde5b10-898c-581d-9750-a83dbf5ad084', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"もう八時だ","kana":"もうはちじだ"},"answer":{"start":2,"end":3},"prompt":{"en":"No subject is written. Which part means \"is\"?","it":"Il soggetto non è scritto. Quale parte vuol dire «è»?"},"translation":{"en":"It''s already eight o''clock.","it":"Sono già le otto."},"glosses":[{"text":"もう","meaning":{"en":"already","it":"già"}},{"text":"八時","reading":"はちじ","meaning":{"en":"eight o''clock","it":"le otto"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, 'ゼロ代名詞', 'だ means "is": 八時だ means "(it) is eight o''clock". No subject is written, and none is needed: the subject is a zero pronoun, left out but understood. Here the situation makes it clear: the current time.', 'だ vuol dire «è»: 八時だ vuol dire «sono le otto». Il soggetto non è scritto, e non serve: è un pronome zero, cioè un soggetto sottinteso. Qui lo chiarisce la situazione: l''ora attuale.'),
  ('e9ac22ea-8073-5d03-a921-43dbccd1614e', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"毎晩日記を書く","kana":"まいばんにっきをかく"},"answer":["毎晩","日記を","書く"],"alsoAccepted":[["日記を","毎晩","書く"]],"prompt":{"en":"Build: \"(I) write in my diary every night.\"","it":"Componi: «(Io) scrivo il diario ogni sera.»"},"translation":{"en":"(I) write in my diary every night.","it":"(Io) scrivo il diario ogni sera."},"glosses":[{"text":"毎晩","reading":"まいばん","meaning":{"en":"every night","it":"ogni sera"}},{"text":"日記を","reading":"にっきを","meaning":{"en":"diary (object)","it":"diario (oggetto)"}},{"text":"書く","reading":"かく","meaning":{"en":"write","it":"scrivo"}}]}'::jsonb, 'ゼロ代名詞', 'There is no が, yet someone is writing. The subject of 書く (write) is a zero pronoun: not written, but understood. With no other context it is the speaker: "I write…". "日記を毎晩書く" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Non c''è nessun が, eppure qualcuno scrive. Il soggetto di 書く (scrivere) è un pronome zero: non è scritto, ma è sottinteso. Senza altro contesto è chi parla: «(io) scrivo…». Va bene anche «日記を毎晩書く»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('579c5b10-3119-59bc-8ed4-87dd1c948f35', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"窓を開ける","kana":"まどをあける"},"answer":"を","distractors":["が","で"],"gap":{"kanji":"窓＿開ける","kana":"まど＿あける"},"prompt":{"en":"\"(I) open the window.\" Which particle marks the window?","it":"«(Io) apro la finestra.» Quale particella segna la finestra?"},"translation":{"en":"(I) open the window.","it":"(Io) apro la finestra."}}'::jsonb, 'ゼロ代名詞', '窓 (window) is the thing being opened, so it is the object and takes を. With が the window would become the subject, the one doing the opening. で marks a place or a means ("at", "with"), not the thing being opened. The real subject, the person who opens it, is a zero pronoun: not written but understood ("I").', '窓 (finestra) è la cosa che viene aperta, quindi è l''oggetto e prende を. Con が la finestra diventerebbe il soggetto, cioè chi apre. で indica un luogo o un mezzo («in», «con»), non la cosa che si apre. Il vero soggetto, la persona che apre, è un pronome zero: non è scritto ma è sottinteso («io»).'),
  ('e6a8429c-f309-59ac-b715-e0021dc6bbf1', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"母が手紙を読んだ","kana":"ははがてがみをよんだ"},"answer":"を","distractors":["が","で"],"gap":{"kanji":"母が手紙＿読んだ","kana":"ははがてがみ＿よんだ"},"prompt":{"en":"\"My mother read the letter.\" Which particle marks what was read?","it":"«Mia madre ha letto la lettera.» Quale particella segna ciò che è stato letto?"},"translation":{"en":"My mother read the letter.","it":"Mia madre ha letto la lettera."}}'::jsonb, '「を」で示す目的語', 'The letter is the thing being read, so it is the object and takes を. が is already on 母 (mother), the one who reads. で marks the place or the means of an action ("at", "with"), not the thing that is read.', 'La lettera è la cosa che viene letta, quindi è l''oggetto e prende を. が è già su 母 (la madre), chi legge. で indica il luogo o il mezzo dell''azione («in», «con»), non la cosa letta.'),
  ('86643edb-f4c4-5d4c-9ff6-3bfd9ec2df0f', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"顔を洗った","kana":"かおをあらった"},"answer":"を","distractors":["が","に"],"gap":{"kanji":"顔＿洗った","kana":"かお＿あらった"},"prompt":{"en":"\"(I) washed my face.\" Which particle goes after 顔 (face)?","it":"«(Io) mi sono lavato la faccia.» Quale particella va dopo 顔 (faccia)?"},"translation":{"en":"(I) washed my face.","it":"(Io) mi sono lavato la faccia."}}'::jsonb, 'ゼロ代名詞', 'The face is the thing being washed, so it takes を, the particle of the object. The one who washes is not written: it is a zero pronoun, understood from the context (here, the speaker). With が, the face itself would be doing the washing, which makes no sense. に marks where something ends up ("to", "into"), not the thing you wash.', 'La faccia è la cosa che viene lavata, quindi prende を, la particella dell''oggetto. Chi lava non è scritto: è un pronome zero, sottinteso dal contesto (qui, chi parla). Con が sarebbe la faccia stessa a lavare, e non ha senso. に indica dove va a finire qualcosa («a», «in»), non la cosa che si lava.'),
  ('d55bbe36-3e6d-5b4d-b98f-2ddcf45e4e0b', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"このカメラを買った","kana":"このカメラをかった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the object?","it":"Quale parte è l''oggetto?"},"translation":{"en":"(I) bought this camera.","it":"(Io) ho comprato questa macchina fotografica."},"glosses":[{"text":"このカメラを","meaning":{"en":"this camera (object)","it":"questa macchina fotografica (oggetto)"}},{"text":"買","reading":"か","meaning":{"en":"buy (kanji of 買う)","it":"comprare (kanji di 買う)"}},{"text":"った","meaning":{"en":"past-tense ending","it":"desinenza del passato"}}]}'::jsonb, '「を」で示す目的語', 'The object is このカメラを: the camera is the thing that was bought, and を comes right after it. The one who bought it is not written; with no other context it is the speaker: "I bought this camera".', 'L''oggetto è このカメラを: la macchina fotografica è la cosa comprata, e を viene subito dopo. Chi l''ha comprata non è scritto; senza altro contesto è chi parla: «ho comprato questa macchina fotografica».'),
  ('fc98755a-2a0e-5e18-9ab8-71ae24c76328', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"いつもラジオを聞く","kana":"いつもラジオをきく"},"answer":["いつも","ラジオを","聞く"],"alsoAccepted":[["ラジオを","いつも","聞く"]],"prompt":{"en":"Build: \"(I) always listen to the radio.\"","it":"Componi: «(Io) ascolto sempre la radio.»"},"translation":{"en":"(I) always listen to the radio.","it":"(Io) ascolto sempre la radio."},"glosses":[{"text":"いつも","meaning":{"en":"always","it":"sempre"}},{"text":"ラジオを","meaning":{"en":"radio (object)","it":"radio (oggetto)"}},{"text":"聞く","reading":"きく","meaning":{"en":"listen","it":"ascolto"}}]}'::jsonb, 'ゼロ代名詞', 'No subject is written: the one who listens is a zero pronoun, understood as the speaker. ラジオ (radio) is the object, so it takes を, and the verb 聞く (listen) comes last. いつも (always) only says how often. "ラジオをいつも聞く" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Il soggetto non è scritto: chi ascolta è un pronome zero, sottinteso come chi parla. ラジオ (radio) è l''oggetto, quindi prende を, e il verbo 聞く (ascoltare) va alla fine. いつも (sempre) dice solo quanto spesso. Va bene anche «ラジオをいつも聞く»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('71f30db7-cbcd-5181-8929-f6a950c6e501', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"まだ火曜日だ","kana":"まだかようびだ"},"answer":{"start":1,"end":2},"prompt":{"en":"\"It''s still Tuesday.\" No subject is written. Which part says what day it is?","it":"«È ancora martedì.» Il soggetto non è scritto. Quale parte dice che giorno è?"},"translation":{"en":"It''s still Tuesday.","it":"È ancora martedì."},"glosses":[{"text":"まだ","meaning":{"en":"still","it":"ancora"}},{"text":"火曜日","reading":"かようび","meaning":{"en":"Tuesday","it":"martedì"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, 'ゼロ代名詞', 'The answer is 火曜日 (Tuesday): with だ, the word for "is", it becomes 火曜日だ, "(it) is Tuesday". No word says what is Tuesday, and none is needed: the subject is a zero pronoun, a subject that is left out but understood. From the situation, it is today. まだ only adds "still".', 'La risposta è 火曜日 (martedì): con だ, la parola per «è», diventa 火曜日だ, «è martedì». Nessuna parola dice che cosa è martedì, e non serve: il soggetto è un pronome zero, cioè un soggetto non scritto ma sottinteso. Dalla situazione si capisce che è oggi. まだ aggiunge solo «ancora».'),
  ('85331300-10d1-59d5-ad44-d94493d05ad3', 'ゼロ代名詞', 'select-span', '{"sentence":{"kanji":"ちょっと眠い","kana":"ちょっとねむい"},"answer":{"start":0,"end":1},"prompt":{"en":"\"(I''m) a bit sleepy.\" No subject is written. Which part means \"a bit\"?","it":"«Ho un po'' sonno.» Il soggetto non è scritto. Quale parte vuol dire «un po''»?"},"translation":{"en":"(I''m) a bit sleepy.","it":"(Io) ho un po'' sonno."},"glosses":[{"text":"ちょっと","meaning":{"en":"a bit","it":"un po''"}},{"text":"眠","reading":"ねむ","meaning":{"en":"sleepy (kanji of 眠い)","it":"assonnato (kanji di 眠い)"}},{"text":"い","meaning":{"en":"ending of the い-adjective","it":"finale dell''aggettivo in い"}}]}'::jsonb, 'ゼロ代名詞', 'The answer is ちょっと (a bit). The rest, 眠い, means "is sleepy", and it is a complete sentence even without a subject. Who is sleepy? It is not written: it is a zero pronoun, a subject that is left out but understood. Here it is the speaker: said like this, on its own, 眠い is about yourself, because only you can feel your own sleepiness directly.', 'La risposta è ちょっと (un po''). Il resto, 眠い, vuol dire «è assonnato», ed è una frase completa anche senza soggetto. Chi ha sonno? Non è scritto: è un pronome zero, cioè un soggetto non scritto ma sottinteso. Qui è chi parla: detto così, da solo, 眠い si dice di sé stessi, perché solo tu senti direttamente il tuo sonno.'),
  ('7997c920-f109-599d-b054-31f24714a1b4', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"いい天気だ","kana":"いいてんきだ"},"answer":"だ","distractors":["が","を"],"gap":{"kanji":"いい天気＿","kana":"いいてんき＿"},"prompt":{"en":"\"It''s nice weather.\" What goes at the end?","it":"«È bel tempo.» Che cosa va alla fine?"},"translation":{"en":"It''s nice weather.","it":"È bel tempo."}}'::jsonb, 'ゼロ代名詞', '天気 (weather) is a noun, and a noun needs だ, the word for "is", to close the sentence: いい天気だ, "(it) is nice weather". No subject is needed: it is a zero pronoun, left out but understood (the weather right now). が and を are particles that mark the role of a noun; they cannot end the sentence, and with が the weather would become a subject with nothing said about it.', '天気 (il tempo atmosferico) è un nome, e un nome ha bisogno di だ, la parola per «è», per chiudere la frase: いい天気だ, «è bel tempo». Il soggetto non serve: è un pronome zero, cioè non scritto ma sottinteso (il tempo di adesso). が e を sono particelle che indicano il ruolo di un nome: non possono chiudere la frase, e con が il tempo diventerebbe un soggetto di cui poi non si dice niente.'),
  ('92e1a7be-2af8-52ce-980b-f9947ea276d7', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"父が車を洗っている","kana":"ちちがくるまをあらっている"},"answer":["父が","車を","洗っている"],"prompt":{"en":"Build: \"My father is washing the car.\"","it":"Componi: «Mio padre sta lavando la macchina.»"},"translation":{"en":"My father is washing the car.","it":"Mio padre sta lavando la macchina."},"glosses":[{"text":"父が","reading":"ちちが","meaning":{"en":"my father (subject)","it":"mio padre (soggetto)"}},{"text":"車を","reading":"くるまを","meaning":{"en":"the car (object)","it":"la macchina (oggetto)"}},{"text":"洗っている","reading":"あらっている","meaning":{"en":"is washing","it":"sta lavando"}}]}'::jsonb, '「を」で示す目的語', 'Each particle shows a role. が marks the subject, the one doing the action (父, my father). を marks the object, the thing the action is done to (車, the car). The verb 洗っている (is washing) comes last. If you swapped the particles (車が, 父を), it would be the car washing my father.', 'Ogni particella indica un ruolo. が segna il soggetto, chi compie l''azione (父, mio padre). を segna l''oggetto, la cosa su cui si compie l''azione (車, la macchina). Il verbo 洗っている (sta lavando) va alla fine. Se scambiassi le particelle (車が, 父を), sarebbe la macchina a lavare mio padre.'),
  ('6889bdad-e57f-5150-9a97-b8ff03eedf5d', 'ゼロ代名詞', 'assemble', '{"sentence":{"kanji":"祖母が毎晩みそ汁を作る","kana":"そぼがまいばんみそしるをつくる"},"answer":["祖母が","毎晩","みそ汁を","作る"],"alsoAccepted":[["毎晩","祖母が","みそ汁を","作る"],["祖母が","みそ汁を","毎晩","作る"]],"prompt":{"en":"Build: \"My grandmother makes miso soup every evening.\"","it":"Componi: «Mia nonna prepara la zuppa di miso ogni sera.»"},"translation":{"en":"My grandmother makes miso soup every evening.","it":"Mia nonna prepara la zuppa di miso ogni sera."},"glosses":[{"text":"祖母が","reading":"そぼが","meaning":{"en":"my grandmother (subject)","it":"mia nonna (soggetto)"}},{"text":"毎晩","reading":"まいばん","meaning":{"en":"every evening","it":"ogni sera"}},{"text":"みそ汁を","reading":"みそしるを","meaning":{"en":"miso soup (object)","it":"zuppa di miso (oggetto)"}},{"text":"作る","reading":"つくる","meaning":{"en":"makes","it":"prepara"}}]}'::jsonb, '「を」で示す目的語', 'みそ汁 (miso soup) is the thing being made, so it is the object and takes を. The one who makes it, 祖母 (my grandmother), is the subject and takes が. 毎晩 (every evening) only says when, so it takes no particle. "毎晩祖母がみそ汁を作る" and "祖母がみそ汁を毎晩作る" are also correct: the verb has to stay at the end, but before it these pieces can change places.', 'みそ汁 (zuppa di miso) è la cosa che viene preparata, quindi è l''oggetto e prende を. Chi la prepara, 祖母 (mia nonna), è il soggetto e prende が. 毎晩 (ogni sera) dice solo quando, quindi non prende particelle. Vanno bene anche «毎晩祖母がみそ汁を作る» e «祖母がみそ汁を毎晩作る»: il verbo deve restare in fondo, ma prima del verbo questi pezzi possono cambiare posto.'),
  ('631ec3ea-1c34-5259-81e3-19d8e3a5a126', 'ゼロ代名詞', 'single-select', '{"sentence":{"kanji":"店員がドアを閉めた","kana":"てんいんがドアをしめた"},"answer":"を","distractors":["が","に"],"gap":{"kanji":"店員がドア＿閉めた","kana":"てんいんがドア＿しめた"},"prompt":{"en":"\"The shop assistant closed the door.\" Which particle marks what was closed?","it":"«Il commesso ha chiuso la porta.» Quale particella segna ciò che è stato chiuso?"},"translation":{"en":"The shop assistant closed the door.","it":"Il commesso ha chiuso la porta."}}'::jsonb, '「を」で示す目的語', 'The door is the thing being closed, so it is the object and takes を. が is already on 店員 (the shop assistant), the one who does the closing; with ドアが the door would also look like someone doing the closing. に marks where something ends up ("to", "into"), not the thing you act on.', 'La porta è la cosa che viene chiusa, quindi è l''oggetto e prende を. が è già su 店員 (il commesso), chi chiude; con ドアが anche la porta sembrerebbe qualcuno che chiude. に indica dove va a finire qualcosa («a», «in»), non la cosa su cui si agisce.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('18239c82-53c0-5b50-b5ea-1ea27f2ef47b', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"これは私の傘だ","kana":"これはわたしのかさだ"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the topic (what the sentence is about)?","it":"Quale parte è il tema (ciò di cui si parla)?"},"translation":{"en":"This is my umbrella.","it":"Questo è il mio ombrello."},"glosses":[{"text":"これは","meaning":{"en":"this (topic)","it":"questo (tema)"}},{"text":"私の傘","reading":"わたしのかさ","meaning":{"en":"my umbrella","it":"il mio ombrello"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '「は」が示す主題', 'The topic is これは: は marks what the sentence is about, "as for this…". は does not say who does what; it only announces the topic. The rest, 私の傘だ, says something about it: "is my umbrella".', 'Il tema è これは: は segna ciò di cui parla la frase, «quanto a questo…». は non dice chi fa che cosa: annuncia solo l''argomento. Il resto, 私の傘だ, dice qualcosa del tema: «è il mio ombrello».'),
  ('4a486ed2-e831-53d7-bb03-619e7e55f5e5', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"東京は人が多い","kana":"とうきょうはひとがおおい"},"answer":"は","distractors":["を","へ"],"gap":{"kanji":"東京＿人が多い","kana":"とうきょう＿ひとがおおい"},"prompt":{"en":"\"As for Tokyo, there are many people.\" Which particle marks Tokyo?","it":"«Quanto a Tokyo, ci sono molte persone.» Quale particella segna Tokyo?"},"translation":{"en":"As for Tokyo, there are many people.","it":"Quanto a Tokyo, ci sono molte persone."}}'::jsonb, '「は」が示す主題', 'Tokyo is not the subject: what is "many" is the people, 人, already marked by が. Tokyo is the topic, what the sentence is about ("as for Tokyo"), and the topic takes は. を marks an object and へ a direction; neither fits here.', 'Tokyo non è il soggetto: a essere molte sono le persone (人), già segnate da が. Tokyo è il tema, ciò di cui si parla («quanto a Tokyo»), e il tema prende は. を segna un oggetto e へ una direzione: qui non vanno bene.'),
  ('8bd02c8c-712f-5b02-950e-c60858e8f452', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"私は毎日コーヒーを飲む","kana":"わたしはまいにちコーヒーをのむ"},"answer":["私は","毎日","コーヒーを","飲む"],"alsoAccepted":[["毎日","私は","コーヒーを","飲む"],["私は","コーヒーを","毎日","飲む"]],"prompt":{"en":"Build: \"I drink coffee every day.\"","it":"Componi: «Bevo caffè ogni giorno.»"},"translation":{"en":"I drink coffee every day.","it":"Bevo caffè ogni giorno."},"glosses":[{"text":"私は","reading":"わたしは","meaning":{"en":"I (topic)","it":"io (tema)"}},{"text":"毎日","reading":"まいにち","meaning":{"en":"every day","it":"ogni giorno"}},{"text":"コーヒーを","meaning":{"en":"coffee (object)","it":"caffè (oggetto)"}},{"text":"飲む","reading":"のむ","meaning":{"en":"drink","it":"bevo"}}]}'::jsonb, '「は」が示す主題', '私は is the topic: "as for me". は says what the sentence is about, not who does the action; here it is simply clear that I am the one who drinks. コーヒー (coffee) is the object, so it takes を. "毎日私はコーヒーを飲む" and "私はコーヒーを毎日飲む" are also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '私は è il tema: «quanto a me». は dice di che cosa parla la frase, non chi compie l''azione; qui è semplicemente chiaro che sono io a bere. コーヒー (caffè) è l''oggetto, quindi prende を. Vanno bene anche «毎日私はコーヒーを飲む» e «私はコーヒーを毎日飲む»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('61e926e3-590c-5339-9425-120cfbbb25da', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"ポストに手紙を入れた","kana":"ポストにてがみをいれた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says where the letter ends up?","it":"Quale parte dice dove finisce la lettera?"},"translation":{"en":"(I) put the letter in the postbox.","it":"(Io) ho messo la lettera nella buca delle lettere."},"glosses":[{"text":"ポストに","meaning":{"en":"into the postbox (destination)","it":"nella buca (destinazione)"}},{"text":"手紙を入","reading":"てがみをい","meaning":{"en":"letter (object), 入 of 入れる","it":"lettera (oggetto), 入 di 入れる"}},{"text":"れた","meaning":{"en":"rest of 入れた (past)","it":"resto di 入れた (passato)"}}]}'::jsonb, '到達点を示す「に」', 'The answer is ポストに. に marks the destination: the place where the action ends up (here, inside the postbox). The letter is the object, with を.', 'La risposta è ポストに. に segna la destinazione: il punto in cui l''azione va a finire (qui, dentro la buca delle lettere). La lettera è l''oggetto, con を.'),
  ('f1d776a4-259a-5651-914b-90de125c1c1c', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"先生に花をあげた","kana":"せんせいにはなをあげた"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"先生＿花をあげた","kana":"せんせい＿はなをあげた"},"prompt":{"en":"\"I gave flowers to the teacher.\" Which particle marks the person who receives them?","it":"«Ho dato dei fiori all''insegnante.» Quale particella segna chi li riceve?"},"translation":{"en":"I gave flowers to the teacher.","it":"Ho dato dei fiori all''insegnante."}}'::jsonb, '到達点を示す「に」', 'The teacher is the person the flowers go to. に marks where something arrives, and that includes a person who receives it. 花 (flowers) is the thing given, so it already has を.', 'L''insegnante è la persona a cui vanno i fiori. に segna dove arriva qualcosa, anche quando è una persona che lo riceve. 花 (fiori) è la cosa data, quindi ha già を.'),
  ('34bfcd4c-14f4-5e5a-86c3-764f90e7c57a', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"姉が友達に手紙を送った","kana":"あねがともだちにてがみをおくった"},"answer":["姉が","友達に","手紙を","送った"],"alsoAccepted":[["姉が","手紙を","友達に","送った"]],"prompt":{"en":"Build: \"My older sister sent a letter to a friend.\"","it":"Componi: «Mia sorella maggiore ha spedito una lettera a un amico.»"},"translation":{"en":"My older sister sent a letter to a friend.","it":"Mia sorella maggiore ha spedito una lettera a un amico."},"glosses":[{"text":"姉が","reading":"あねが","meaning":{"en":"older sister (subject)","it":"sorella maggiore (soggetto)"}},{"text":"友達に","reading":"ともだちに","meaning":{"en":"to a friend","it":"a un amico"}},{"text":"手紙を","reading":"てがみを","meaning":{"en":"letter (object)","it":"lettera (oggetto)"}},{"text":"送った","reading":"おくった","meaning":{"en":"sent","it":"ha spedito"}}]}'::jsonb, '到達点を示す「に」', 'Each particle shows a role: が who sends (姉, older sister), に who the letter goes to (友達, a friend), を what is sent (手紙, a letter). Because the particles show the roles, 手紙を can also come before 友達に with the same meaning: both orders are correct.', 'Ogni particella indica un ruolo: が chi spedisce (姉, la sorella maggiore), に a chi va la lettera (友達, un amico), を che cosa si spedisce (手紙, una lettera). Poiché i ruoli li danno le particelle, 手紙を può anche venire prima di 友達に con lo stesso significato: tutti e due gli ordini sono giusti.'),
  ('1e706b10-234a-58f5-8475-806e623c27ab', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"この本は高い","kana":"このほんはたかい"},"answer":"は","distractors":["を","に"],"gap":{"kanji":"この本＿高い","kana":"このほん＿たかい"},"prompt":{"en":"\"This book is expensive.\" Which particle marks what the sentence is about?","it":"«Questo libro è caro.» Quale particella segna ciò di cui si parla?"},"translation":{"en":"This book is expensive.","it":"Questo libro è caro."}}'::jsonb, '「は」が示す主題', 'The sentence is about this book, so この本 is the topic and takes は. The predicate 高い ("is expensive") then says something about it. を marks an object and に a destination: neither goes with an adjective like 高い.', 'La frase parla di questo libro, quindi この本 è il tema e prende は. Il predicato 高い («è caro») dice poi qualcosa del tema. を segna un oggetto e に una destinazione: nessuna delle due va con un aggettivo come 高い.'),
  ('569f7a67-1ab8-53bf-9b64-7e06448425b4', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"駅に着いた","kana":"えきについた"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"駅＿着いた","kana":"えき＿ついた"},"prompt":{"en":"\"(I) arrived at the station.\" Which particle marks where (I) arrived?","it":"«(Io) sono arrivato alla stazione.» Quale particella segna dove sono arrivato?"},"translation":{"en":"(I) arrived at the station.","it":"(Io) sono arrivato alla stazione."}}'::jsonb, '到達点を示す「に」', 'The station is where the movement ends, its destination, so it takes に. With を the station would be the thing acted on. で marks where an action takes place, not where you arrive.', 'La stazione è il punto in cui finisce lo spostamento, la destinazione, quindi prende に. Con を la stazione sarebbe la cosa su cui si agisce. で indica dove si svolge un''azione, non dove si arriva.'),
  ('8bef3929-c4d1-519e-9b36-6a254724d7d3', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"テストは明日だ","kana":"テストはあしただ"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says what the sentence is about?","it":"Quale parte dice di che cosa parla la frase?"},"translation":{"en":"The test is tomorrow.","it":"L''esame è domani."},"glosses":[{"text":"テストは","meaning":{"en":"the test (topic)","it":"l''esame (tema)"}},{"text":"明日","reading":"あした","meaning":{"en":"tomorrow","it":"domani"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '「は」が示す主題', 'The topic is テストは: the sentence is about the test, and は marks it. The rest, 明日だ, says something about the topic: "is tomorrow". だ is the word for "is" that links the topic to a noun (明日, tomorrow).', 'Il tema è テストは: la frase parla dell''esame, e は lo segna. Il resto, 明日だ, dice qualcosa del tema: «è domani». だ è la parola per «è» che collega il tema a un nome (明日, domani).'),
  ('6065d965-6f9e-5372-972d-4eb4310df00f', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"子どもが部屋に入った","kana":"こどもがへやにはいった"},"answer":["子どもが","部屋に","入った"],"alsoAccepted":[["部屋に","子どもが","入った"]],"prompt":{"en":"Build: \"The child went into the room.\"","it":"Componi: «Il bambino è entrato nella stanza.»"},"translation":{"en":"The child went into the room.","it":"Il bambino è entrato nella stanza."},"glosses":[{"text":"子どもが","reading":"こどもが","meaning":{"en":"the child (subject)","it":"il bambino (soggetto)"}},{"text":"部屋に","reading":"へやに","meaning":{"en":"into the room (destination)","it":"nella stanza (destinazione)"}},{"text":"入った","reading":"はいった","meaning":{"en":"went in","it":"è entrato"}}]}'::jsonb, '到達点を示す「に」', 'が marks the subject, the one who moves (子ども, child). に marks the destination, the place where the movement ends (部屋, room). The verb 入った (went in) comes last. "部屋に子どもが入った" is also correct: the particles show the roles, so the place can come first.', 'が segna il soggetto, chi si muove (子ども, il bambino). に segna la destinazione, il luogo in cui finisce lo spostamento (部屋, la stanza). Il verbo 入った (è entrato) va alla fine. Va bene anche «部屋に子どもが入った»: i ruoli li danno le particelle, quindi il luogo può venire per primo.'),
  ('fb53b90e-0c6a-5051-ab1a-5976dfdfb0a0', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"この町は冬が長い","kana":"このまちはふゆがながい"},"answer":["この町は","冬が","長い"],"prompt":{"en":"Build: \"In this town, winter is long.\" Start with the topic.","it":"Componi: «In questa città l''inverno è lungo.» Comincia dal tema."},"translation":{"en":"In this town, winter is long.","it":"In questa città l''inverno è lungo."},"glosses":[{"text":"この町は","reading":"このまちは","meaning":{"en":"this town (topic)","it":"questa città (tema)"}},{"text":"冬が","reading":"ふゆが","meaning":{"en":"winter (subject)","it":"l''inverno (soggetto)"}},{"text":"長い","reading":"ながい","meaning":{"en":"is long","it":"è lungo"}}]}'::jsonb, '「は」が示す主題', 'この町は is the topic, what the sentence is about: "as for this town". What is long is the winter, so 冬 (winter) is the subject and takes が. 長い ("is long") is the predicate, the part that says something about the subject. は sets the scene first; が then points to what the predicate describes.', 'この町は è il tema, ciò di cui parla la frase: «quanto a questa città». A essere lungo è l''inverno, quindi 冬 (inverno) è il soggetto e prende が. 長い («è lungo») è il predicato, la parte che dice qualcosa del soggetto. は prepara prima la scena; が poi indica di che cosa parla il predicato.'),
  ('0893efd4-8643-5c4c-acb2-2dbde67a81f5', 'は-が示す主題', 'assemble', '{"sentence":{"kanji":"日曜日は図書館が休みだ","kana":"にちようびはとしょかんがやすみだ"},"answer":["日曜日は","図書館が","休み","だ"],"prompt":{"en":"Build: \"On Sundays, the library is closed.\"","it":"Componi: «La domenica la biblioteca è chiusa.»"},"translation":{"en":"On Sundays, the library is closed.","it":"La domenica la biblioteca è chiusa."},"glosses":[{"text":"日曜日は","reading":"にちようびは","meaning":{"en":"Sundays (topic)","it":"la domenica (tema)"}},{"text":"図書館が","reading":"としょかんが","meaning":{"en":"the library (subject)","it":"la biblioteca (soggetto)"}},{"text":"休み","reading":"やすみ","meaning":{"en":"a day off, closed","it":"giorno di chiusura, chiuso"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '「は」が示す主題', '日曜日は is the topic: "as for Sundays". は announces what we are talking about, even though Sunday itself does nothing. The subject is 図書館 (the library), with が: it is the library that is closed. 休み (a day off) is a noun, so it needs だ, the word for "is", at the end.', '日曜日は è il tema: «quanto alla domenica». は annuncia di che cosa si parla, anche se la domenica di per sé non fa niente. Il soggetto è 図書館 (la biblioteca), con が: è la biblioteca a essere chiusa. 休み (giorno di chiusura) è un nome, quindi alla fine ha bisogno di だ, la parola per «è».'),
  ('6c0f7c03-f951-5cc5-961f-a3b3a064e0a3', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"この部屋は窓が大きい","kana":"このへやはまどがおおきい"},"answer":"は","distractors":["を","に"],"gap":{"kanji":"この部屋＿窓が大きい","kana":"このへや＿まどがおおきい"},"prompt":{"en":"\"This room has big windows.\" Which particle marks what the sentence is about?","it":"«Questa stanza ha finestre grandi.» Quale particella segna ciò di cui si parla?"},"translation":{"en":"This room has big windows.","it":"Questa stanza ha finestre grandi."}}'::jsonb, '「は」が示す主題', 'The sentence is about this room, so この部屋 is the topic and takes は: "as for this room". What is big is the windows, 窓, already marked by が. を marks the thing an action is done to, but 大きい ("is big") is not an action. に marks where something ends up, and nothing is moving here.', 'La frase parla di questa stanza, quindi この部屋 è il tema e prende は: «quanto a questa stanza». A essere grandi sono le finestre, 窓, già segnate da が. を segna la cosa su cui si compie un''azione, ma 大きい («è grande») non è un''azione. に indica dove va a finire qualcosa, e qui niente si sposta.'),
  ('1bff88fa-b19a-5d14-bc7d-c1d86cd2ed96', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"ベッドに猫が乗った","kana":"ベッドにねこがのった"},"answer":{"start":0,"end":1},"prompt":{"en":"\"The cat got onto the bed.\" Which part says where the cat ended up?","it":"«Il gatto è salito sul letto.» Quale parte dice dove è finito il gatto?"},"translation":{"en":"The cat got onto the bed.","it":"Il gatto è salito sul letto."},"glosses":[{"text":"ベッドに","meaning":{"en":"onto the bed (destination)","it":"sul letto (destinazione)"}},{"text":"猫が乗","reading":"ねこがの","meaning":{"en":"the cat (subject), 乗 of 乗る","it":"il gatto (soggetto), 乗 di 乗る"}},{"text":"った","meaning":{"en":"rest of 乗った (past)","it":"resto di 乗った (passato)"}}]}'::jsonb, '到達点を示す「に」', 'The answer is ベッドに. に marks the destination, the point where a movement ends: the cat climbed up and ended up on the bed. 猫が is the subject, the one who moves. The place with に can come first in the sentence: it is the particle, not the position, that shows its role.', 'La risposta è ベッドに. に segna la destinazione, il punto in cui finisce un movimento: il gatto è salito ed è finito sul letto. 猫が è il soggetto, chi si muove. Il luogo con に può stare all''inizio della frase: il ruolo lo indica la particella, non la posizione.'),
  ('b836debc-020b-53fa-86ce-9ef262d4710b', 'は-が示す主題', 'select-span', '{"sentence":{"kanji":"カレンダーに予定を書いた","kana":"カレンダーによていをかいた"},"answer":{"start":0,"end":1},"prompt":{"en":"\"(I) wrote the appointment on the calendar.\" Which part says where the writing ends up?","it":"«(Io) ho scritto l''impegno sul calendario.» Quale parte dice dove finisce ciò che ho scritto?"},"translation":{"en":"(I) wrote the appointment on the calendar.","it":"(Io) ho scritto l''impegno sul calendario."},"glosses":[{"text":"カレンダーに","meaning":{"en":"on the calendar (destination)","it":"sul calendario (destinazione)"}},{"text":"予定を書","reading":"よていをか","meaning":{"en":"appointment (object), 書 of 書く","it":"impegno (oggetto), 書 di 書く"}},{"text":"いた","meaning":{"en":"rest of 書いた (past)","it":"resto di 書いた (passato)"}}]}'::jsonb, '到達点を示す「に」', 'The answer is カレンダーに. に marks the destination, the place where the action ends up: what I wrote lands on the calendar. 予定 (the appointment) is the thing written, so it takes を. The one who writes is not mentioned; with no other context it is the speaker.', 'La risposta è カレンダーに. に segna la destinazione, il punto in cui va a finire l''azione: ciò che ho scritto finisce sul calendario. 予定 (l''impegno) è la cosa scritta, quindi prende を. Chi scrive non è nominato; senza altro contesto è chi parla.'),
  ('e25dfd07-fd73-54fe-9996-5b51770eb4a0', 'は-が示す主題', 'single-select', '{"sentence":{"kanji":"鳥が屋根に止まった","kana":"とりがやねにとまった"},"answer":"に","distractors":["を","が"],"gap":{"kanji":"鳥が屋根＿止まった","kana":"とりがやね＿とまった"},"prompt":{"en":"\"A bird landed on the roof.\" Which particle marks where the bird landed?","it":"«Un uccello si è posato sul tetto.» Quale particella segna dove si è posato l''uccello?"},"translation":{"en":"A bird landed on the roof.","it":"Un uccello si è posato sul tetto."}}'::jsonb, '到達点を示す「に」', 'The roof is where the bird''s flight ends, its destination, so it takes に. With を the roof would be the thing acted on, as if the bird were doing something to the roof. が is already on 鳥 (bird), the one who lands; with 屋根が the roof would also become a subject, which makes no sense here.', 'Il tetto è il punto in cui finisce il volo dell''uccello, la destinazione, quindi prende に. Con を il tetto sarebbe la cosa su cui si agisce, come se l''uccello facesse qualcosa al tetto. が è già su 鳥 (uccello), chi si posa; con 屋根が anche il tetto diventerebbe un soggetto, e qui non ha senso.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('b7d38cc8-562b-59dd-92df-b6599109a919', '非過去形', 'single-select', '{"sentence":{"kanji":"明日は雨が降る","kana":"あしたはあめがふる"},"answer":"降る","distractors":["降った","降っていた"],"gap":{"kanji":"明日は雨が＿","kana":"あしたはあめが＿"},"prompt":{"en":"\"It will rain tomorrow.\" Which verb form fits?","it":"«Domani pioverà.» Quale forma del verbo è giusta?"},"translation":{"en":"It will rain tomorrow.","it":"Domani pioverà."},"glosses":[{"text":"降る","reading":"ふる"},{"text":"降った","reading":"ふった"},{"text":"降っていた","reading":"ふっていた"}]}'::jsonb, '非過去形', '降る is the dictionary form (the basic form of the verb, the one you find in a dictionary). It is a non-past tense: it covers the future and habits, not only "now". With 明日 (tomorrow) it means "it will rain"; a past form like 降った cannot go with tomorrow.', '降る è la forma del dizionario (la forma base del verbo, quella che trovi sul dizionario). È un tempo non passato: vale per il futuro e per le abitudini, non solo per «adesso». Con 明日 (domani) significa «pioverà»; un passato come 降った non può stare con domani.'),
  ('3ed770d8-53e8-583b-9402-cdba8605fcb4', '非過去形', 'single-select', '{"sentence":{"kanji":"父が新聞を読んでいる","kana":"ちちがしんぶんをよんでいる"},"answer":"読んでいる","distractors":["読むいる","読みている","読んいる"],"gap":{"kanji":"父が新聞を＿","kana":"ちちがしんぶんを＿"},"prompt":{"en":"\"My father is reading the newspaper.\" Which form says the action is happening right now?","it":"«Mio padre sta leggendo il giornale.» Quale forma dice che l''azione sta succedendo adesso?"},"translation":{"en":"My father is reading the newspaper.","it":"Mio padre sta leggendo il giornale."},"glosses":[{"text":"読んでいる","reading":"よんでいる"},{"text":"読むいる","reading":"よむいる"},{"text":"読みている","reading":"よみている"},{"text":"読んいる","reading":"よんいる"}]}'::jsonb, '「ている」の進行', '"Is doing" = te-form + いる. The te-form is the verb form ending in て or で (読む → 読んで). So 読んでいる means "is reading"; いる never attaches directly to 読む or 読み.', '«Sta facendo» = forma in て + いる. La forma in て è la forma del verbo che finisce in て o で (読む → 読んで). Quindi 読んでいる significa «sta leggendo»; いる non si attacca mai direttamente a 読む o a 読み.'),
  ('3b4b6752-0757-51a1-b94d-13f807ec11e8', '非過去形', 'select-span', '{"sentence":{"kanji":"妹がテレビを見ている","kana":"いもうとがテレビをみている"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part shows that the action is happening right now?","it":"Quale parte indica che l''azione sta succedendo adesso?"},"translation":{"en":"My younger sister is watching TV.","it":"Mia sorella minore sta guardando la TV."},"glosses":[{"text":"妹がテレビを見","reading":"いもうとがテレビをみ","meaning":{"en":"younger sister, TV, watch","it":"sorella minore, TV, guardare"}},{"text":"ている","meaning":{"en":"is ...-ing (happening now)","it":"sta ...-ndo (succede adesso)"}}]}'::jsonb, '「ている」の進行', 'Select ている. 見る (to watch) just drops る to make its te-form (the form ending in て): 見て. Add いる and you get 見ている, "is watching".', 'Seleziona ている. 見る (guardare) toglie solo る per fare la forma in て (la forma che finisce in て): 見て. Aggiungi いる e ottieni 見ている, «sta guardando».'),
  ('2281b09b-cfa1-5201-b30a-a4d0e9916bdd', '非過去形', 'select-span', '{"sentence":{"kanji":"昨日カレーを作った","kana":"きのうカレーをつくった"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part makes the verb past?","it":"Quale parte mette il verbo al passato?"},"translation":{"en":"(I) made curry yesterday.","it":"Ieri (io) ho preparato il curry."},"glosses":[{"text":"昨日カレーを作","reading":"きのうカレーをつく","meaning":{"en":"yesterday, curry, make","it":"ieri, curry, preparare"}},{"text":"った","meaning":{"en":"past ending","it":"desinenza del passato"}}]}'::jsonb, '過去形の「た」', 'Select った. The past is built like the te-form (the form ending in て), just with た instead of て: 作る → 作って → 作った. 昨日 (yesterday) needs no particle.', 'Seleziona った. Il passato si costruisce come la forma in て (la forma che finisce in て), solo con た al posto di て: 作る → 作って → 作った. 昨日 (ieri) non vuole particella.'),
  ('5f4f76f1-97eb-5e69-b160-43aaeca96e13', '非過去形', 'assemble', '{"sentence":{"kanji":"先週新しい靴を買った","kana":"せんしゅうあたらしいくつをかった"},"answer":["先週","新しい","靴を","買った"],"alsoAccepted":[["新しい","靴を","先週","買った"]],"prompt":{"en":"Build: \"I bought new shoes last week.\"","it":"Componi: «La settimana scorsa ho comprato delle scarpe nuove.»"},"translation":{"en":"I bought new shoes last week.","it":"La settimana scorsa ho comprato delle scarpe nuove."},"glosses":[{"text":"先週","reading":"せんしゅう","meaning":{"en":"last week","it":"la settimana scorsa"}},{"text":"新しい","reading":"あたらしい","meaning":{"en":"new","it":"nuove"}},{"text":"靴を","reading":"くつを","meaning":{"en":"shoes (what I bought)","it":"scarpe (cosa ho comprato)"}},{"text":"買った","reading":"かった","meaning":{"en":"bought","it":"ho comprato"}}]}'::jsonb, '過去形の「た」', 'The time word 先週 (last week) usually goes first, with no particle. Then "new shoes" + を (the particle that marks what you buy), then the verb at the end. 買う → 買った (bought). "新しい靴を先週買った" is also correct: the verb stays at the end, and 先週 can move. 新しい, though, always stays right before 靴を, because it describes the shoes.', 'La parola di tempo 先週 (la settimana scorsa) di solito va per prima, senza particella. Poi «scarpe nuove» + を (la particella che indica cosa compri), poi il verbo in fondo. 買う → 買った (ho comprato). Va bene anche «新しい靴を先週買った»: il verbo resta in fondo, e 先週 può spostarsi. 新しい invece sta sempre subito prima di 靴を, perché descrive le scarpe.'),
  ('4af79a02-6a52-5ed0-8de8-d892d154cd92', '非過去形', 'assemble', '{"sentence":{"kanji":"七時に友達が来る","kana":"しちじにともだちがくる"},"answer":["七時に","友達が","来る"],"alsoAccepted":[["友達が","七時に","来る"]],"prompt":{"en":"Build: \"A friend is coming at seven.\"","it":"Componi: «Alle sette viene un amico.»"},"translation":{"en":"A friend is coming at seven.","it":"Alle sette viene un amico."},"glosses":[{"text":"七時に","reading":"しちじに","meaning":{"en":"at seven o''clock","it":"alle sette"}},{"text":"友達が","reading":"ともだちが","meaning":{"en":"a friend (the one who comes)","it":"un amico (chi viene)"}},{"text":"来る","reading":"くる","meaning":{"en":"comes","it":"viene"}}]}'::jsonb, '時を示す「に」', 'A clock time like 七時 (seven o''clock) takes に, like English "at". Quick test: if English says "at", "on" or "in" before the time, Japanese uses に. 来る (comes) is non-past, so here it means a future arrival. "友達が七時に来る" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Un orario come 七時 (le sette) prende に, come «alle» in italiano. Prova rapida: se in inglese davanti al tempo serve «at», «on» o «in», in giapponese serve に. 来る (viene) è non passato, quindi qui indica un arrivo futuro. Va bene anche «友達が七時に来る»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('1362ab6a-c76c-52f2-8990-3d5c04dced59', '非過去形', 'single-select', '{"sentence":{"kanji":"来年大学を卒業する","kana":"らいねんだいがくをそつぎょうする"},"answer":"来年","distractors":["来年を","来年が"],"gap":{"kanji":"＿大学を卒業する","kana":"＿だいがくをそつぎょうする"},"prompt":{"en":"\"I will graduate from university next year.\" How is \"next year\" written here?","it":"«L''anno prossimo mi laureo.» Come si scrive qui «l''anno prossimo»?"},"translation":{"en":"I will graduate from university next year.","it":"L''anno prossimo mi laureo."},"glosses":[{"text":"来年","reading":"らいねん"},{"text":"来年を","reading":"らいねんを"},{"text":"来年が","reading":"らいねんが"}]}'::jsonb, '時を示す「に」', '来年 (next year) depends on when you are speaking, so it takes no particle. に is only for fixed times, like a date, a weekday or an hour. With を or が, 来年 would become the thing you finish, or the one who graduates.', '来年 (l''anno prossimo) dipende da quando parli, quindi non prende particella. に serve solo per i tempi fissi, come una data, un giorno della settimana o un''ora. Con を o が, 来年 diventerebbe la cosa che finisci, o chi si laurea.'),
  ('77a06afc-5205-501e-9734-bdbd9ec37ba5', '非過去形', 'select-span', '{"sentence":{"kanji":"きのう雨が降った","kana":"きのうあめがふった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which word says when it rained?","it":"Quale parola dice quando è piovuto?"},"translation":{"en":"It rained yesterday.","it":"Ieri è piovuto."},"glosses":[{"text":"きのう","meaning":{"en":"yesterday","it":"ieri"}},{"text":"雨が降","reading":"あめがふ","meaning":{"en":"rain, fall","it":"pioggia, cadere"}},{"text":"った","meaning":{"en":"past ending","it":"desinenza del passato"}}]}'::jsonb, '時を示す「に」', 'Select きのう (yesterday). Words like yesterday, today, tomorrow or last week depend on when you are speaking, so they take no に. They simply sit at the start of the sentence.', 'Seleziona きのう (ieri). Parole come ieri, oggi, domani o la settimana scorsa dipendono da quando parli, quindi non prendono に. Stanno semplicemente all''inizio della frase.'),
  ('0cb772a1-ec27-552f-854c-7daf8ed5c783', '非過去形', 'assemble', '{"sentence":{"kanji":"毎朝コーヒーを飲む","kana":"まいあさコーヒーをのむ"},"answer":["毎朝","コーヒーを","飲む"],"alsoAccepted":[["コーヒーを","毎朝","飲む"]],"prompt":{"en":"Build: \"I drink coffee every morning.\"","it":"Componi: «Ogni mattina bevo il caffè.»"},"translation":{"en":"I drink coffee every morning.","it":"Ogni mattina bevo il caffè."},"glosses":[{"text":"毎朝","reading":"まいあさ","meaning":{"en":"every morning","it":"ogni mattina"}},{"text":"コーヒーを","meaning":{"en":"coffee (what I drink)","it":"caffè (cosa bevo)"}},{"text":"飲む","reading":"のむ","meaning":{"en":"drink","it":"bevo"}}]}'::jsonb, '非過去形', 'For a habit, use the non-past: the verb exactly as a dictionary lists it, 飲む, "I drink". 毎朝 (every morning) takes no に and usually goes first; the verb always comes last. "コーヒーを毎朝飲む" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Per un''abitudine si usa il non passato: il verbo così come lo trovi sul dizionario, 飲む, «bevo». 毎朝 (ogni mattina) non prende に e di solito va per primo; il verbo sta sempre in fondo. Va bene anche «コーヒーを毎朝飲む»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('68eb3381-1ff9-5c34-b388-6f5da586e7ea', '非過去形', 'assemble', '{"sentence":{"kanji":"姉は今電話で話している","kana":"あねはいまでんわではなしている"},"answer":["姉は","今","電話で","話している"],"alsoAccepted":[["今","姉は","電話で","話している"]],"prompt":{"en":"Build: \"My older sister is talking on the phone now.\"","it":"Componi: «Mia sorella maggiore adesso sta parlando al telefono.»"},"translation":{"en":"My older sister is talking on the phone now.","it":"Mia sorella maggiore adesso sta parlando al telefono."},"glosses":[{"text":"姉は","reading":"あねは","meaning":{"en":"my older sister (the topic)","it":"mia sorella maggiore (l''argomento)"}},{"text":"今","reading":"いま","meaning":{"en":"now","it":"adesso"}},{"text":"電話で","reading":"でんわで","meaning":{"en":"on the phone","it":"al telefono"}},{"text":"話している","reading":"はなしている","meaning":{"en":"is talking","it":"sta parlando"}}]}'::jsonb, '「ている」の進行', '話す (to talk) has the te-form (the form ending in て) 話して; adding いる gives 話している, "is talking". 今 (now) takes no particle. The verb goes last. "今姉は電話で話している" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '話す (parlare) ha la forma in て (la forma che finisce in て) 話して; aggiungendo いる si ottiene 話している, «sta parlando». 今 (adesso) non prende particella. Il verbo va in fondo. Va bene anche «今姉は電話で話している»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('5aa9459a-159d-5e9a-b38e-79959e03fe4e', '非過去形', 'single-select', '{"sentence":{"kanji":"来週東京で会議がある","kana":"らいしゅうとうきょうでかいぎがある"},"answer":"ある","distractors":["あった","あるだ"],"gap":{"kanji":"来週東京で会議が＿","kana":"らいしゅうとうきょうでかいぎが＿"},"prompt":{"en":"\"There is a meeting in Tokyo next week.\" Which verb form fits?","it":"«La settimana prossima c''è una riunione a Tokyo.» Quale forma del verbo è giusta?"},"translation":{"en":"There is a meeting in Tokyo next week.","it":"La settimana prossima c''è una riunione a Tokyo."},"glosses":[{"text":"ある"},{"text":"あった"},{"text":"あるだ"}]}'::jsonb, '非過去形', 'ある (there is) here is in the non-past: the verb exactly as you find it in a dictionary. The non-past is used for things that have not happened yet, so with 来週 (next week) it means "there will be". あった is the past and cannot go with next week; あるだ does not exist, because だ (the word for "is") never goes after a verb.', 'ある (c''è) qui è al non passato: il verbo così come lo trovi sul dizionario. Il non passato si usa per le cose che non sono ancora successe, quindi con 来週 (la settimana prossima) significa «ci sarà». あった è il passato e non può stare con la settimana prossima; あるだ non esiste, perché だ (la parola per «è») non va mai dopo un verbo.'),
  ('5de8b6a0-9e1f-5e24-94fe-275ffe0668da', '非過去形', 'select-span', '{"sentence":{"kanji":"よく公園で走る","kana":"よくこうえんではしる"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I often run in the park.\" Which part shows that the verb is not in the past?","it":"«Corro spesso al parco.» Quale parte mostra che il verbo non è al passato?"},"translation":{"en":"I often run in the park.","it":"Corro spesso al parco."},"glosses":[{"text":"よく","meaning":{"en":"often","it":"spesso"}},{"text":"公園で走","reading":"こうえんではし","meaning":{"en":"in the park, run","it":"al parco, correre"}},{"text":"る","meaning":{"en":"dictionary-form ending (not past)","it":"finale della forma del dizionario (non passato)"}}]}'::jsonb, '非過去形', 'Select る. 走る (to run) ends in る, just as you find it in a dictionary: this is the non-past, used for habits and for the future. In the past it would be 走った. よく (often) tells you how often, but it is the verb ending that says "not past".', 'Seleziona る. 走る (correre) finisce in る, così come lo trovi sul dizionario: è il non passato, che si usa per le abitudini e per il futuro. Al passato sarebbe 走った. よく (spesso) dice quanto spesso, ma è il finale del verbo a dire «non passato».'),
  ('26164b1a-abcf-527a-bdbb-8904df961676', '非過去形', 'select-span', '{"sentence":{"kanji":"あさって荷物が届く","kana":"あさってにもつがとどく"},"answer":{"start":0,"end":1},"prompt":{"en":"\"The parcel arrives the day after tomorrow.\" 届く is non-past. Which part tells you it is about the future?","it":"«Il pacco arriva dopodomani.» 届く è al non passato. Quale parte dice che si parla del futuro?"},"translation":{"en":"The parcel arrives the day after tomorrow.","it":"Il pacco arriva dopodomani."},"glosses":[{"text":"あさって","meaning":{"en":"the day after tomorrow","it":"dopodomani"}},{"text":"荷物が届","reading":"にもつがとど","meaning":{"en":"the parcel, arrive","it":"il pacco, arrivare"}},{"text":"く","meaning":{"en":"dictionary-form ending (not past)","it":"finale della forma del dizionario (non passato)"}}]}'::jsonb, '非過去形', 'Select あさって (the day after tomorrow). The non-past form 届く only says "not past": it can be a habit or something still to come. Here the time word あさって makes it clearly future: "it will arrive". Without it, 荷物が届く could also mean "parcels arrive" as a general fact.', 'Seleziona あさって (dopodomani). La forma non passata 届く dice solo «non passato»: può essere un''abitudine o qualcosa che deve ancora succedere. Qui la parola di tempo あさって la rende chiaramente futura: «arriverà». Senza, 荷物が届く potrebbe anche voler dire «i pacchi arrivano» in generale.'),
  ('8417e540-70e4-515a-900b-32d720e27d3a', '非過去形', 'assemble', '{"sentence":{"kanji":"この店は十時に開く","kana":"このみせはじゅうじにあく"},"answer":["この店は","十時に","開く"],"prompt":{"en":"Build: \"This shop opens at ten.\"","it":"Componi: «Questo negozio apre alle dieci.»"},"translation":{"en":"This shop opens at ten.","it":"Questo negozio apre alle dieci."},"glosses":[{"text":"この店は","reading":"このみせは","meaning":{"en":"this shop (the topic)","it":"questo negozio (l''argomento)"}},{"text":"十時に","reading":"じゅうじに","meaning":{"en":"at ten o''clock","it":"alle dieci"}},{"text":"開く","reading":"あく","meaning":{"en":"opens","it":"apre"}}]}'::jsonb, '非過去形', 'A fixed schedule that repeats every day uses the non-past: 開く (opens), the verb as you find it in a dictionary. First the topic この店は (this shop), then the time 十時に (at ten), and the verb at the end.', 'Un orario fisso che si ripete ogni giorno usa il non passato: 開く (apre), il verbo così come lo trovi sul dizionario. Prima l''argomento この店は (questo negozio), poi l''ora 十時に (alle dieci), e il verbo in fondo.'),
  ('7f2378b5-46c8-5a0f-ad00-5619071eff75', '非過去形', 'single-select', '{"sentence":{"kanji":"子どもたちが庭で遊んでいる","kana":"こどもたちがにわであそんでいる"},"answer":"遊んでいる","distractors":["遊びている","遊ぶいる","遊んている"],"gap":{"kanji":"子どもたちが庭で＿","kana":"こどもたちがにわで＿"},"prompt":{"en":"\"The children are playing in the garden.\" Which form says they are playing right now?","it":"«I bambini stanno giocando in giardino.» Quale forma dice che stanno giocando adesso?"},"translation":{"en":"The children are playing in the garden.","it":"I bambini stanno giocando in giardino."},"glosses":[{"text":"遊んでいる","reading":"あそんでいる"},{"text":"遊びている","reading":"あそびている"},{"text":"遊ぶいる","reading":"あそぶいる"},{"text":"遊んている","reading":"あそんている"}]}'::jsonb, '「ている」の進行', '"Is doing" = te-form + いる. The te-form is the verb form ending in て or で. 遊ぶ (to play) ends in ぶ, so ぶ becomes ん and て becomes で: 遊んで. Add いる: 遊んでいる, "are playing". 遊んている is wrong because after ん you always get で, not て.', '«Sta facendo» = forma in て + いる. La forma in て è la forma del verbo che finisce in て o で. 遊ぶ (giocare) finisce in ぶ, quindi ぶ diventa ん e て diventa で: 遊んで. Aggiungi いる: 遊んでいる, «stanno giocando». 遊んている è sbagliato perché dopo ん viene sempre で, non て.'),
  ('29d9e52c-0f40-5bb3-843a-92dab1509a5b', '非過去形', 'select-span', '{"sentence":{"kanji":"うちの猫がソファで寝ている","kana":"うちのねこがソファでねている"},"answer":{"start":2,"end":3},"prompt":{"en":"\"Our cat is sleeping on the sofa.\" Which part says it is happening right now?","it":"«Il nostro gatto sta dormendo sul divano.» Quale parte dice che sta succedendo adesso?"},"translation":{"en":"Our cat is sleeping on the sofa.","it":"Il nostro gatto sta dormendo sul divano."},"glosses":[{"text":"うちの","meaning":{"en":"our","it":"nostro"}},{"text":"猫がソファで寝","reading":"ねこがソファでね","meaning":{"en":"the cat, on the sofa, sleep","it":"il gatto, sul divano, dormire"}},{"text":"ている","meaning":{"en":"is ...-ing (happening now)","it":"sta ...-ndo (succede adesso)"}}]}'::jsonb, '「ている」の進行', 'Select ている. 寝る (to sleep) just drops る to make its te-form (the form ending in て): 寝て. Adding いる gives 寝ている, "is sleeping". うちの (our) only tells you whose cat it is.', 'Seleziona ている. 寝る (dormire) toglie solo る per fare la forma in て (la forma che finisce in て): 寝て. Aggiungendo いる si ottiene 寝ている, «sta dormendo». うちの (nostro) dice solo di chi è il gatto.'),
  ('d31a120b-adb5-5da8-9980-741f425e3fcf', '非過去形', 'assemble', '{"sentence":{"kanji":"シェフが台所で魚を焼いている","kana":"シェフがだいどころでさかなをやいている"},"answer":["シェフが","台所で","魚を","焼いている"],"alsoAccepted":[["シェフが","魚を","台所で","焼いている"],["台所で","シェフが","魚を","焼いている"]],"prompt":{"en":"Build: \"The chef is grilling fish in the kitchen.\"","it":"Componi: «Lo chef sta cuocendo il pesce alla griglia in cucina.»"},"translation":{"en":"The chef is grilling fish in the kitchen.","it":"Lo chef sta cuocendo il pesce alla griglia in cucina."},"glosses":[{"text":"シェフが","meaning":{"en":"the chef (the one doing it)","it":"lo chef (chi lo fa)"}},{"text":"台所で","reading":"だいどころで","meaning":{"en":"in the kitchen","it":"in cucina"}},{"text":"魚を","reading":"さかなを","meaning":{"en":"fish (what is being grilled)","it":"il pesce (cosa cuoce)"}},{"text":"焼いている","reading":"やいている","meaning":{"en":"is grilling","it":"sta cuocendo alla griglia"}}]}'::jsonb, '「ている」の進行', '焼く (to grill) ends in く, so its te-form (the form ending in て) is 焼いて; adding いる gives 焼いている, "is grilling". The one doing it usually comes first with が, the verb goes last. "シェフが魚を台所で焼いている" and "台所でシェフが魚を焼いている" are also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '焼く (cuocere alla griglia) finisce in く, quindi la sua forma in て (la forma che finisce in て) è 焼いて; aggiungendo いる si ottiene 焼いている, «sta cuocendo». Chi lo fa di solito viene per primo con が, il verbo va in fondo. Vanno bene anche «シェフが魚を台所で焼いている» e «台所でシェフが魚を焼いている»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('512b14fc-11e2-57e3-8683-a4e1ae2487c4', '非過去形', 'single-select', '{"sentence":{"kanji":"先月北海道を旅行した","kana":"せんげつほっかいどうをりょこうした"},"answer":"した","distractors":["する","しった"],"gap":{"kanji":"先月北海道を旅行＿","kana":"せんげつほっかいどうをりょこう＿"},"prompt":{"en":"\"Last month I travelled around Hokkaido.\" Which form of する fits?","it":"«Il mese scorso ho fatto un viaggio in Hokkaido.» Quale forma di する è giusta?"},"translation":{"en":"Last month I travelled around Hokkaido.","it":"Il mese scorso ho fatto un viaggio in Hokkaido."},"glosses":[{"text":"した"},{"text":"する"},{"text":"しった"}]}'::jsonb, '過去形の「た」', '先月 (last month) is in the past, so the verb must be past too. 旅行する means "to travel", and the past of する is した: 旅行した, "I travelled". する is non-past and cannot go with last month; しった does not exist.', '先月 (il mese scorso) è nel passato, quindi anche il verbo deve essere al passato. 旅行する vuol dire «viaggiare», e il passato di する è した: 旅行した, «ho viaggiato». する è non passato e non può stare con il mese scorso; しった non esiste.'),
  ('7cf9707b-277e-5035-a564-d5c03d541fb6', '非過去形', 'single-select', '{"sentence":{"kanji":"今朝バスが遅れた","kana":"けさバスがおくれた"},"answer":"遅れた","distractors":["遅れる","遅れった"],"gap":{"kanji":"今朝バスが＿","kana":"けさバスが＿"},"prompt":{"en":"\"The bus was late this morning.\" Which form of 遅れる fits?","it":"«Stamattina l''autobus era in ritardo.» Quale forma di 遅れる è giusta?"},"translation":{"en":"The bus was late this morning.","it":"Stamattina l''autobus era in ritardo."},"glosses":[{"text":"遅れた","reading":"おくれた"},{"text":"遅れる","reading":"おくれる"},{"text":"遅れった","reading":"おくれった"}]}'::jsonb, '過去形の「た」', 'The bus was late: it already happened, so the verb goes in the past. 遅れる (to be late) ends in -eru and simply drops る, then adds た: 遅れ + た = 遅れた. No small っ is needed, so 遅れった is wrong. 遅れる is non-past: "will be late".', 'L''autobus era in ritardo: è già successo, quindi il verbo va al passato. 遅れる (essere in ritardo) finisce in -eru e toglie semplicemente る, poi aggiunge た: 遅れ + た = 遅れた. Non serve nessuna piccola っ, quindi 遅れった è sbagliato. 遅れる è non passato: «sarà in ritardo».'),
  ('59d39392-39f2-53bb-a857-0d8e8cca63d1', '非過去形', 'select-span', '{"sentence":{"kanji":"さっき電車が着いた","kana":"さっきでんしゃがついた"},"answer":{"start":2,"end":3},"prompt":{"en":"\"The train arrived a moment ago.\" Which part makes 着く past?","it":"«Il treno è arrivato poco fa.» Quale parte mette 着く al passato?"},"translation":{"en":"The train arrived a moment ago.","it":"Il treno è arrivato poco fa."},"glosses":[{"text":"さっき","meaning":{"en":"a moment ago","it":"poco fa"}},{"text":"電車が着","reading":"でんしゃがつ","meaning":{"en":"the train, arrive","it":"il treno, arrivare"}},{"text":"いた","meaning":{"en":"past ending of 着く (arrived)","it":"desinenza del passato di 着く (arrivato)"}}]}'::jsonb, '過去形の「た」', 'Select いた. 着く (to arrive) ends in く: く becomes い, then た is added: 着く → 着いた. さっき (a moment ago) says when, but it does not make the verb past: that is the job of the ending.', 'Seleziona いた. 着く (arrivare) finisce in く: く diventa い, poi si aggiunge た: 着く → 着いた. さっき (poco fa) dice quando, ma non mette il verbo al passato: quello è il compito del finale.'),
  ('b77af65a-c810-5354-9710-0d2fe1ac3735', '非過去形', 'assemble', '{"sentence":{"kanji":"おととい海で写真を撮った","kana":"おとというみでしゃしんをとった"},"answer":["おととい","海で","写真を","撮った"],"alsoAccepted":[["おととい","写真を","海で","撮った"],["海で","おととい","写真を","撮った"]],"prompt":{"en":"Build: \"The day before yesterday I took photos at the sea.\"","it":"Componi: «L''altro ieri ho fatto delle foto al mare.»"},"translation":{"en":"The day before yesterday I took photos at the sea.","it":"L''altro ieri ho fatto delle foto al mare."},"glosses":[{"text":"おととい","meaning":{"en":"the day before yesterday","it":"l''altro ieri"}},{"text":"海で","reading":"うみで","meaning":{"en":"at the sea","it":"al mare"}},{"text":"写真を","reading":"しゃしんを","meaning":{"en":"photos (what I took)","it":"foto (cosa ho fatto)"}},{"text":"撮った","reading":"とった","meaning":{"en":"took (a photo)","it":"ho fatto (una foto)"}}]}'::jsonb, '過去形の「た」', '撮る (to take a photo) ends in る and makes its past with a small っ: 撮る → 撮った. The time word おととい (the day before yesterday) usually goes first with no particle, and the verb goes last. "おととい写真を海で撮った" and "海でおととい写真を撮った" are also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '撮る (fotografare) finisce in る e fa il passato con una piccola っ: 撮る → 撮った. La parola di tempo おととい (l''altro ieri) di solito va per prima senza particella, e il verbo va in fondo. Vanno bene anche «おととい写真を海で撮った» e «海でおととい写真を撮った»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('44ae4d49-6df9-571b-a14c-db5b9a346b9d', '非過去形', 'single-select', '{"sentence":{"kanji":"五月三日に引っ越す","kana":"ごがつみっかにひっこす"},"answer":"五月三日に","distractors":["五月三日","五月三日を"],"gap":{"kanji":"＿引っ越す","kana":"＿ひっこす"},"prompt":{"en":"\"I am moving house on May 3rd.\" How is \"on May 3rd\" written here?","it":"«Il 3 maggio trasloco.» Come si scrive qui «il 3 maggio»?"},"translation":{"en":"I am moving house on May 3rd.","it":"Il 3 maggio trasloco."},"glosses":[{"text":"五月三日に","reading":"ごがつみっかに"},{"text":"五月三日","reading":"ごがつみっか"},{"text":"五月三日を","reading":"ごがつみっかを"}]}'::jsonb, '時を示す「に」', 'A date like 五月三日 (May 3rd) is a fixed point in the calendar: it does not change depending on when you speak. Fixed times take に, like English "on". Only words like today, tomorrow or next year go without に. With を, the date would become the thing you move.', 'Una data come 五月三日 (il 3 maggio) è un punto fisso del calendario: non cambia a seconda di quando parli. I tempi fissi prendono に. Solo parole come oggi, domani o l''anno prossimo vanno senza に. Con を, la data diventerebbe la cosa che traslochi.'),
  ('41c8abea-13a0-53d7-81b9-dbe635cd9000', '非過去形', 'select-span', '{"sentence":{"kanji":"クリスマスに家族が集まる","kana":"クリスマスにかぞくがあつまる"},"answer":{"start":0,"end":1},"prompt":{"en":"\"At Christmas the family gets together.\" Which part says when?","it":"«A Natale la famiglia si riunisce.» Quale parte dice quando?"},"translation":{"en":"At Christmas the family gets together.","it":"A Natale la famiglia si riunisce."},"glosses":[{"text":"クリスマスに","meaning":{"en":"at Christmas","it":"a Natale"}},{"text":"家族が集","reading":"かぞくがあつ","meaning":{"en":"the family, gather","it":"la famiglia, riunirsi"}},{"text":"まる","meaning":{"en":"end of the verb 集まる (gets together)","it":"fine del verbo 集まる (si riunisce)"}}]}'::jsonb, '時を示す「に」', 'Select クリスマスに (at Christmas). Christmas is a fixed day of the year, so it takes に, which marks the moment when something happens. Compare with あした (tomorrow), which depends on when you speak and takes no に.', 'Seleziona クリスマスに (a Natale). Natale è un giorno fisso dell''anno, quindi prende に, che indica il momento in cui succede qualcosa. Confronta con あした (domani), che dipende da quando parli e non prende に.'),
  ('b7ab23ed-7eb4-52ac-8b04-11035b2953db', '非過去形', 'assemble', '{"sentence":{"kanji":"四月に桜が咲く","kana":"しがつにさくらがさく"},"answer":["四月に","桜が","咲く"],"alsoAccepted":[["桜が","四月に","咲く"]],"prompt":{"en":"Build: \"The cherry trees bloom in April.\"","it":"Componi: «I ciliegi fioriscono ad aprile.»"},"translation":{"en":"The cherry trees bloom in April.","it":"I ciliegi fioriscono ad aprile."},"glosses":[{"text":"四月に","reading":"しがつに","meaning":{"en":"in April","it":"ad aprile"}},{"text":"桜が","reading":"さくらが","meaning":{"en":"the cherry trees (what blooms)","it":"i ciliegi (cosa fiorisce)"}},{"text":"咲く","reading":"さく","meaning":{"en":"bloom","it":"fioriscono"}}]}'::jsonb, '時を示す「に」', 'A month like 四月 (April) is a fixed time, so it takes に, like English "in". 咲く (bloom) is non-past: it happens every year. "桜が四月に咲く" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Un mese come 四月 (aprile) è un tempo fisso, quindi prende に, come «ad» in italiano. 咲く (fioriscono) è non passato: succede ogni anno. Va bene anche «桜が四月に咲く»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('3edb0ae6-beb3-5405-a88e-42582289500c', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"朝ごはんを食べた","kana":"あさごはんをたべた"},"answer":"食べた","distractors":["食べった","食べいた","食んだ"],"gap":{"kanji":"朝ごはんを＿","kana":"あさごはんを＿"},"prompt":{"en":"\"I ate breakfast.\" What is the past of 食べる?","it":"«Ho fatto colazione.» Qual è il passato di 食べる?"},"translation":{"en":"I ate breakfast.","it":"Ho fatto colazione."},"glosses":[{"text":"食べた","reading":"たべた"},{"text":"食べった","reading":"たべった"},{"text":"食べいた","reading":"たべいた"},{"text":"食んだ","reading":"たんだ"}]}'::jsonb, '動詞の三つのグループ', '食べる is an ichidan verb (the group of verbs ending in -iru or -eru that simply drop る). To make the past, drop る and add た: 食べ + た = 食べた. Nothing else changes.', '食べる è un verbo ichidan (il gruppo di verbi in -iru o -eru che tolgono semplicemente る). Per fare il passato togli る e aggiungi た: 食べ + た = 食べた. Non cambia nient''altro.'),
  ('d5c8da5e-6e1b-5e48-b374-a114cb6e4e43', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"毎朝公園を走っている","kana":"まいあさこうえんをはしっている"},"answer":"走って","distractors":["走て","走りて","走んで"],"gap":{"kanji":"毎朝公園を＿いる","kana":"まいあさこうえんを＿いる"},"prompt":{"en":"\"I run in the park every morning.\" What is the te-form of 走る?","it":"«Ogni mattina corro al parco.» Qual è la forma in て di 走る?"},"translation":{"en":"I run in the park every morning.","it":"Ogni mattina corro al parco."},"glosses":[{"text":"走って","reading":"はしって"},{"text":"走て","reading":"はして"},{"text":"走りて","reading":"はしりて"},{"text":"走んで","reading":"はしんで"}]}'::jsonb, '動詞の三つのグループ', '走る ends in -iru, but it is a godan verb (the group of verbs whose last syllable changes, like 書く → 書いて). Godan verbs ending in る make the te-form (the form ending in て) with a small っ: 走る → 走って. 走て is wrong: that would treat it like 食べる.', '走る finisce in -iru, ma è un verbo godan (il gruppo di verbi che cambiano l''ultima sillaba, come 書く → 書いて). I godan in る fanno la forma in て (la forma che finisce in て) con una piccola っ: 走る → 走って. 走て è sbagliato: lo tratterebbe come 食べる.'),
  ('cd298cc6-62a9-54aa-8f73-d88e3c6214f9', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"弟が薬を飲んだ","kana":"おとうとがくすりをのんだ"},"answer":"飲んだ","distractors":["飲った","飲いだ","飲みた"],"gap":{"kanji":"弟が薬を＿","kana":"おとうとがくすりを＿"},"prompt":{"en":"\"My younger brother took the medicine.\" What is the past of 飲む?","it":"«Mio fratello minore ha preso la medicina.» Qual è il passato di 飲む?"},"translation":{"en":"My younger brother took the medicine.","it":"Mio fratello minore ha preso la medicina."},"glosses":[{"text":"飲んだ","reading":"のんだ"},{"text":"飲った","reading":"のった"},{"text":"飲いだ","reading":"のいだ"},{"text":"飲みた","reading":"のみた"}]}'::jsonb, 'て形・た形の作り方', 'Verbs ending in む, ぶ or ぬ turn that syllable into ん, and て/た become で/だ. So 飲む (to drink) → 飲んで → 飲んだ.', 'I verbi che finiscono in む, ぶ o ぬ cambiano quella sillaba in ん, e て/た diventano で/だ. Quindi 飲む (bere) → 飲んで → 飲んだ.'),
  ('a83154b8-bddd-5726-ad4a-9cc36ddc9b02', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"昨日プールで泳いだ","kana":"きのうプールでおよいだ"},"answer":"泳いだ","distractors":["泳った","泳んだ","泳いた"],"gap":{"kanji":"昨日プールで＿","kana":"きのうプールで＿"},"prompt":{"en":"\"I swam in the pool yesterday.\" What is the past of 泳ぐ?","it":"«Ieri ho nuotato in piscina.» Qual è il passato di 泳ぐ?"},"translation":{"en":"I swam in the pool yesterday.","it":"Ieri ho nuotato in piscina."},"glosses":[{"text":"泳いだ","reading":"およいだ"},{"text":"泳った","reading":"およった"},{"text":"泳んだ","reading":"およんだ"},{"text":"泳いた","reading":"およいた"}]}'::jsonb, 'て形・た形の作り方', 'Verbs ending in く become いて/いた (書く → 書いた). Verbs ending in ぐ do the same, but with で/だ: いで/いだ. 泳ぐ (to swim) ends in ぐ, so the past is 泳いだ, not 泳いた.', 'I verbi che finiscono in く diventano いて/いた (書く → 書いた). Quelli in ぐ fanno lo stesso, ma con で/だ: いで/いだ. 泳ぐ (nuotare) finisce in ぐ, quindi il passato è 泳いだ, non 泳いた.'),
  ('5a77229e-6cec-5a7a-a56d-015085d4fd93', '動詞の三つのグループ', 'select-span', '{"sentence":{"kanji":"手紙を出した","kana":"てがみをだした"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part is the past ending of 出す?","it":"Quale parte è la desinenza del passato di 出す?"},"translation":{"en":"I sent a letter.","it":"Ho spedito una lettera."},"glosses":[{"text":"手紙を出","reading":"てがみをだ","meaning":{"en":"letter, send","it":"lettera, spedire"}},{"text":"した","meaning":{"en":"past ending of 出す (sent)","it":"desinenza del passato di 出す (spedito)"}}]}'::jsonb, 'て形・た形の作り方', 'Select した. Verbs ending in す change す into し, then add て or た: 出す (to send) → 出して → 出した.', 'Seleziona した. I verbi che finiscono in す cambiano す in し, poi aggiungono て o た: 出す (spedire) → 出して → 出した.'),
  ('10054a46-427c-5262-9c64-6c52b362676c', '動詞の三つのグループ', 'assemble', '{"sentence":{"kanji":"歩いて学校に行った","kana":"あるいてがっこうにいった"},"answer":["歩いて","学校に","行った"],"alsoAccepted":[["学校に","歩いて","行った"]],"prompt":{"en":"Build: \"I walked to school.\"","it":"Componi: «Sono andato a scuola a piedi.»"},"translation":{"en":"I walked to school.","it":"Sono andato a scuola a piedi."},"glosses":[{"text":"歩いて","reading":"あるいて","meaning":{"en":"on foot, walking","it":"a piedi, camminando"}},{"text":"学校に","reading":"がっこうに","meaning":{"en":"to school","it":"a scuola"}},{"text":"行った","reading":"いった","meaning":{"en":"went","it":"sono andato"}}]}'::jsonb, 'て形・た形の作り方', '歩く (to walk) ends in く, so it becomes 歩いて ("walking"). 行く (to go) also ends in く, but it is the one exception: 行って / 行った, never 行いた. The te-form (the form ending in て) first says how you went. "学校に歩いて行った" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '歩く (camminare) finisce in く, quindi diventa 歩いて («camminando»). Anche 行く (andare) finisce in く, ma è l''unica eccezione: 行って / 行った, mai 行いた. La forma in て (la forma che finisce in て) dice prima come sei andato. Va bene anche «学校に歩いて行った»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('3b9faea7-4987-5660-b634-29e62290f61d', '動詞の三つのグループ', 'single-select', '{"sentence":{"kanji":"日曜日に友達が来た","kana":"にちようびにともだちがきた"},"answer":"来た","distractors":["来った","来いた","来んだ"],"gap":{"kanji":"日曜日に友達が＿","kana":"にちようびにともだちが＿"},"prompt":{"en":"\"A friend came on Sunday.\" What is the past of 来る?","it":"«Domenica è venuto un amico.» Qual è il passato di 来る?"},"translation":{"en":"A friend came on Sunday.","it":"Domenica è venuto un amico."},"glosses":[{"text":"来た","reading":"きた"},{"text":"来った","reading":"きった"},{"text":"来いた","reading":"きいた"},{"text":"来んだ","reading":"きんだ"}]}'::jsonb, '動詞の三つのグループ', 'Japanese has only two irregular verbs: 来る (to come) and する (to do). You just memorize their forms: 来る → 来て / 来た (read きて / きた), する → して / した.', 'Il giapponese ha solo due verbi irregolari: 来る (venire) e する (fare). Le loro forme si imparano a memoria: 来る → 来て / 来た (si leggono きて / きた), する → して / した.'),
  ('cc4c3df6-15b2-5fbe-b1f6-7dedc6204d86', '動詞の三つのグループ', 'select-span', '{"sentence":{"kanji":"バスを待った","kana":"バスをまった"},"answer":{"start":2,"end":3},"prompt":{"en":"Which part is the past ending of 待つ?","it":"Quale parte è la desinenza del passato di 待つ?"},"translation":{"en":"I waited for the bus.","it":"Ho aspettato l''autobus."},"glosses":[{"text":"バスを","meaning":{"en":"the bus (what I waited for)","it":"l''autobus (cosa ho aspettato)"}},{"text":"待","reading":"ま","meaning":{"en":"wait","it":"aspettare"}},{"text":"った","meaning":{"en":"past ending of 待つ (waited)","it":"desinenza del passato di 待つ (aspettato)"}}]}'::jsonb, 'て形・た形の作り方', 'Select った. Godan verbs (the group whose last syllable changes) ending in つ, う or る replace that syllable with a small っ, then add て or た. So 待つ (to wait) → 待って → 待った.', 'Seleziona った. I verbi godan (il gruppo che cambia l''ultima sillaba) che finiscono in つ, う o る sostituiscono quella sillaba con una piccola っ, poi aggiungono て o た. Quindi 待つ (aspettare) → 待って → 待った.'),
  ('64d5073f-f9b5-567d-84ed-235df78d0069', '動詞の三つのグループ', 'select-span', '{"sentence":{"kanji":"昨日は十時に寝た","kana":"きのうはじゅうじにねた"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part makes 寝る past?","it":"Quale parte mette 寝る al passato?"},"translation":{"en":"Yesterday I went to bed at ten.","it":"Ieri sono andato a letto alle dieci."},"glosses":[{"text":"昨日は十時に寝","reading":"きのうはじゅうじにね","meaning":{"en":"yesterday, at ten o''clock, go to bed","it":"ieri, alle dieci, andare a letto"}},{"text":"た","meaning":{"en":"past ending","it":"desinenza del passato"}}]}'::jsonb, '動詞の三つのグループ', 'Select た. 寝る (to go to bed) is an ichidan verb (it ends in -eru and simply drops る). So you drop る and add た: 寝 + た = 寝た. No small っ is needed.', 'Seleziona た. 寝る (andare a letto) è un verbo ichidan (finisce in -eru e toglie semplicemente る). Quindi togli る e aggiungi た: 寝 + た = 寝た. Non serve nessuna piccola っ.'),
  ('1b54d6fe-f1e5-50c8-b6e8-ba2152ccea72', '動詞の三つのグループ', 'assemble', '{"sentence":{"kanji":"本を読んで寝た","kana":"ほんをよんでねた"},"answer":["本を","読んで","寝た"],"prompt":{"en":"Build: \"I read a book and went to sleep.\"","it":"Componi: «Ho letto un libro e sono andato a dormire.»"},"translation":{"en":"I read a book and went to sleep.","it":"Ho letto un libro e sono andato a dormire."},"glosses":[{"text":"本を","reading":"ほんを","meaning":{"en":"a book (what I read)","it":"un libro (cosa ho letto)"}},{"text":"読んで","reading":"よんで","meaning":{"en":"read, and then","it":"ho letto, e poi"}},{"text":"寝た","reading":"ねた","meaning":{"en":"went to sleep","it":"sono andato a dormire"}}]}'::jsonb, 'て形・た形の作り方', 'The te-form (the form ending in て or で) joins two actions: "I did this, and then that". 読む ends in む, so it becomes 読んで. Only the last verb, 寝た, says that everything is in the past. 本を stays right before 読んで: the book is what you read.', 'La forma in て (la forma che finisce in て o で) unisce due azioni: «ho fatto questo, e poi quello». 読む finisce in む, quindi diventa 読んで. Solo l''ultimo verbo, 寝た, dice che tutto è al passato. 本を sta subito prima di 読んで: è il libro che leggi.'),
  ('bfc80f44-063f-5807-b198-2870a9be4b27', '動詞の三つのグループ', 'select-span', '{"sentence":{"kanji":"六時に家へ帰った","kana":"ろくじにいえへかえった"},"answer":{"start":1,"end":2},"prompt":{"en":"\"I went home at six.\" 帰る ends in -eru, but which part shows it is not an ichidan verb?","it":"«Sono tornato a casa alle sei.» 帰る finisce in -eru, ma quale parte mostra che non è un verbo ichidan?"},"translation":{"en":"I went home at six.","it":"Sono tornato a casa alle sei."},"glosses":[{"text":"六時に家へ帰","reading":"ろくじにいえへかえ","meaning":{"en":"at six o''clock, home, go back","it":"alle sei, a casa, tornare"}},{"text":"った","meaning":{"en":"past ending of 帰る (went back)","it":"desinenza del passato di 帰る (tornato)"}}]}'::jsonb, '動詞の三つのグループ', 'Select った. An ichidan verb (one that simply drops る) would give 帰た, but the right past is 帰った, with a small っ. That small っ shows 帰る is a godan verb (the group whose last syllable changes), even though it ends in -eru like 食べる.', 'Seleziona った. Un verbo ichidan (che toglie semplicemente る) darebbe 帰た, ma il passato giusto è 帰った, con una piccola っ. Quella piccola っ mostra che 帰る è un verbo godan (il gruppo che cambia l''ultima sillaba), anche se finisce in -eru come 食べる.'),
  ('66a4b22e-b1c2-58ca-8c22-411e0f18c9af', '動詞の三つのグループ', 'assemble', '{"sentence":{"kanji":"朝起きて顔を洗った","kana":"あさおきてかおをあらった"},"answer":["朝","起きて","顔を","洗った"],"prompt":{"en":"Build: \"In the morning I got up and washed my face.\"","it":"Componi: «La mattina mi sono alzato e mi sono lavato la faccia.»"},"translation":{"en":"In the morning I got up and washed my face.","it":"La mattina mi sono alzato e mi sono lavato la faccia."},"glosses":[{"text":"朝","reading":"あさ","meaning":{"en":"in the morning","it":"la mattina"}},{"text":"起きて","reading":"おきて","meaning":{"en":"got up, and then","it":"mi sono alzato, e poi"}},{"text":"顔を","reading":"かおを","meaning":{"en":"my face (what I washed)","it":"la faccia (cosa ho lavato)"}},{"text":"洗った","reading":"あらった","meaning":{"en":"washed","it":"ho lavato"}}]}'::jsonb, '動詞の三つのグループ', 'Two verbs from two different groups. 起きる (to get up) is ichidan (it simply drops る): 起きて. 洗う (to wash) is godan (its last syllable changes): う becomes a small っ, so 洗った. The te-form (the form ending in て) 起きて says "I got up, and then", so it comes before 顔を洗った. 顔を stays right before 洗った: the face is what you wash.', 'Due verbi di due gruppi diversi. 起きる (alzarsi) è ichidan (toglie semplicemente る): 起きて. 洗う (lavare) è godan (cambia l''ultima sillaba): う diventa una piccola っ, quindi 洗った. La forma in て (la forma che finisce in て) 起きて dice «mi sono alzato, e poi», quindi viene prima di 顔を洗った. 顔を sta subito prima di 洗った: è la faccia che lavi.'),
  ('869bd090-3ce0-5ff8-8184-249eee699ab1', '動詞の三つのグループ', 'assemble', '{"sentence":{"kanji":"夕方犬の散歩をした","kana":"ゆうがたいぬのさんぽをした"},"answer":["夕方","犬の散歩を","した"],"prompt":{"en":"Build: \"In the evening I walked the dog.\"","it":"Componi: «Nel tardo pomeriggio ho portato a spasso il cane.»"},"translation":{"en":"In the evening I walked the dog.","it":"Nel tardo pomeriggio ho portato a spasso il cane."},"glosses":[{"text":"夕方","reading":"ゆうがた","meaning":{"en":"in the evening","it":"nel tardo pomeriggio"}},{"text":"犬の散歩を","reading":"いぬのさんぽを","meaning":{"en":"the dog''s walk","it":"la passeggiata del cane"}},{"text":"した","meaning":{"en":"did","it":"ho fatto"}}]}'::jsonb, '動詞の三つのグループ', 'する (to do) is one of the only two irregular verbs, together with 来る: its past is simply した. 犬の散歩をする literally means "to do the dog''s walk". The time word 夕方 (evening) goes first with no particle, and した goes last, right after 犬の散歩を: the two belong together.', 'する (fare) è uno dei soli due verbi irregolari, insieme a 来る: il suo passato è semplicemente した. 犬の散歩をする vuol dire alla lettera «fare la passeggiata del cane». La parola di tempo 夕方 (tardo pomeriggio) va per prima senza particella, e した va in fondo, subito dopo 犬の散歩を: i due pezzi vanno insieme.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('88bacd49-0013-53ad-8822-bc64198450cd', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"おいしい店に行った","kana":"おいしいみせにいった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part describes the restaurant?","it":"Quale parte descrive il locale?"},"translation":{"en":"I went to a restaurant with delicious food.","it":"Sono andato in un locale dove si mangia bene."},"glosses":[{"text":"おいしい","meaning":{"en":"delicious","it":"buono, delizioso"}},{"text":"店に行","reading":"みせにい","meaning":{"en":"to the restaurant, go","it":"al locale, andare"}},{"text":"った","meaning":{"en":"past ending of 行く (went)","it":"desinenza del passato di 行く (andato)"}}]}'::jsonb, '名詞を修飾する述語', 'Select おいしい (delicious). It is an い-adjective (an adjective ending in い). To describe a noun, just put it right before the noun: おいしい店, "a restaurant with delicious food".', 'Seleziona おいしい (buono). È un aggettivo in い (un aggettivo che finisce in い). Per descrivere un nome basta metterlo subito prima del nome: おいしい店, «un locale dove si mangia bene».'),
  ('f514db52-f4fc-5d2f-af57-5ff12b9949c1', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"昨日買った傘が壊れた","kana":"きのうかったかさがこわれた"},"answer":["昨日","買った","傘が","壊れた"],"prompt":{"en":"Build: \"The umbrella I bought yesterday broke.\"","it":"Componi: «L''ombrello che ho comprato ieri si è rotto.»"},"translation":{"en":"The umbrella I bought yesterday broke.","it":"L''ombrello che ho comprato ieri si è rotto."},"glosses":[{"text":"昨日","reading":"きのう","meaning":{"en":"yesterday","it":"ieri"}},{"text":"買った","reading":"かった","meaning":{"en":"bought (describes the umbrella)","it":"comprato (descrive l''ombrello)"}},{"text":"傘が","reading":"かさが","meaning":{"en":"the umbrella (what broke)","it":"l''ombrello (cosa si è rotto)"}},{"text":"壊れた","reading":"こわれた","meaning":{"en":"broke","it":"si è rotto"}}]}'::jsonb, '名詞を修飾する述語', 'A verb can describe a noun too: put it right before the noun. 昨日買った傘 = "the umbrella (I) bought yesterday". Japanese needs no word for "that" or "which": the position is enough. 昨日 stays right before 買った because it says when you bought it: before 壊れた it would mean the umbrella broke yesterday.', 'Anche un verbo può descrivere un nome: basta metterlo subito prima del nome. 昨日買った傘 = «l''ombrello (che) ho comprato ieri». Il giapponese non ha bisogno di una parola per «che»: basta la posizione. 昨日 sta subito prima di 買った perché dice quando l''hai comprato: prima di 壊れた vorrebbe dire che si è rotto ieri.'),
  ('349ef8de-fce0-5138-84a5-10426df29fe8', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"静かな町に住んでいる","kana":"しずかなまちにすんでいる"},"answer":"静かな","distractors":["静かだ","静かの","静かい"],"gap":{"kanji":"＿町に住んでいる","kana":"＿まちにすんでいる"},"prompt":{"en":"\"I live in a quiet town.\" Which form of 静か goes before a noun?","it":"«Vivo in una città tranquilla.» Quale forma di 静か va davanti a un nome?"},"translation":{"en":"I live in a quiet town.","it":"Vivo in una città tranquilla."},"glosses":[{"text":"静かな","reading":"しずかな"},{"text":"静かだ","reading":"しずかだ"},{"text":"静かの","reading":"しずかの"},{"text":"静かい","reading":"しずかい"}]}'::jsonb, '名詞を修飾する「な」', '静か (quiet) is a な-adjective (an adjective that needs な before a noun). At the end of a sentence it takes だ ("is"): 町が静かだ, "the town is quiet". Before a noun, だ becomes な: 静かな町, "a quiet town".', '静か (tranquillo) è un aggettivo in な (un aggettivo che vuole な davanti a un nome). A fine frase prende だ (cioè «è»): 町が静かだ, «la città è tranquilla». Davanti a un nome, だ diventa な: 静かな町, «una città tranquilla».'),
  ('dfcc733a-c32e-5f45-9fd1-43b4c27d2055', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"有名な歌手が来た","kana":"ゆうめいなかしゅがきた"},"answer":["有名な","歌手が","来た"],"prompt":{"en":"Build: \"A famous singer came.\"","it":"Componi: «È venuto un cantante famoso.»"},"translation":{"en":"A famous singer came.","it":"È venuto un cantante famoso."},"glosses":[{"text":"有名な","reading":"ゆうめいな","meaning":{"en":"famous","it":"famoso"}},{"text":"歌手が","reading":"かしゅが","meaning":{"en":"a singer (the one who came)","it":"un cantante (chi è venuto)"}},{"text":"来た","reading":"きた","meaning":{"en":"came","it":"è venuto"}}]}'::jsonb, '名詞を修飾する「な」', '有名 (famous) is a な-adjective (an adjective that needs な before a noun), so: 有名な歌手, "a famous singer". Then が marks who did the action, and the verb 来た (came) goes last.', '有名 (famoso) è un aggettivo in な (un aggettivo che vuole な davanti a un nome), quindi: 有名な歌手, «un cantante famoso». Poi が indica chi ha fatto l''azione, e il verbo 来た (è venuto) va in fondo.'),
  ('79ae205c-615d-5647-9b01-d6800dee970c', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"木の机を買った","kana":"きのつくえをかった"},"answer":"の","distractors":["な","が"],"gap":{"kanji":"木＿机を買った","kana":"き＿つくえをかった"},"prompt":{"en":"\"I bought a wooden desk.\" Which particle links 木 to 机?","it":"«Ho comprato una scrivania di legno.» Quale particella collega 木 a 机?"},"translation":{"en":"I bought a wooden desk.","it":"Ho comprato una scrivania di legno."},"glosses":[{"text":"の"},{"text":"な"},{"text":"が"}]}'::jsonb, '名詞を修飾する「の」', '木 (wood) is a normal noun, not an adjective, so it cannot take な. When a noun describes another noun (whose it is, what it is made of, what kind it is), Japanese puts の between them: 木の机, "a desk of wood".', '木 (legno) è un nome normale, non un aggettivo, quindi non può prendere な. Quando un nome descrive un altro nome (di chi è, di che materiale è, di che tipo è), il giapponese mette の fra i due: 木の机, «una scrivania di legno».'),
  ('3be87963-5201-5b19-a2c5-b8b43bc26ea1', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"日本語の先生が来た","kana":"にほんごのせんせいがきた"},"answer":"の","distractors":["な","だ"],"gap":{"kanji":"日本語＿先生が来た","kana":"にほんご＿せんせいがきた"},"prompt":{"en":"\"The Japanese teacher came.\" Which particle links the two nouns?","it":"«È venuto l''insegnante di giapponese.» Quale particella collega i due nomi?"},"translation":{"en":"The Japanese teacher came.","it":"È venuto l''insegnante di giapponese."},"glosses":[{"text":"の"},{"text":"な"},{"text":"だ"}]}'::jsonb, '名詞を修飾する「の」', '日本語の先生 = "teacher of Japanese": の joins two nouns and says what kind of teacher. だ means "is" and goes at the end of a sentence, not between nouns. な is only for な-adjectives like 静か.', '日本語の先生 = «insegnante di giapponese»: の unisce due nomi e dice che tipo di insegnante è. だ vuol dire «è» e va a fine frase, non fra due nomi. な serve solo agli aggettivi in な come 静か.'),
  ('1f20e07c-7443-527b-9988-cd47e56ee9e9', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"きれいな花を買った","kana":"きれいなはなをかった"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part describes the flowers?","it":"Quale parte descrive i fiori?"},"translation":{"en":"I bought pretty flowers.","it":"Ho comprato dei bei fiori."},"glosses":[{"text":"きれいな","meaning":{"en":"pretty","it":"belli"}},{"text":"花を買","reading":"はなをか","meaning":{"en":"flowers, buy","it":"fiori, comprare"}},{"text":"った","meaning":{"en":"past ending of 買う (bought)","it":"desinenza del passato di 買う (comprato)"}}]}'::jsonb, '名詞を修飾する「な」', 'Select きれいな (pretty). きれい ends in い, but it is a な-adjective (an adjective that needs な before a noun), not an い-adjective. So before 花 (flowers) it becomes きれいな.', 'Seleziona きれいな (belli). きれい finisce in い, ma è un aggettivo in な (un aggettivo che vuole な davanti a un nome), non un aggettivo in い. Quindi davanti a 花 (fiori) diventa きれいな.'),
  ('b33f988e-8704-5ad9-92bf-12514e0cd894', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"あそこにいる人は先生だ","kana":"あそこにいるひとはせんせいだ"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part tells you which person we mean?","it":"Quale parte dice di quale persona si parla?"},"translation":{"en":"The person over there is a teacher.","it":"La persona laggiù è un insegnante."},"glosses":[{"text":"あそこにいる","meaning":{"en":"who is over there","it":"che è laggiù"}},{"text":"人は先生","reading":"ひとはせんせい","meaning":{"en":"person (the topic), teacher","it":"persona (l''argomento), insegnante"}},{"text":"だ","meaning":{"en":"is","it":"è"}}]}'::jsonb, '名詞を修飾する述語', 'Select あそこにいる ("is over there"). A verb placed right before a noun describes it: あそこにいる人 = "the person who is over there". At the end, だ is the word for "is": "...is a teacher".', 'Seleziona あそこにいる («è laggiù»). Un verbo messo subito prima di un nome lo descrive: あそこにいる人 = «la persona che è laggiù». In fondo, だ è la parola per «è»: «...è un insegnante».'),
  ('8f080662-e371-50cf-992a-a9e4560700e2', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"姉の車は赤い","kana":"あねのくるまはあかい"},"answer":["姉の","車は","赤い"],"prompt":{"en":"Build: \"My older sister''s car is red.\"","it":"Componi: «La macchina di mia sorella maggiore è rossa.»"},"translation":{"en":"My older sister''s car is red.","it":"La macchina di mia sorella maggiore è rossa."},"glosses":[{"text":"姉の","reading":"あねの","meaning":{"en":"my older sister''s","it":"di mia sorella maggiore"}},{"text":"車は","reading":"くるまは","meaning":{"en":"the car (the topic)","it":"la macchina (l''argomento)"}},{"text":"赤い","reading":"あかい","meaning":{"en":"is red","it":"è rossa"}}]}'::jsonb, '名詞を修飾する「の」', '姉の車 = "my older sister''s car": の goes after the owner, and the owner comes before the thing. Then は marks what we talk about, and 赤い (red) closes the sentence: an い-adjective alone already means "is red".', '姉の車 = «la macchina di mia sorella maggiore»: の va dopo chi possiede, e chi possiede viene prima della cosa. Poi は indica di cosa si parla, e 赤い (rosso) chiude la frase: un aggettivo in い da solo significa già «è rosso».'),
  ('9b92691c-3dbe-5d5f-90c2-1338b5fa7cee', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"新しい服を買った","kana":"あたらしいふくをかった"},"answer":"新しい","distractors":["新しいな","新しいの","新しいだ"],"gap":{"kanji":"＿服を買った","kana":"＿ふくをかった"},"prompt":{"en":"\"I bought new clothes.\" Which form of 新しい goes before 服?","it":"«Ho comprato dei vestiti nuovi.» Quale forma di 新しい va davanti a 服?"},"translation":{"en":"I bought new clothes.","it":"Ho comprato dei vestiti nuovi."},"glosses":[{"text":"新しい","reading":"あたらしい"},{"text":"新しいな","reading":"あたらしいな"},{"text":"新しいの","reading":"あたらしいの"},{"text":"新しいだ","reading":"あたらしいだ"}]}'::jsonb, '名詞を修飾する述語', '新しい (new) is an い-adjective (an adjective ending in い). It goes straight before the noun, with nothing in between: 新しい服, "new clothes". な is only for な-adjectives, and の only joins two nouns.', '新しい (nuovo) è un aggettivo in い (un aggettivo che finisce in い). Va direttamente davanti al nome, senza niente in mezzo: 新しい服, «vestiti nuovi». な serve solo agli aggettivi in な, e の unisce solo due nomi.'),
  ('68810005-2d0e-5560-8808-f1efad1c47d8', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"これは祖母が編んだセーターだ","kana":"これはそぼがあんだセーターだ"},"answer":"編んだ","distractors":["編んだの","編んだな"],"gap":{"kanji":"これは祖母が＿セーターだ","kana":"これはそぼが＿セーターだ"},"prompt":{"en":"\"This is the sweater my grandmother knitted.\" What goes before セーター?","it":"«Questo è il maglione che ha fatto a maglia mia nonna.» Cosa va davanti a セーター?"},"translation":{"en":"This is the sweater my grandmother knitted.","it":"Questo è il maglione che ha fatto a maglia mia nonna."},"glosses":[{"text":"編んだ","reading":"あんだ"},{"text":"編んだの","reading":"あんだの"},{"text":"編んだな","reading":"あんだな"}]}'::jsonb, '名詞を修飾する述語', 'A verb can describe a noun by standing right before it, with nothing in between: 祖母が編んだセーター, "the sweater (that) my grandmother knitted". の only joins two nouns, and な is only for な-adjectives (adjectives that need な before a noun), so neither goes after a verb.', 'Un verbo può descrivere un nome mettendosi subito prima, senza niente in mezzo: 祖母が編んだセーター, «il maglione (che) ha fatto a maglia mia nonna». の unisce solo due nomi, e な serve solo agli aggettivi in な (gli aggettivi che vogliono な davanti a un nome), quindi nessuno dei due va dopo un verbo.'),
  ('b40fa7c7-052f-547b-b992-fc54913d4311', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"窓から見える山はきれいだ","kana":"まどからみえるやまはきれいだ"},"answer":["窓から","見える","山は","きれいだ"],"prompt":{"en":"Build: \"The mountain you can see from the window is beautiful.\"","it":"Componi: «La montagna che si vede dalla finestra è bella.»"},"translation":{"en":"The mountain you can see from the window is beautiful.","it":"La montagna che si vede dalla finestra è bella."},"glosses":[{"text":"窓から","reading":"まどから","meaning":{"en":"from the window","it":"dalla finestra"}},{"text":"見える","reading":"みえる","meaning":{"en":"can be seen (describes the mountain)","it":"si vede (descrive la montagna)"}},{"text":"山は","reading":"やまは","meaning":{"en":"the mountain (the topic)","it":"la montagna (l''argomento)"}},{"text":"きれいだ","meaning":{"en":"is beautiful","it":"è bella"}}]}'::jsonb, '名詞を修飾する述語', '窓から見える (can be seen from the window) is a whole little sentence placed before 山 (mountain) to describe it: "the mountain that can be seen from the window". 窓から stays right before 見える: it is from the window that you see it. Then は marks what we talk about, and きれいだ (is beautiful) closes the sentence.', '窓から見える (si vede dalla finestra) è una piccola frase intera messa davanti a 山 (montagna) per descriverla: «la montagna che si vede dalla finestra». 窓から sta subito prima di 見える: è dalla finestra che la vedi. Poi は indica di cosa si parla, e きれいだ (è bella) chiude la frase.'),
  ('cd3a9111-abee-5262-bc29-ac5b27992e01', '名詞を修飾する述語', 'single-select', '{"sentence":{"kanji":"駅の近くに便利な店がある","kana":"えきのちかくにべんりなみせがある"},"answer":"な","distractors":["の","だ"],"gap":{"kanji":"駅の近くに便利＿店がある","kana":"えきのちかくにべんり＿みせがある"},"prompt":{"en":"\"There is a handy shop near the station.\" Which word links 便利 to 店?","it":"«Vicino alla stazione c''è un negozio comodo.» Quale parola collega 便利 a 店?"},"translation":{"en":"There is a handy shop near the station.","it":"Vicino alla stazione c''è un negozio comodo."},"glosses":[{"text":"な"},{"text":"の"},{"text":"だ"}]}'::jsonb, '名詞を修飾する「な」', '便利 (handy, convenient) is a な-adjective (an adjective that needs な before a noun): 便利な店, "a handy shop". だ means "is" and only goes at the end: 店が便利だ, "the shop is handy". の joins two nouns, but 便利 is an adjective.', '便利 (comodo) è un aggettivo in な (un aggettivo che vuole な davanti a un nome): 便利な店, «un negozio comodo». だ vuol dire «è» e va solo a fine frase: 店が便利だ, «il negozio è comodo». の unisce due nomi, ma 便利 è un aggettivo.'),
  ('80a101ed-759d-5e45-9c39-d26c26f5f997', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"すてきな帽子をもらった","kana":"すてきなぼうしをもらった"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I got a lovely hat.\" Which part describes the hat?","it":"«Ho ricevuto un bel cappello.» Quale parte descrive il cappello?"},"translation":{"en":"I got a lovely hat.","it":"Ho ricevuto un bel cappello."},"glosses":[{"text":"すてきな","meaning":{"en":"lovely","it":"bello"}},{"text":"帽子","reading":"ぼうし","meaning":{"en":"hat","it":"cappello"}},{"text":"をもらった","meaning":{"en":"received (it)","it":"ho ricevuto"}}]}'::jsonb, '名詞を修飾する「な」', 'Select すてきな (lovely). すてき is a な-adjective (an adjective that needs な before a noun), so before 帽子 (hat) it becomes すてきな. The describing word always comes before the noun it describes.', 'Seleziona すてきな (bello). すてき è un aggettivo in な (un aggettivo che vuole な davanti a un nome), quindi davanti a 帽子 (cappello) diventa すてきな. La parola che descrive viene sempre prima del nome che descrive.'),
  ('f12a6045-36d6-5f64-89e8-04f4c98025a5', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"元気な子犬が庭を走っている","kana":"げんきなこいぬがにわをはしっている"},"answer":["元気な","子犬が","庭を","走っている"],"alsoAccepted":[["庭を","元気な","子犬が","走っている"]],"prompt":{"en":"Build: \"A lively puppy is running around the garden.\"","it":"Componi: «Un cucciolo vivace sta correndo in giardino.»"},"translation":{"en":"A lively puppy is running around the garden.","it":"Un cucciolo vivace sta correndo in giardino."},"glosses":[{"text":"元気な","reading":"げんきな","meaning":{"en":"lively","it":"vivace"}},{"text":"子犬が","reading":"こいぬが","meaning":{"en":"a puppy (the one running)","it":"un cucciolo (chi corre)"}},{"text":"庭を","reading":"にわを","meaning":{"en":"around the garden","it":"per il giardino"}},{"text":"走っている","reading":"はしっている","meaning":{"en":"is running","it":"sta correndo"}}]}'::jsonb, '名詞を修飾する「な」', '元気 (lively, full of energy) is a な-adjective (an adjective that needs な before a noun), so: 元気な子犬, "a lively puppy". 元気な must stay right before 子犬. Then 庭を (around the garden) and the verb 走っている (is running) at the end. "庭を元気な子犬が走っている" is also correct: 庭を can come first, as long as 元気な子犬 stays together.', '元気 (vivace, pieno di energia) è un aggettivo in な (un aggettivo che vuole な davanti a un nome), quindi: 元気な子犬, «un cucciolo vivace». 元気な deve stare subito prima di 子犬. Poi 庭を (per il giardino) e il verbo 走っている (sta correndo) in fondo. Va bene anche «庭を元気な子犬が走っている»: 庭を può venire per primo, basta che 元気な子犬 resti unito.'),
  ('d37b8620-7f1c-5de9-81d2-b1eaa716bff2', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"イタリアの車が好きだ","kana":"イタリアのくるまがすきだ"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I like Italian cars.\" Which part says what kind of car?","it":"«Mi piacciono le macchine italiane.» Quale parte dice che tipo di macchina?"},"translation":{"en":"I like Italian cars.","it":"Mi piacciono le macchine italiane."},"glosses":[{"text":"イタリアの","meaning":{"en":"from Italy, Italian","it":"dell''Italia, italiana"}},{"text":"車が好","reading":"くるまがす","meaning":{"en":"cars, liked","it":"macchine, piacere"}},{"text":"きだ","meaning":{"en":"end of 好き + だ (is liked)","it":"fine di 好き + だ (piace)"}}]}'::jsonb, '名詞を修飾する「の」', 'Select イタリアの. イタリア (Italy) is a noun: to describe another noun it needs の in between. イタリアの車 = "car of Italy", that is "Italian car". The noun that describes always comes first.', 'Seleziona イタリアの. イタリア (Italia) è un nome: per descrivere un altro nome vuole の in mezzo. イタリアの車 = «macchina dell''Italia», cioè «macchina italiana». Il nome che descrive viene sempre per primo.'),
  ('4d86b953-a0ca-5fc3-ae25-8a9e2a224bc0', '名詞を修飾する述語', 'select-span', '{"sentence":{"kanji":"サッカーの試合を見た","kana":"サッカーのしあいをみた"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I watched a football match.\" Which part says what kind of match?","it":"«Ho guardato una partita di calcio.» Quale parte dice che tipo di partita?"},"translation":{"en":"I watched a football match.","it":"Ho guardato una partita di calcio."},"glosses":[{"text":"サッカーの","meaning":{"en":"of football","it":"di calcio"}},{"text":"試合を見","reading":"しあいをみ","meaning":{"en":"match, watch","it":"partita, guardare"}},{"text":"た","meaning":{"en":"past ending","it":"desinenza del passato"}}]}'::jsonb, '名詞を修飾する「の」', 'Select サッカーの (of football). サッカー and 試合 (match) are both nouns, so の goes between them: サッカーの試合, "a football match". The first noun says what kind the second one is.', 'Seleziona サッカーの (di calcio). サッカー e 試合 (partita) sono due nomi, quindi fra loro va の: サッカーの試合, «una partita di calcio». Il primo nome dice di che tipo è il secondo.'),
  ('ef032b50-ebad-5bff-b930-684231de3e7f', '名詞を修飾する述語', 'assemble', '{"sentence":{"kanji":"春の風は気持ちいい","kana":"はるのかぜはきもちいい"},"answer":["春の","風は","気持ちいい"],"prompt":{"en":"Build: \"The spring wind feels nice.\"","it":"Componi: «Il vento di primavera è piacevole.»"},"translation":{"en":"The spring wind feels nice.","it":"Il vento di primavera è piacevole."},"glosses":[{"text":"春の","reading":"はるの","meaning":{"en":"of spring","it":"di primavera"}},{"text":"風は","reading":"かぜは","meaning":{"en":"the wind (the topic)","it":"il vento (l''argomento)"}},{"text":"気持ちいい","reading":"きもちいい","meaning":{"en":"feels nice","it":"è piacevole"}}]}'::jsonb, '名詞を修飾する「の」', '春 (spring) is a noun, so to describe 風 (wind) it takes の: 春の風, "the spring wind". Then は marks what we talk about, and 気持ちいい (feels nice), an adjective ending in い, closes the sentence on its own.', '春 (primavera) è un nome, quindi per descrivere 風 (vento) prende の: 春の風, «il vento di primavera». Poi は indica di cosa si parla, e 気持ちいい (è piacevole), un aggettivo che finisce in い, chiude la frase da solo.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('de4b81da-1d12-5346-860e-ea0c1cad7e66', '否定の-ない', 'single-select', '{"sentence":{"kanji":"今日は時間がない","kana":"きょうはじかんがない"},"answer":"ない","distractors":["あらない","ないだ","なく"],"gap":{"kanji":"今日は時間が＿","kana":"きょうはじかんが＿"},"prompt":{"en":"\"I have no time today.\" How do you say \"there is not\" (the negative of ある)?","it":"«Oggi non ho tempo.» Come si dice «non c''è» (la negazione di ある)?"},"translation":{"en":"I have no time today.","it":"Oggi non ho tempo."},"glosses":[{"text":"ない"},{"text":"あらない"},{"text":"ないだ"},{"text":"なく"}]}'::jsonb, '否定の「ない」', 'ある ("there is") has an irregular negative: it is simply ない ("there is not"); あらない does not exist. ない is an い-adjective (a word that ends in い and already contains "is", like 高い = "is expensive"), so nothing goes after it: no だ ("is").', 'ある («c''è») ha una negazione irregolare: è semplicemente ない («non c''è»); あらない non esiste. ない è un aggettivo in い (una parola che finisce in い e contiene già il «è», come 高い = «è caro»), quindi dopo non vuole niente: niente だ («è»).'),
  ('b377835e-ce27-5345-8523-26d307f4fa86', '否定の-ない', 'single-select', '{"sentence":{"kanji":"兄はお酒を飲まない","kana":"あにはおさけをのまない"},"answer":"飲まない","distractors":["飲むない","飲みない","飲まらない"],"gap":{"kanji":"兄はお酒を＿","kana":"あにはおさけを＿"},"prompt":{"en":"\"My older brother doesn''t drink alcohol.\" How do you say \"doesn''t drink\" (from 飲む)?","it":"«Mio fratello maggiore non beve alcolici.» Come si dice «non beve» (da 飲む)?"},"translation":{"en":"My older brother doesn''t drink alcohol.","it":"Mio fratello maggiore non beve alcolici."},"glosses":[{"text":"飲まない","reading":"のまない"},{"text":"飲むない","reading":"のむない"},{"text":"飲みない","reading":"のみない"},{"text":"飲まらない","reading":"のまらない"}]}'::jsonb, '否定の「ない」', 'To make a verb negative, change its last kana from the u-sound to the a-sound, then add ない: 飲む → 飲ま + ない = 飲まない ("doesn''t drink"). You never put ない straight after the dictionary form: 飲むない is wrong.', 'Per negare un verbo si cambia l''ultimo kana dal suono u al suono a e poi si aggiunge ない: 飲む → 飲ま + ない = 飲まない («non beve»). ない non si mette mai direttamente dopo la forma base: 飲むない è sbagliato.'),
  ('42743f63-d12a-5fe3-845f-62a6c9511434', '否定の-ない', 'single-select', '{"sentence":{"kanji":"母は肉を買わない","kana":"はははにくをかわない"},"answer":"買わない","distractors":["買あない","買いない","買うない"],"gap":{"kanji":"母は肉を＿","kana":"はははにくを＿"},"prompt":{"en":"\"My mother doesn''t buy meat.\" How do you say \"doesn''t buy\" (from 買う)?","it":"«Mia madre non compra carne.» Come si dice «non compra» (da 買う)?"},"translation":{"en":"My mother doesn''t buy meat.","it":"Mia madre non compra carne."},"glosses":[{"text":"買わない","reading":"かわない"},{"text":"買あない","reading":"かあない"},{"text":"買いない","reading":"かいない"},{"text":"買うない","reading":"かうない"}]}'::jsonb, '否定の「ない」', 'Verbs ending in う are the one exception: before ない, う does not become あ but わ. So 買う ("to buy") → 買わ + ない = 買わない. 買あない does not exist.', 'I verbi che finiscono in う sono l''unica eccezione: davanti a ない, う non diventa あ ma わ. Quindi 買う («comprare») → 買わ + ない = 買わない. 買あない non esiste.'),
  ('15e5d9ee-259e-58fd-952b-2a29db6134f7', '否定の-ない', 'select-span', '{"sentence":{"kanji":"あれは駅ではない","kana":"あれはえきではない"},"answer":{"start":2,"end":3},"prompt":{"en":"\"That is not the station.\" Which part means \"is not\"?","it":"«Quella non è la stazione.» Quale parte significa «non è»?"},"translation":{"en":"That is not the station.","it":"Quella non è la stazione."},"glosses":[{"text":"あれは","meaning":{"en":"that one (は: the topic)","it":"quella (は: il tema)"}},{"text":"駅","reading":"えき","meaning":{"en":"station","it":"stazione"}},{"text":"ではない","meaning":{"en":"is not","it":"non è"}}]}'::jsonb, '名詞文の否定「ではない」', 'Select ではない ("is not"). After a noun, "is" is だ: 駅だ = "it is the station". To negate it, だ becomes ではない: 駅ではない; in casual speech people say じゃない.', 'Seleziona ではない («non è»). Dopo un nome, «è» si dice だ: 駅だ = «è la stazione». Per negarla, だ diventa ではない: 駅ではない; nel parlato informale si dice じゃない.'),
  ('ef8c40a5-800f-5e9f-a558-497b7536040a', '否定の-ない', 'single-select', '{"sentence":{"kanji":"この部屋は寒くない","kana":"このへやはさむくない"},"answer":"寒くない","distractors":["寒いない","寒いではない","寒じゃない"],"gap":{"kanji":"この部屋は＿","kana":"このへやは＿"},"prompt":{"en":"\"This room is not cold.\" How do you say \"is not cold\" (from 寒い)?","it":"«Questa stanza non è fredda.» Come si dice «non è fredda» (da 寒い)?"},"translation":{"en":"This room is not cold.","it":"Questa stanza non è fredda."},"glosses":[{"text":"寒くない","reading":"さむくない"},{"text":"寒いない","reading":"さむいない"},{"text":"寒いではない","reading":"さむいではない"},{"text":"寒じゃない","reading":"さむじゃない"}]}'::jsonb, '形容詞の否定「くない」', '寒い ("is cold") is an い-adjective: it ends in い and already contains "is". To negate it, replace the final い with く and add ない: 寒い → 寒くない. ではない goes after nouns, not after い-adjectives.', '寒い («è freddo») è un aggettivo in い: finisce in い e contiene già il «è». Per negarlo si sostituisce la い finale con く e si aggiunge ない: 寒い → 寒くない. ではない va dopo i nomi, non dopo gli aggettivi in い.'),
  ('fba6f22c-731b-51d4-a33f-9b4f83ba8de9', '否定の-ない', 'single-select', '{"sentence":{"kanji":"この映画はよくない","kana":"このえいがはよくない"},"answer":"よくない","distractors":["いくない","いいない","よいない"],"gap":{"kanji":"この映画は＿","kana":"このえいがは＿"},"prompt":{"en":"\"This film is not good.\" How do you say \"is not good\" (from いい)?","it":"«Questo film non è bello.» Come si dice «non è bello» (da いい)?"},"translation":{"en":"This film is not good.","it":"Questo film non è bello."},"glosses":[{"text":"よくない"},{"text":"いくない"},{"text":"いいない"},{"text":"よいない"}]}'::jsonb, '形容詞の否定「くない」', 'いい ("is good") is irregular: every change starts from its older form, よい. So "is not good" is よくない, and "was good" is よかった. いくない does not exist.', 'いい («è buono, è bello») è irregolare: ogni cambiamento parte dalla sua forma antica, よい. Quindi «non è bello» è よくない e «era bello» è よかった. いくない non esiste.'),
  ('b340d16c-bcce-5281-806c-2f88c74cfb10', '否定の-ない', 'assemble', '{"sentence":{"kanji":"昨日は雨が降らなかった","kana":"きのうはあめがふらなかった"},"answer":["昨日は","雨が","降らなかった"],"prompt":{"en":"Build: \"It did not rain yesterday.\"","it":"Componi: «Ieri non è piovuto.»"},"translation":{"en":"It did not rain yesterday.","it":"Ieri non è piovuto."},"glosses":[{"text":"昨日は","reading":"きのうは","meaning":{"en":"yesterday (は: the topic)","it":"ieri (は: il tema)"}},{"text":"雨が","reading":"あめが","meaning":{"en":"the rain (が: the subject)","it":"la pioggia (が: il soggetto)"}},{"text":"降らなかった","reading":"ふらなかった","meaning":{"en":"did not fall","it":"non è caduta"}}]}'::jsonb, '否定の「ない」', 'For "did not", first make the negative 降らない ("does not fall"), then turn the final い of ない into かった, as with any い-adjective: 降らなかった. The order is: when (昨日は), the subject (雨が), and the verb last.', 'Per il «non» al passato si fa prima il negativo 降らない («non cade»), poi la い finale di ない diventa かった, come in ogni aggettivo in い: 降らなかった. L''ordine è: quando (昨日は), il soggetto (雨が) e il verbo alla fine.'),
  ('a1216140-12ce-5d2a-935e-ab787b263c95', '否定の-ない', 'select-span', '{"sentence":{"kanji":"テレビを見なかった","kana":"テレビをみなかった"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I didn''t watch TV.\" Which part means \"didn''t\" (\"not\" in the past)?","it":"«Non ho guardato la TV.» Quale parte è il «non» al passato?"},"translation":{"en":"I didn''t watch TV.","it":"Non ho guardato la TV."},"glosses":[{"text":"テレビを","meaning":{"en":"TV (を: the object)","it":"la TV (を: l''oggetto)"}},{"text":"見","reading":"み","meaning":{"en":"watch (the verb without る)","it":"guardare (il verbo senza る)"}},{"text":"なかった","meaning":{"en":"did not","it":"non (al passato)"}}]}'::jsonb, '否定の「ない」', 'Select なかった. 見る ("to watch") is an ichidan verb (a verb that simply drops る before an ending): 見る → 見 + ない = 見ない. The past of ない is なかった, so 見なかった = "didn''t watch".', 'Seleziona なかった. 見る («guardare») è un verbo ichidan (un verbo che perde solo る prima di una desinenza): 見る → 見 + ない = 見ない. Il passato di ない è なかった, quindi 見なかった = «non ho guardato».'),
  ('52bf43ea-e519-5318-be37-3953bf03d7be', '否定の-ない', 'single-select', '{"sentence":{"kanji":"私はたばこを吸いません","kana":"わたしはたばこをすいません"},"answer":"吸いません","distractors":["吸わません","吸うません","吸いまさない"],"gap":{"kanji":"私はたばこを＿","kana":"わたしはたばこを＿"},"prompt":{"en":"\"I don''t smoke.\" How do you say \"don''t smoke\" politely (from 吸う)?","it":"«Non fumo.» Come si dice «non fumo» in modo cortese (da 吸う)?"},"translation":{"en":"I don''t smoke.","it":"Non fumo."},"glosses":[{"text":"吸いません","reading":"すいません"},{"text":"吸わません","reading":"すわません"},{"text":"吸うません","reading":"すうません"},{"text":"吸いまさない","reading":"すいまさない"}]}'::jsonb, '丁寧な否定「ません」', 'In polite speech, "not" is ません, the negative of ます (the polite verb ending). Like ます, it goes after the i-stem, the verb with its last kana changed to the i-sound: 吸う → 吸い. So 吸います ("I smoke") becomes 吸いません ("I don''t smoke").', 'Nel registro cortese il «non» è ません, la forma negativa di ます (la desinenza cortese del verbo). Come ます, si attacca al radicale in i, cioè il verbo con l''ultimo kana cambiato nel suono i: 吸う → 吸い. Quindi 吸います («fumo») diventa 吸いません («non fumo»).'),
  ('0166bf28-bd05-5e80-b39f-30fd30d7b0be', '否定の-ない', 'assemble', '{"sentence":{"kanji":"これは私の傘ではない","kana":"これはわたしのかさではない"},"answer":["これは","私の","傘","ではない"],"prompt":{"en":"Build: \"This is not my umbrella.\"","it":"Componi: «Questo non è il mio ombrello.»"},"translation":{"en":"This is not my umbrella.","it":"Questo non è il mio ombrello."},"glosses":[{"text":"これは","meaning":{"en":"this (は: the topic)","it":"questo (は: il tema)"}},{"text":"私の","reading":"わたしの","meaning":{"en":"my","it":"il mio"}},{"text":"傘","reading":"かさ","meaning":{"en":"umbrella","it":"ombrello"}},{"text":"ではない","meaning":{"en":"is not","it":"non è"}}]}'::jsonb, '名詞文の否定「ではない」', 'After a noun, "is not" is ではない, the negative of だ (the word for "is" after nouns). It goes at the very end, right after the noun: 傘ではない = "is not an umbrella". The owner comes before the thing, joined by の: 私の傘 = "my umbrella".', 'Dopo un nome, «non è» si dice ではない, la forma negativa di だ (la parola che fa da «è» dopo i nomi). Va proprio alla fine, subito dopo il nome: 傘ではない = «non è un ombrello». Il possessore viene prima della cosa, unito da の: 私の傘 = «il mio ombrello».'),
  ('09dc7975-5a07-51e0-82d1-db9850ad2cb5', '否定の-ない', 'assemble', '{"sentence":{"kanji":"この時計はぜんぜん動かない","kana":"このとけいはぜんぜんうごかない"},"answer":["この時計は","ぜんぜん","動かない"],"prompt":{"en":"Build: \"This clock doesn''t work at all.\"","it":"Componi: «Quest''orologio non funziona per niente.»"},"translation":{"en":"This clock doesn''t work at all.","it":"Quest''orologio non funziona per niente."},"glosses":[{"text":"この時計は","reading":"このとけいは","meaning":{"en":"this clock (は: the topic)","it":"quest''orologio (は: il tema)"}},{"text":"ぜんぜん","meaning":{"en":"(not) at all","it":"(non) per niente"}},{"text":"動かない","reading":"うごかない","meaning":{"en":"doesn''t move, doesn''t work","it":"non si muove, non funziona"}}]}'::jsonb, '否定の「ない」', '動く ("to move, to work") ends in く. For the negative, く changes to the a-sound, か, and ない is added: 動かない. ぜんぜん before a negative means "not at all", and it goes right before the verb it negates. The topic comes first and the verb goes last.', '動く («muoversi, funzionare») finisce in く. Per la negazione, く passa al suono a, か, e si aggiunge ない: 動かない. ぜんぜん davanti a una negazione significa «per niente», e va subito prima del verbo che nega. Il tema va all''inizio e il verbo alla fine.'),
  ('085dab24-ba05-51b6-a21a-1094f53a7b5e', '否定の-ない', 'single-select', '{"sentence":{"kanji":"明日は休みではない","kana":"あしたはやすみではない"},"answer":"ではない","distractors":["くない","だない","ないだ"],"gap":{"kanji":"明日は休み＿","kana":"あしたはやすみ＿"},"prompt":{"en":"\"Tomorrow is not a day off.\" How do you say \"is not\" after the noun 休み (\"day off\")?","it":"«Domani non è un giorno libero.» Come si dice «non è» dopo il nome 休み («giorno libero»)?"},"translation":{"en":"Tomorrow is not a day off.","it":"Domani non è un giorno libero."},"glosses":[{"text":"ではない"},{"text":"くない"},{"text":"だない"},{"text":"ないだ"}]}'::jsonb, '名詞文の否定「ではない」', '休み ("day off") is a noun. After a noun, "is" is だ, and "is not" is ではない: 休みではない. くない is only for い-adjectives (words that end in い, like 高い = "is expensive"). だ never takes ない directly, so だない does not exist, and nothing goes after ない: ないだ is wrong too.', '休み («giorno libero») è un nome. Dopo un nome, «è» si dice だ e «non è» si dice ではない: 休みではない. くない serve solo per gli aggettivi in い (parole che finiscono in い, come 高い = «è caro»). だ non prende mai ない direttamente, quindi だない non esiste, e dopo ない non va niente: anche ないだ è sbagliato.'),
  ('251b0e1a-4eca-5e5c-a45c-294fcdf36887', '否定の-ない', 'single-select', '{"sentence":{"kanji":"あの人は日本人ではなかった","kana":"あのひとはにほんじんではなかった"},"answer":"ではなかった","distractors":["ではないだった","だなかった","ではなかっただ"],"gap":{"kanji":"あの人は日本人＿","kana":"あのひとはにほんじん＿"},"prompt":{"en":"\"That person was not Japanese.\" How do you say \"was not\" after a noun?","it":"«Quella persona non era giapponese.» Come si dice «non era» dopo un nome?"},"translation":{"en":"That person was not Japanese.","it":"Quella persona non era giapponese."},"glosses":[{"text":"ではなかった"},{"text":"ではないだった"},{"text":"だなかった"},{"text":"ではなかっただ"}]}'::jsonb, '名詞文の否定「ではない」', 'The past of ではない ("is not") is ではなかった ("was not"): the final い of ない becomes かった, as in every い-adjective. だった is the past of だ ("is"), but it cannot come after ない: ではないだった is wrong.', 'Il passato di ではない («non è») è ではなかった («non era»): la い finale di ない diventa かった, come in ogni aggettivo in い. だった è il passato di だ («è»), ma non può venire dopo ない: ではないだった è sbagliato.'),
  ('9a89de50-8d8f-511e-928e-a95ae7eb9a9f', '否定の-ない', 'select-span', '{"sentence":{"kanji":"これは砂糖じゃない","kana":"これはさとうじゃない"},"answer":{"start":2,"end":3},"prompt":{"en":"\"This isn''t sugar.\" Which part is the casual \"is not\"?","it":"«Questo non è zucchero.» Quale parte è il «non è» informale?"},"translation":{"en":"This isn''t sugar.","it":"Questo non è zucchero."},"glosses":[{"text":"これは","meaning":{"en":"this (は: the topic)","it":"questo (は: il tema)"}},{"text":"砂糖","reading":"さとう","meaning":{"en":"sugar","it":"zucchero"}},{"text":"じゃない","meaning":{"en":"is not (casual)","it":"non è (informale)"}}]}'::jsonb, '名詞文の否定「ではない」', 'Select じゃない. After a noun, "is not" is ではない; in everyday speech では shrinks to じゃ, so people say じゃない: 砂糖じゃない = "it isn''t sugar". The meaning is the same, only more casual.', 'Seleziona じゃない. Dopo un nome, «non è» si dice ではない; nel parlato di tutti i giorni では si accorcia in じゃ, quindi si dice じゃない: 砂糖じゃない = «non è zucchero». Il significato è lo stesso, solo più informale.'),
  ('390d2948-ac09-58ae-a349-573ab6e0e123', '否定の-ない', 'assemble', '{"sentence":{"kanji":"駅前の店はもうパン屋ではない","kana":"えきまえのみせはもうパンやではない"},"answer":["駅前の店は","もう","パン屋","ではない"],"alsoAccepted":[["もう","駅前の店は","パン屋","ではない"]],"prompt":{"en":"Build: \"The shop in front of the station is no longer a bakery.\"","it":"Componi: «Il negozio davanti alla stazione non è più una panetteria.»"},"translation":{"en":"The shop in front of the station is no longer a bakery.","it":"Il negozio davanti alla stazione non è più una panetteria."},"glosses":[{"text":"駅前の店は","reading":"えきまえのみせは","meaning":{"en":"the shop in front of the station (は: the topic)","it":"il negozio davanti alla stazione (は: il tema)"}},{"text":"もう","meaning":{"en":"anymore (with a negative)","it":"più (con una negazione)"}},{"text":"パン屋","reading":"パンや","meaning":{"en":"bakery","it":"panetteria"}},{"text":"ではない","meaning":{"en":"is not","it":"non è"}}]}'::jsonb, '名詞文の否定「ではない」', 'パン屋 ("bakery") is a noun, so "is not" after it is ではない, at the very end. もう with a negative means "no longer": もうパン屋ではない = "is no longer a bakery". The topic, 駅前の店は, comes first. "もう駅前の店はパン屋ではない" is also correct: like a time word, もう can also open the sentence. パン屋ではない always stays together at the end.', 'パン屋 («panetteria») è un nome, quindi dopo di lui «non è» si dice ではない, proprio alla fine. もう con una negazione significa «non più»: もうパン屋ではない = «non è più una panetteria». Il tema, 駅前の店は, va all''inizio. Va bene anche «もう駅前の店はパン屋ではない»: come una parola di tempo, もう può anche aprire la frase. パン屋ではない resta sempre unito, in fondo.'),
  ('f699ef88-5f7c-5460-90f7-0d56fa4e1da3', '否定の-ない', 'select-span', '{"sentence":{"kanji":"このカレーは辛くない","kana":"このカレーはからくない"},"answer":{"start":2,"end":3},"prompt":{"en":"\"This curry is not spicy.\" Which part makes 辛い (\"spicy\") negative?","it":"«Questo curry non è piccante.» Quale parte rende negativo 辛い («piccante»)?"},"translation":{"en":"This curry is not spicy.","it":"Questo curry non è piccante."},"glosses":[{"text":"このカレーは","meaning":{"en":"this curry (は: the topic)","it":"questo curry (は: il tema)"}},{"text":"辛","reading":"から","meaning":{"en":"spicy (the adjective without い)","it":"piccante (l''aggettivo senza い)"}},{"text":"くない","meaning":{"en":"is not","it":"non è"}}]}'::jsonb, '形容詞の否定「くない」', 'Select くない. 辛い ("is spicy") is an い-adjective (a word that ends in い and already contains "is"). To negate it, the final い becomes く and ない is added: 辛い → 辛くない.', 'Seleziona くない. 辛い («è piccante») è un aggettivo in い (una parola che finisce in い e contiene già il «è»). Per negarlo, la い finale diventa く e si aggiunge ない: 辛い → 辛くない.'),
  ('4325c595-3d35-52d8-87df-87ad71ba5eab', '否定の-ない', 'assemble', '{"sentence":{"kanji":"家は駅から遠くない","kana":"いえはえきからとおくない"},"answer":["家は","駅から","遠くない"],"prompt":{"en":"Build: \"My house is not far from the station.\"","it":"Componi: «Casa mia non è lontana dalla stazione.»"},"translation":{"en":"My house is not far from the station.","it":"Casa mia non è lontana dalla stazione."},"glosses":[{"text":"家は","reading":"いえは","meaning":{"en":"(my) house (は: the topic)","it":"casa (mia) (は: il tema)"}},{"text":"駅から","reading":"えきから","meaning":{"en":"from the station","it":"dalla stazione"}},{"text":"遠くない","reading":"とおくない","meaning":{"en":"is not far","it":"non è lontana"}}]}'::jsonb, '形容詞の否定「くない」', '遠い ("is far") is an い-adjective: its negative is 遠くない ("is not far"), with い changed to く before ない. Like a verb, it goes at the end: first the topic (家は), then "from the station" (駅から).', '遠い («è lontano») è un aggettivo in い: la sua negazione è 遠くない («non è lontano»), con la い cambiata in く davanti a ない. Come un verbo, va alla fine: prima il tema (家は), poi «dalla stazione» (駅から).'),
  ('a48eb7a4-3928-5428-8fa3-49294510b622', '否定の-ない', 'single-select', '{"sentence":{"kanji":"昨日のテストは難しくなかった","kana":"きのうのテストはむずかしくなかった"},"answer":"難しくなかった","distractors":["難しいなかった","難しくないだった","難しいではなかった"],"gap":{"kanji":"昨日のテストは＿","kana":"きのうのテストは＿"},"prompt":{"en":"\"Yesterday''s exam was not difficult.\" How do you say \"was not difficult\" (from 難しい)?","it":"«L''esame di ieri non era difficile.» Come si dice «non era difficile» (da 難しい)?"},"translation":{"en":"Yesterday''s exam was not difficult.","it":"L''esame di ieri non era difficile."},"glosses":[{"text":"難しくなかった","reading":"むずかしくなかった"},{"text":"難しいなかった","reading":"むずかしいなかった"},{"text":"難しくないだった","reading":"むずかしくないだった"},{"text":"難しいではなかった","reading":"むずかしいではなかった"}]}'::jsonb, '形容詞の否定「くない」', 'First make the negative: 難しい → 難しくない ("is not difficult"). ない ends in い, so its past works like any い-adjective: い becomes かった, giving 難しくなかった. だった (the past of だ, "is") never goes after an い-adjective, and ではなかった is only for nouns.', 'Prima si fa la negazione: 難しい → 難しくない («non è difficile»). ない finisce in い, quindi il suo passato funziona come in ogni aggettivo in い: la い diventa かった, e si ottiene 難しくなかった. だった (il passato di だ, «è») non va mai dopo un aggettivo in い, e ではなかった è solo per i nomi.'),
  ('95f98e9c-8bfa-5038-ab64-aeff49569c72', '否定の-ない', 'assemble', '{"sentence":{"kanji":"このレストランはあまり高くない","kana":"このレストランはあまりたかくない"},"answer":["このレストランは","あまり","高くない"],"prompt":{"en":"Build: \"This restaurant is not very expensive.\"","it":"Componi: «Questo ristorante non è molto caro.»"},"translation":{"en":"This restaurant is not very expensive.","it":"Questo ristorante non è molto caro."},"glosses":[{"text":"このレストランは","meaning":{"en":"this restaurant (は: the topic)","it":"questo ristorante (は: il tema)"}},{"text":"あまり","meaning":{"en":"(not) very","it":"(non) molto"}},{"text":"高くない","reading":"たかくない","meaning":{"en":"is not expensive","it":"non è caro"}}]}'::jsonb, '形容詞の否定「くない」', '高い ("is expensive") is an い-adjective, so "is not expensive" is 高くない: the final い becomes く before ない. あまり goes right before a negative and softens it: あまり高くない = "not very expensive". The adjective goes last, like a verb.', '高い («è caro») è un aggettivo in い, quindi «non è caro» è 高くない: la い finale diventa く davanti a ない. あまり si mette subito prima di una negazione e la attenua: あまり高くない = «non molto caro». L''aggettivo va alla fine, come un verbo.'),
  ('b929f095-5ee8-5110-879f-0acb79c68a29', '否定の-ない', 'single-select', '{"sentence":{"kanji":"週末は目覚ましをかけません","kana":"しゅうまつはめざましをかけません"},"answer":"かけません","distractors":["かけりません","かけるません","かけまさない"],"gap":{"kanji":"週末は目覚ましを＿","kana":"しゅうまつはめざましを＿"},"prompt":{"en":"\"At the weekend I don''t set the alarm.\" How do you say \"don''t set\" politely (from かける)?","it":"«Nel fine settimana non metto la sveglia.» Come si dice «non metto» in modo cortese (da かける)?"},"translation":{"en":"At the weekend I don''t set the alarm.","it":"Nel fine settimana non metto la sveglia."},"glosses":[{"text":"かけません"},{"text":"かけりません"},{"text":"かけるません"},{"text":"かけまさない"}]}'::jsonb, '丁寧な否定「ません」', 'かける ("to set", here an alarm) is an ichidan verb (a verb that simply drops る before an ending). The polite "not" is ません, and it goes where ます goes: かけ + ません = かけません. The dictionary form never comes before ません: かけるません is wrong.', 'かける («mettere», qui la sveglia) è un verbo ichidan (un verbo che perde solo る prima di una desinenza). Il «non» cortese è ません, e va dove va ます: かけ + ません = かけません. La forma base non va mai davanti a ません: かけるません è sbagliato.'),
  ('fa3d08db-3c69-5c3f-aa14-cfd189aff539', '否定の-ない', 'single-select', '{"sentence":{"kanji":"昨日は誰にも会いませんでした","kana":"きのうはだれにもあいませんでした"},"answer":"会いませんでした","distractors":["会いませんだった","会わませんでした","会いますでした"],"gap":{"kanji":"昨日は誰にも＿","kana":"きのうはだれにも＿"},"prompt":{"en":"\"Yesterday I didn''t see anyone.\" How do you say \"didn''t see\" politely (from 会う, \"to meet\")?","it":"«Ieri non ho visto nessuno.» Come si dice «non ho visto» in modo cortese (da 会う, «incontrare»)?"},"translation":{"en":"Yesterday I didn''t see anyone.","it":"Ieri non ho visto nessuno."},"glosses":[{"text":"会いませんでした","reading":"あいませんでした"},{"text":"会いませんだった","reading":"あいませんだった"},{"text":"会わませんでした","reading":"あわませんでした"},{"text":"会いますでした","reading":"あいますでした"}]}'::jsonb, '丁寧な否定「ません」', 'The polite past of "not" is ません + でした: 会いません ("I don''t meet") → 会いませんでした ("I didn''t meet"). ません is not an い-adjective, so it does not take だった. Like ます, it follows the i-stem (the verb with its last kana changed to the i-sound): 会う → 会い, not 会わ. 誰にも with a negative means "nobody".', 'Il passato cortese del «non» è ません + でした: 会いません («non incontro») → 会いませんでした («non ho incontrato»). ません non è un aggettivo in い, quindi non prende だった. Come ます, si attacca al radicale in i (il verbo con l''ultimo kana cambiato nel suono i): 会う → 会い, non 会わ. 誰にも con una negazione significa «nessuno».'),
  ('9c217f7b-73c9-5ad7-a424-b66d7bc5bb0f', '否定の-ない', 'single-select', '{"sentence":{"kanji":"日曜日は仕事をしません","kana":"にちようびはしごとをしません"},"answer":"しません","distractors":["さません","すません","しないません"],"gap":{"kanji":"日曜日は仕事を＿","kana":"にちようびはしごとを＿"},"prompt":{"en":"\"I don''t work on Sundays.\" How do you say \"don''t do\" politely (from する)?","it":"«La domenica non lavoro.» Come si dice «non faccio» in modo cortese (da する)?"},"translation":{"en":"I don''t work on Sundays.","it":"La domenica non lavoro."},"glosses":[{"text":"しません"},{"text":"さません"},{"text":"すません"},{"text":"しないません"}]}'::jsonb, '丁寧な否定「ません」', 'する ("to do") is irregular: before ます and ません it becomes し. So します ("I do") becomes しません ("I don''t do"); 仕事をしません = "I don''t work". ません already contains "not": adding ない as well, as in しないません, is wrong.', 'する («fare») è irregolare: davanti a ます e ません diventa し. Quindi します («faccio») diventa しません («non faccio»); 仕事をしません = «non lavoro». ません contiene già il «non»: aggiungere anche ない, come in しないません, è sbagliato.'),
  ('c0274108-b082-5cb8-b616-d1cba3504bc8', '否定の-ない', 'select-span', '{"sentence":{"kanji":"このシャツはもう着ません","kana":"このシャツはもうきません"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I don''t wear this shirt anymore.\" Which part is the polite \"not\"?","it":"«Questa camicia non la metto più.» Quale parte è il «non» cortese?"},"translation":{"en":"I don''t wear this shirt anymore.","it":"Questa camicia non la metto più."},"glosses":[{"text":"このシャツはもう","meaning":{"en":"this shirt (は: the topic) + anymore","it":"questa camicia (は: il tema) + più"}},{"text":"着","reading":"き","meaning":{"en":"wear (the verb without る)","it":"indossare (il verbo senza る)"}},{"text":"ません","meaning":{"en":"do not (polite)","it":"non (cortese)"}}]}'::jsonb, '丁寧な否定「ません」', 'Select ません. 着る ("to wear") is an ichidan verb (it simply drops る), so 着 + ます = 着ます ("I wear") and 着 + ません = 着ません ("I don''t wear"). With もう, the negative means "not anymore".', 'Seleziona ません. 着る («indossare») è un verbo ichidan (perde solo る), quindi 着 + ます = 着ます («indosso») e 着 + ません = 着ません («non indosso»). Con もう, la negazione significa «non più».'),
  ('bdfc07ee-3cb3-58e4-b502-7c0d013e6dcc', '否定の-ない', 'assemble', '{"sentence":{"kanji":"この町は雪が降りません","kana":"このまちはゆきがふりません"},"answer":["この町は","雪が","降りません"],"prompt":{"en":"Build: \"It doesn''t snow in this town.\"","it":"Componi: «In questa città non nevica.»"},"translation":{"en":"It doesn''t snow in this town.","it":"In questa città non nevica."},"glosses":[{"text":"この町は","reading":"このまちは","meaning":{"en":"this town (は: the topic)","it":"questa città (は: il tema)"}},{"text":"雪が","reading":"ゆきが","meaning":{"en":"snow (が: the subject)","it":"la neve (が: il soggetto)"}},{"text":"降りません","reading":"ふりません","meaning":{"en":"does not fall (polite)","it":"non cade (cortese)"}}]}'::jsonb, '丁寧な否定「ません」', '降りません is the polite negative of 降る ("to fall", for rain and snow): 降る → 降り (the i-stem, the form used before ます) + ません. The topic (この町は) comes first, then what falls (雪が), and the verb goes last.', '降りません è la negazione cortese di 降る («cadere», per pioggia e neve): 降る → 降り (il radicale in i, la forma che si usa davanti a ます) + ません. Prima il tema (この町は), poi ciò che cade (雪が), e il verbo alla fine.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('890ece21-e470-5522-9007-238149cdf418', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"毎週手紙を書きます","kana":"まいしゅうてがみをかきます"},"answer":"書きます","distractors":["書くます","書かます","書こます"],"gap":{"kanji":"毎週手紙を＿","kana":"まいしゅうてがみを＿"},"prompt":{"en":"\"I write a letter every week.\" How do you say \"write\" politely (from 書く)?","it":"«Ogni settimana scrivo una lettera.» Come si dice «scrivo» in modo cortese (da 書く)?"},"translation":{"en":"I write a letter every week.","it":"Ogni settimana scrivo una lettera."},"glosses":[{"text":"書きます","reading":"かきます"},{"text":"書くます","reading":"かくます"},{"text":"書かます","reading":"かかます"},{"text":"書こます","reading":"かこます"}]}'::jsonb, '連用形につく「ます」「たい」', 'ます is an auxiliary (a piece added to a verb that changes its tone or meaning): it makes the verb polite. It attaches to the i-stem, the verb with its last kana changed to the i-sound: 書く → 書き + ます = 書きます. The meaning stays the same; only the tone becomes polite.', 'ます è un ausiliare (un pezzo che si aggiunge al verbo e ne cambia il tono o il significato): rende il verbo cortese. Si attacca al radicale in i, cioè il verbo con l''ultimo kana cambiato nel suono i: 書く → 書き + ます = 書きます. Il significato resta lo stesso, cambia solo il tono.'),
  ('9c01efa2-0480-512a-b7ec-ace89c604eb4', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"ゆっくり休みたい","kana":"ゆっくりやすみたい"},"answer":"休みたい","distractors":["休むたい","休またい","休みったい"],"gap":{"kanji":"ゆっくり＿","kana":"ゆっくり＿"},"prompt":{"en":"\"I want to rest properly.\" How do you say \"want to rest\" (from 休む)?","it":"«Voglio riposarmi con calma.» Come si dice «voglio riposarmi» (da 休む)?"},"translation":{"en":"I want to rest properly.","it":"Voglio riposarmi con calma."},"glosses":[{"text":"休みたい","reading":"やすみたい"},{"text":"休むたい","reading":"やすむたい"},{"text":"休またい","reading":"やすまたい"},{"text":"休みったい","reading":"やすみったい"}]}'::jsonb, '連用形につく「ます」「たい」', 'To say "want to", add たい to the i-stem (the verb with its last kana changed to the i-sound): 休む → 休み + たい = 休みたい. 休みたい ends in い and works like an い-adjective (a word ending in い that already contains "is"), so "don''t want to rest" is 休みたくない.', 'Per dire «voglio», si aggiunge たい al radicale in i (il verbo con l''ultimo kana cambiato nel suono i): 休む → 休み + たい = 休みたい. 休みたい finisce in い e funziona come un aggettivo in い (una parola in い che contiene già il «è»), quindi «non voglio riposarmi» è 休みたくない.'),
  ('cb90a02a-6d35-5b29-ae38-611a76e319d3', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"一緒に昼ごはんを食べましょう","kana":"いっしょにひるごはんをたべましょう"},"answer":["一緒に","昼ごはんを","食べましょう"],"alsoAccepted":[["昼ごはんを","一緒に","食べましょう"]],"prompt":{"en":"Build: \"Let''s have lunch together.\"","it":"Componi: «Pranziamo insieme.»"},"translation":{"en":"Let''s have lunch together.","it":"Pranziamo insieme."},"glosses":[{"text":"一緒に","reading":"いっしょに","meaning":{"en":"together","it":"insieme"}},{"text":"昼ごはんを","reading":"ひるごはんを","meaning":{"en":"lunch (を: the object)","it":"il pranzo (を: l''oggetto)"}},{"text":"食べましょう","reading":"たべましょう","meaning":{"en":"let''s eat","it":"mangiamo"}}]}'::jsonb, '連用形につく「ます」「たい」', 'ましょう means "let''s…" in polite speech; it comes from ます and attaches in the same place. 食べる is an ichidan verb (a verb that simply drops る), so the stem is 食べ and "let''s eat" is 食べましょう. The verb goes last, after "together" (一緒に) and the object (昼ごはんを). "昼ごはんを一緒に食べましょう" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'ましょう significa «facciamo…» nel registro cortese; deriva da ます e si attacca nello stesso punto. 食べる è un verbo ichidan (un verbo che perde solo る), quindi il radicale è 食べ e «mangiamo» è 食べましょう. Il verbo va alla fine, dopo «insieme» (一緒に) e l''oggetto (昼ごはんを). Va bene anche «昼ごはんを一緒に食べましょう»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('5fd847ca-3b86-509a-94eb-615047363693', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"先生が生徒に本を読ませた","kana":"せんせいがせいとにほんをよませた"},"answer":"読ませた","distractors":["読みせた","読むさせた","読めさせた"],"gap":{"kanji":"先生が生徒に本を＿","kana":"せんせいがせいとにほんを＿"},"prompt":{"en":"\"The teacher had the pupils read a book.\" How do you say \"made (them) read\" (from 読む)?","it":"«L''insegnante ha fatto leggere un libro agli studenti.» Come si dice «ha fatto leggere» (da 読む)?"},"translation":{"en":"The teacher had the pupils read a book.","it":"L''insegnante ha fatto leggere un libro agli studenti."},"glosses":[{"text":"読ませた","reading":"よませた"},{"text":"読みせた","reading":"よみせた"},{"text":"読むさせた","reading":"よむさせた"},{"text":"読めさせた","reading":"よめさせた"}]}'::jsonb, '未然形につく「せる」「れる」', 'The causative means "make or let someone do". For verbs like 読む, change the last kana to the a-sound and add せる: 読む → 読ま + せる = 読ませる; in the past, 読ませた. The person who is made to act takes に: 生徒に = "the pupils".', 'Il causativo significa «far fare» o «lasciar fare». Per verbi come 読む si cambia l''ultimo kana nel suono a e si aggiunge せる: 読む → 読ま + せる = 読ませる; al passato, 読ませた. La persona a cui si fa fare l''azione prende に: 生徒に = «agli studenti».'),
  ('82a7d415-c9cc-5d00-8d43-37bb64d9afd1', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"母が子供に野菜を食べさせた","kana":"ははがこどもにやさいをたべさせた"},"answer":"食べさせた","distractors":["食べせた","食べらせた","食べませた"],"gap":{"kanji":"母が子供に野菜を＿","kana":"ははがこどもにやさいを＿"},"prompt":{"en":"\"The mother made the child eat vegetables.\" How do you say \"made (him) eat\" (from 食べる)?","it":"«La madre ha fatto mangiare le verdure al bambino.» Come si dice «ha fatto mangiare» (da 食べる)?"},"translation":{"en":"The mother made the child eat vegetables.","it":"La madre ha fatto mangiare le verdure al bambino."},"glosses":[{"text":"食べさせた","reading":"たべさせた"},{"text":"食べせた","reading":"たべせた"},{"text":"食べらせた","reading":"たべらせた"},{"text":"食べませた","reading":"たべませた"}]}'::jsonb, '未然形につく「せる」「れる」', '食べる is an ichidan verb (a verb that simply drops る before an ending). Ichidan verbs take the longer form of the causative ("make someone do"), させる: 食べる → 食べ + させる = 食べさせる; in the past, 食べさせた. The same holds for every auxiliary with two forms: the longer one goes on ichidan verbs.', '食べる è un verbo ichidan (un verbo che perde solo る prima di una desinenza). I verbi ichidan prendono la forma lunga del causativo («far fare»), させる: 食べる → 食べ + させる = 食べさせる; al passato, 食べさせた. Vale per ogni ausiliare con due forme: quella lunga va sui verbi ichidan.'),
  ('60424dec-be6d-5efb-a460-98282ec99bf0', '動詞の語幹と助動詞', 'select-span', '{"sentence":{"kanji":"財布を盗まれた","kana":"さいふをぬすまれた"},"answer":{"start":1,"end":2},"prompt":{"en":"\"My wallet was stolen.\" Which part makes 盗む (\"to steal\") passive and past?","it":"«Mi hanno rubato il portafoglio.» Quale parte rende 盗む («rubare») passivo e al passato?"},"translation":{"en":"My wallet was stolen.","it":"Mi hanno rubato il portafoglio."},"glosses":[{"text":"財布を盗","reading":"さいふをぬす","meaning":{"en":"the wallet (を: the object) + steal (first part)","it":"il portafoglio (を: l''oggetto) + rubare (prima parte)"}},{"text":"まれた","meaning":{"en":"was …-en (passive, past)","it":"è stato … (passivo, passato)"}}]}'::jsonb, '未然形につく「せる」「れる」', 'Select まれた. The passive ("something is done to someone") adds れる to the verb with its last kana changed to the a-sound: 盗む → 盗ま + れる; in the past, 盗まれた. So the part you select starts with ま, the changed last kana of 盗む, followed by れた. The person it happened to ("me") is understood and not said.', 'Seleziona まれた. Il passivo («qualcosa viene fatto a qualcuno») aggiunge れる al verbo con l''ultimo kana cambiato nel suono a: 盗む → 盗ま + れる; al passato, 盗まれた. Per questo la parte da selezionare comincia con ま, l''ultimo kana di 盗む cambiato, seguito da れた. Chi l''ha subito («io») è sottinteso e non si dice.'),
  ('219d9482-5afc-5f6c-bddf-de8c75155efa', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"一緒に帰ろう","kana":"いっしょにかえろう"},"answer":"帰ろう","distractors":["帰りよう","帰るう","帰よう"],"gap":{"kanji":"一緒に＿","kana":"いっしょに＿"},"prompt":{"en":"\"Let''s go home together.\" How do you say \"let''s go home\" (from 帰る)?","it":"«Torniamo a casa insieme.» Come si dice «torniamo a casa» (da 帰る)?"},"translation":{"en":"Let''s go home together.","it":"Torniamo a casa insieme."},"glosses":[{"text":"帰ろう","reading":"かえろう"},{"text":"帰りよう","reading":"かえりよう"},{"text":"帰るう","reading":"かえるう"},{"text":"帰よう","reading":"かえよう"}]}'::jsonb, '意向形', 'The volitional form means "let''s…" (casual). For most verbs, change the last kana to the o-sound and add う: 帰る → 帰ろ + う = 帰ろう. 帰る ends in -eru but is not an ichidan verb (one that simply drops る), so it does not take よう.', 'La forma volitiva significa «facciamo…!» (informale). Per la maggior parte dei verbi si cambia l''ultimo kana nel suono o e si aggiunge う: 帰る → 帰ろ + う = 帰ろう. 帰る finisce in -eru ma non è un verbo ichidan (uno che perde solo る), quindi non prende よう.'),
  ('83685bf3-6246-59cf-b37c-fb267e5680a3', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"そろそろ始めよう","kana":"そろそろはじめよう"},"answer":"始めよう","distractors":["始めろう","始めおう","始まよう"],"gap":{"kanji":"そろそろ＿","kana":"そろそろ＿"},"prompt":{"en":"\"Let''s get started.\" How do you say \"let''s start\" (from 始める)?","it":"«Cominciamo.» Come si dice «cominciamo» (da 始める)?"},"translation":{"en":"Let''s get started.","it":"Cominciamo."},"glosses":[{"text":"始めよう","reading":"はじめよう"},{"text":"始めろう","reading":"はじめろう"},{"text":"始めおう","reading":"はじめおう"},{"text":"始まよう","reading":"はじまよう"}]}'::jsonb, '意向形', '始める ("to begin") is an ichidan verb (a verb that simply drops る before an ending). Its volitional form ("let''s…") drops る and adds よう: 始める → 始め + よう = 始めよう.', '始める («cominciare») è un verbo ichidan (un verbo che perde solo る prima di una desinenza). La sua forma volitiva («facciamo…!») toglie る e aggiunge よう: 始める → 始め + よう = 始めよう.'),
  ('3c0f7198-df17-5a0f-9d70-bc512d087a11', '動詞の語幹と助動詞', 'select-span', '{"sentence":{"kanji":"もっと寝たい","kana":"もっとねたい"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I want to sleep more.\" Which part is the auxiliary, the piece added to the verb?","it":"«Voglio dormire ancora.» Quale parte è l''ausiliare, il pezzo aggiunto al verbo?"},"translation":{"en":"I want to sleep more.","it":"Voglio dormire ancora."},"glosses":[{"text":"もっと","meaning":{"en":"more","it":"di più, ancora"}},{"text":"寝","reading":"ね","meaning":{"en":"sleep (the verb without る)","it":"dormire (il verbo senza る)"}},{"text":"たい","meaning":{"en":"want to","it":"voglio"}}]}'::jsonb, '動詞の語幹と助動詞', 'Select たい. A Japanese verb is built from a stem (the part that stays fixed, here 寝 from 寝る) plus auxiliaries (pieces added after it that bring a meaning): たい adds "want to". 寝る simply drops る, so 寝 + たい = 寝たい.', 'Seleziona たい. Un verbo giapponese si costruisce con il radicale (la parte che resta fissa, qui 寝 da 寝る) più gli ausiliari (pezzi aggiunti dopo, che portano un significato): たい aggiunge «voglio». 寝る perde solo る, quindi 寝 + たい = 寝たい.'),
  ('7c505681-fe40-53ed-8543-71c94f8918be', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"週末に海で泳ごう","kana":"しゅうまつにうみでおよごう"},"answer":["週末に","海で","泳ごう"],"alsoAccepted":[["海で","週末に","泳ごう"]],"prompt":{"en":"Build: \"Let''s swim in the sea this weekend.\"","it":"Componi: «Questo fine settimana nuotiamo al mare.»"},"translation":{"en":"Let''s swim in the sea this weekend.","it":"Questo fine settimana nuotiamo al mare."},"glosses":[{"text":"週末に","reading":"しゅうまつに","meaning":{"en":"at the weekend","it":"nel fine settimana"}},{"text":"海で","reading":"うみで","meaning":{"en":"in the sea","it":"al mare"}},{"text":"泳ごう","reading":"およごう","meaning":{"en":"let''s swim","it":"nuotiamo"}}]}'::jsonb, '意向形', '泳ごう is the volitional form of 泳ぐ ("to swim"): it means "let''s swim". The last kana changes to the o-sound and う is added: 泳ぐ → 泳ご + う. The verb goes last: first when (週末に), then where (海で). "海で週末に泳ごう" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '泳ごう è la forma volitiva di 泳ぐ («nuotare»): significa «nuotiamo». L''ultimo kana passa al suono o e si aggiunge う: 泳ぐ → 泳ご + う. Il verbo va alla fine: prima quando (週末に), poi dove (海で). Va bene anche «海で週末に泳ごう»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('38198ec2-9f1a-5d38-ab36-2c5705e6e7c7', '動詞の語幹と助動詞', 'select-span', '{"sentence":{"kanji":"さっきニュースを見ました","kana":"さっきニュースをみました"},"answer":{"start":1,"end":2},"prompt":{"en":"\"I watched the news a little while ago.\" Which part is the stem, the part of the verb that stays fixed?","it":"«Poco fa ho guardato il telegiornale.» Quale parte è il radicale, la parte del verbo che resta fissa?"},"translation":{"en":"I watched the news a little while ago.","it":"Poco fa ho guardato il telegiornale."},"glosses":[{"text":"さっきニュースを","meaning":{"en":"a little while ago + the news (を: the object)","it":"poco fa + il telegiornale (を: l''oggetto)"}},{"text":"見","reading":"み","meaning":{"en":"watch (the stem of 見る)","it":"guardare (il radicale di 見る)"}},{"text":"ました","meaning":{"en":"(polite, past)","it":"(cortese, passato)"}}]}'::jsonb, '動詞の語幹と助動詞', 'Select 見. 見る ("to watch") is an ichidan verb (a verb that simply drops る), so its stem (the fixed part that the auxiliaries attach to) is 見. After it comes the auxiliary: ました is ます (polite) in the past. The same stem gives 見ない, 見たい, 見よう.', 'Seleziona 見. 見る («guardare») è un verbo ichidan (un verbo che perde solo る), quindi il suo radicale (la parte fissa a cui si attaccano gli ausiliari) è 見. Dopo viene l''ausiliare: ました è ます (cortese) al passato. Dallo stesso radicale vengono 見ない, 見たい, 見よう.'),
  ('e1cfa1ce-c627-5118-8446-8c53f4f6fb2f', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"この道は車が通らない","kana":"このみちはくるまがとおらない"},"answer":"通らない","distractors":["通りない","通るない","通ろない"],"gap":{"kanji":"この道は車が＿","kana":"このみちはくるまが＿"},"prompt":{"en":"\"Cars don''t go along this road.\" Which form of 通る (\"to pass\") goes before ない?","it":"«Da questa strada non passano macchine.» Quale forma di 通る («passare») va davanti a ない?"},"translation":{"en":"Cars don''t go along this road.","it":"Da questa strada non passano macchine."},"glosses":[{"text":"通らない","reading":"とおらない"},{"text":"通りない","reading":"とおりない"},{"text":"通るない","reading":"とおるない"},{"text":"通ろない","reading":"とおろない"}]}'::jsonb, '動詞の語幹と助動詞', 'Verbs like 通る change their last kana depending on the auxiliary (the piece added after the verb): the a-sound before ない (通らない), the i-sound before ます (通ります), the o-sound before う (通ろう). So before ない it is 通ら.', 'I verbi come 通る cambiano l''ultimo kana a seconda dell''ausiliare (il pezzo che si aggiunge dopo il verbo): suono a davanti a ない (通らない), suono i davanti a ます (通ります), suono o davanti a う (通ろう). Quindi davanti a ない è 通ら.'),
  ('47694bb8-9456-5f87-8898-b8b047b9c7ae', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"夜は窓を閉めます","kana":"よるはまどをしめます"},"answer":"閉めます","distractors":["閉めります","閉まます","閉めるます"],"gap":{"kanji":"夜は窓を＿","kana":"よるはまどを＿"},"prompt":{"en":"\"In the evening I close the window.\" Which form of 閉める (\"to close\") goes before ます?","it":"«La sera chiudo la finestra.» Quale forma di 閉める («chiudere») va davanti a ます?"},"translation":{"en":"In the evening I close the window.","it":"La sera chiudo la finestra."},"glosses":[{"text":"閉めます","reading":"しめます"},{"text":"閉めります","reading":"しめります"},{"text":"閉まます","reading":"しまます"},{"text":"閉めるます","reading":"しめるます"}]}'::jsonb, '動詞の語幹と助動詞', '閉める is an ichidan verb (a verb that simply drops る). Its stem, 閉め, never changes: whatever auxiliary (a piece added after the verb) comes next attaches straight to it: 閉めます, 閉めない, 閉めたい. An extra り, as in 閉めります, appears only in verbs that are not ichidan, like 帰る → 帰ります.', '閉める è un verbo ichidan (un verbo che perde solo る). Il suo radicale, 閉め, non cambia mai: qualunque ausiliare (un pezzo aggiunto dopo il verbo) venga dopo, si attacca direttamente: 閉めます, 閉めない, 閉めたい. Una り in più, come in 閉めります, compare solo nei verbi che non sono ichidan, come 帰る → 帰ります.'),
  ('6ea1f1c2-b5d5-5f38-b671-363aba4f2d0c', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"毎朝公園を走ります","kana":"まいあさこうえんをはしります"},"answer":["毎朝","公園を","走り","ます"],"alsoAccepted":[["公園を","毎朝","走り","ます"]],"prompt":{"en":"Build: \"I run in the park every morning.\"","it":"Componi: «Ogni mattina corro al parco.»"},"translation":{"en":"I run in the park every morning.","it":"Ogni mattina corro al parco."},"glosses":[{"text":"毎朝","reading":"まいあさ","meaning":{"en":"every morning","it":"ogni mattina"}},{"text":"公園を","reading":"こうえんを","meaning":{"en":"through the park (を: where you move)","it":"nel parco (を: dove ci si muove)"}},{"text":"走り","reading":"はしり","meaning":{"en":"run (the stem of 走る)","it":"correre (il radicale di 走る)"}},{"text":"ます","meaning":{"en":"(polite ending)","it":"(desinenza cortese)"}}]}'::jsonb, '動詞の語幹と助動詞', 'The verb is split into two tiles: the stem 走り (the form of 走る used before ます) and the auxiliary ます (a piece added after the stem, here to make it polite). The stem always comes first and the auxiliary right after it, at the end of the sentence. "公園を毎朝走ります" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Il verbo è diviso in due tessere: il radicale 走り (la forma di 走る che si usa davanti a ます) e l''ausiliare ます (un pezzo che si aggiunge dopo il radicale, qui per renderlo cortese). Prima viene sempre il radicale, subito dopo l''ausiliare, in fondo alla frase. Va bene anche «公園を毎朝走ります»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('9dd50b1c-1186-547d-a014-0511e4dc5427', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"今日は家から出ない","kana":"きょうはいえからでない"},"answer":["今日は","家から","出","ない"],"prompt":{"en":"Build: \"Today I''m not leaving the house.\"","it":"Componi: «Oggi non esco di casa.»"},"translation":{"en":"Today I''m not leaving the house.","it":"Oggi non esco di casa."},"glosses":[{"text":"今日は","reading":"きょうは","meaning":{"en":"today (は: the topic)","it":"oggi (は: il tema)"}},{"text":"家から","reading":"いえから","meaning":{"en":"from the house","it":"da casa"}},{"text":"出","reading":"で","meaning":{"en":"go out (the stem of 出る)","it":"uscire (il radicale di 出る)"}},{"text":"ない","meaning":{"en":"not","it":"non"}}]}'::jsonb, '動詞の語幹と助動詞', '出る ("to go out") is an ichidan verb: it drops る, and its stem is just 出. The auxiliary ない ("not") attaches right after the stem: 出 + ない = 出ない. Stem and auxiliary stay together at the end; the time word (今日は) usually comes first.', '出る («uscire») è un verbo ichidan: perde る, e il suo radicale è solo 出. L''ausiliare ない («non») si attacca subito dopo il radicale: 出 + ない = 出ない. Radicale e ausiliare restano insieme in fondo; la parola di tempo (今日は) di solito va all''inizio.'),
  ('e9f56b34-37c7-522d-aceb-058ffa80cd00', '動詞の語幹と助動詞', 'select-span', '{"sentence":{"kanji":"仕事の日はスーツを着ます","kana":"しごとのひはスーツをきます"},"answer":{"start":1,"end":2},"prompt":{"en":"\"On work days I wear a suit.\" Which part makes the verb polite?","it":"«Nei giorni di lavoro metto il completo.» Quale parte rende cortese il verbo?"},"translation":{"en":"On work days I wear a suit.","it":"Nei giorni di lavoro metto il completo."},"glosses":[{"text":"仕事の日はスーツを着","reading":"しごとのひはスーツをき","meaning":{"en":"on work days (は: the topic) + a suit (を) + wear (stem of 着る)","it":"nei giorni di lavoro (は: il tema) + il completo (を) + indossare (radicale di 着る)"}},{"text":"ます","meaning":{"en":"(polite ending)","it":"(desinenza cortese)"}}]}'::jsonb, '連用形につく「ます」「たい」', 'Select ます. ます makes the verb polite without changing its meaning. It attaches to the stem (the part of the verb that stays fixed); 着る ("to wear") simply drops る, so the stem is 着: 着 + ます = 着ます. The same stem takes たい for "want to": 着たい.', 'Seleziona ます. ます rende cortese il verbo senza cambiarne il significato. Si attacca al radicale (la parte del verbo che resta fissa); 着る («indossare») perde solo る, quindi il radicale è 着: 着 + ます = 着ます. Lo stesso radicale prende たい per dire «voglio»: 着たい.'),
  ('33b718bb-4b30-5e09-92b5-dc101ee4f745', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"暑いから冷たいものが飲みたい","kana":"あついからつめたいものがのみたい"},"answer":["暑いから","冷たいものが","飲みたい"],"prompt":{"en":"Build: \"It''s hot, so I want something cold to drink.\"","it":"Componi: «Fa caldo, quindi voglio bere qualcosa di freddo.»"},"translation":{"en":"It''s hot, so I want something cold to drink.","it":"Fa caldo, quindi voglio bere qualcosa di freddo."},"glosses":[{"text":"暑いから","reading":"あついから","meaning":{"en":"because it''s hot","it":"visto che fa caldo"}},{"text":"冷たいものが","reading":"つめたいものが","meaning":{"en":"something cold (が: what you want)","it":"qualcosa di freddo (が: ciò che si vuole)"}},{"text":"飲みたい","reading":"のみたい","meaning":{"en":"want to drink","it":"voglio bere"}}]}'::jsonb, '連用形につく「ます」「たい」', 'たい ("want to") attaches to the i-stem (the form of the verb used before ます): 飲む → 飲み + たい = 飲みたい. With たい, the thing you want can take が instead of を: 冷たいものが飲みたい. The reason (暑いから, "because it''s hot") comes first and the verb last.', 'たい («voglio») si attacca al radicale in i (la forma del verbo usata davanti a ます): 飲む → 飲み + たい = 飲みたい. Con たい, la cosa che si vuole può prendere が invece di を: 冷たいものが飲みたい. La ragione (暑いから, «visto che fa caldo») va all''inizio e il verbo alla fine.'),
  ('d10a46cc-dff3-5f3f-9ff4-c739b30dc3b1', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"夏休みに北海道を旅行したい","kana":"なつやすみにほっかいどうをりょこうしたい"},"answer":"旅行したい","distractors":["旅行するたい","旅行さたい","旅行しったい"],"gap":{"kanji":"夏休みに北海道を＿","kana":"なつやすみにほっかいどうを＿"},"prompt":{"en":"\"In the summer holidays I want to travel around Hokkaido.\" How do you say \"want to travel\" (from 旅行する)?","it":"«Durante le vacanze estive voglio girare l''Hokkaido.» Come si dice «voglio viaggiare» (da 旅行する)?"},"translation":{"en":"In the summer holidays I want to travel around Hokkaido.","it":"Durante le vacanze estive voglio girare l''Hokkaido."},"glosses":[{"text":"旅行したい","reading":"りょこうしたい"},{"text":"旅行するたい","reading":"りょこうするたい"},{"text":"旅行さたい","reading":"りょこうさたい"},{"text":"旅行しったい","reading":"りょこうしったい"}]}'::jsonb, '連用形につく「ます」「たい」', '旅行する is 旅行 ("trip") + する ("to do"). する is irregular: its i-stem (the form used before ます) is し, as in します. たい attaches there: し + たい = したい, so 旅行したい = "want to travel". The dictionary form する never comes before たい.', '旅行する è 旅行 («viaggio») + する («fare»). する è irregolare: il suo radicale in i (la forma usata davanti a ます) è し, come in します. たい si attacca lì: し + たい = したい, quindi 旅行したい = «voglio viaggiare». La forma base する non va mai davanti a たい.'),
  ('7647b61f-26c1-5c41-b03e-5269868f7816', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"電車の中で足を踏まれた","kana":"でんしゃのなかであしをふまれた"},"answer":"踏まれた","distractors":["踏みれた","踏むれた","踏まられた"],"gap":{"kanji":"電車の中で足を＿","kana":"でんしゃのなかであしを＿"},"prompt":{"en":"\"Someone stepped on my foot on the train.\" How do you say \"had (my foot) stepped on\" (the passive of 踏む)?","it":"«Sul treno mi hanno pestato un piede.» Come si dice «mi hanno pestato» (il passivo di 踏む)?"},"translation":{"en":"Someone stepped on my foot on the train.","it":"Sul treno mi hanno pestato un piede."},"glosses":[{"text":"踏まれた","reading":"ふまれた"},{"text":"踏みれた","reading":"ふみれた"},{"text":"踏むれた","reading":"ふむれた"},{"text":"踏まられた","reading":"ふまられた"}]}'::jsonb, '未然形につく「せる」「れる」', 'The passive ("something is done to someone") of verbs like 踏む ("to step on") changes the last kana to the a-sound and adds れる: 踏む → 踏ま + れる = 踏まれる; in the past, 踏まれた. The longer られる is only for ichidan verbs (verbs that simply drop る), so 踏まられた is wrong.', 'Il passivo («qualcosa viene fatto a qualcuno») dei verbi come 踏む («pestare») cambia l''ultimo kana nel suono a e aggiunge れる: 踏む → 踏ま + れる = 踏まれる; al passato, 踏まれた. La forma lunga られる è solo per i verbi ichidan (quelli che perdono solo る), quindi 踏まられた è sbagliato.'),
  ('72b56c4a-10e2-5062-b0a8-77564f29a86b', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"店長がアルバイトに床を掃除させた","kana":"てんちょうがアルバイトにゆかをそうじさせた"},"answer":["店長が","アルバイトに","床を","掃除させた"],"alsoAccepted":[["店長が","床を","アルバイトに","掃除させた"]],"prompt":{"en":"Build: \"The manager had the part-timer clean the floor.\"","it":"Componi: «Il responsabile ha fatto pulire il pavimento al dipendente part-time.»"},"translation":{"en":"The manager had the part-timer clean the floor.","it":"Il responsabile ha fatto pulire il pavimento al dipendente part-time."},"glosses":[{"text":"店長が","reading":"てんちょうが","meaning":{"en":"the manager (が: the subject)","it":"il responsabile (が: il soggetto)"}},{"text":"アルバイトに","meaning":{"en":"the part-timer (に: who is made to do it)","it":"il dipendente part-time (に: chi deve farlo)"}},{"text":"床を","reading":"ゆかを","meaning":{"en":"the floor (を: the object)","it":"il pavimento (を: l''oggetto)"}},{"text":"掃除させた","reading":"そうじさせた","meaning":{"en":"made (them) clean","it":"ha fatto pulire"}}]}'::jsonb, '未然形につく「せる」「れる」', '掃除する ("to clean") ends in する, and the causative ("make someone do") of する is させる: 掃除させる; in the past, 掃除させた. The one who is made to do it takes に (アルバイトに), what gets cleaned takes を (床を), and the verb goes last. "店長が床をアルバイトに掃除させた" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '掃除する («pulire») finisce in する, e il causativo («far fare») di する è させる: 掃除させる; al passato, 掃除させた. Chi deve fare l''azione prende に (アルバイトに), ciò che si pulisce prende を (床を), e il verbo va alla fine. Va bene anche «店長が床をアルバイトに掃除させた»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('2cb36b38-3c52-567f-bbf5-79b9bc57e5db', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"隣の犬に手をかまれた","kana":"となりのいぬにてをかまれた"},"answer":["隣の犬に","手を","かまれた"],"alsoAccepted":[["手を","隣の犬に","かまれた"]],"prompt":{"en":"Build: \"I got bitten on the hand by the neighbours'' dog.\"","it":"Componi: «Il cane dei vicini mi ha morso la mano.»"},"translation":{"en":"I got bitten on the hand by the neighbours'' dog.","it":"Il cane dei vicini mi ha morso la mano."},"glosses":[{"text":"隣の犬に","reading":"となりのいぬに","meaning":{"en":"by the neighbours'' dog","it":"dal cane dei vicini"}},{"text":"手を","reading":"てを","meaning":{"en":"(my) hand (を: the object)","it":"la mano (を: l''oggetto)"}},{"text":"かまれた","meaning":{"en":"got bitten","it":"è stata morsa"}}]}'::jsonb, '未然形につく「せる」「れる」', 'かまれた is the passive of かむ ("to bite"): the last kana changes to the a-sound and れる is added, かむ → かま + れる; in the past, かまれた. In a passive sentence the one who does the action takes に: 隣の犬に = "by the neighbours'' dog". The person it happened to ("me") is understood. "手を隣の犬にかまれた" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'かまれた è il passivo di かむ («mordere»): l''ultimo kana passa al suono a e si aggiunge れる, かむ → かま + れる; al passato, かまれた. In una frase passiva chi fa l''azione prende に: 隣の犬に = «dal cane dei vicini». Chi l''ha subita («io») è sottinteso. Va bene anche «手を隣の犬にかまれた»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('1e6c3233-77a9-5e09-a055-5576c290221f', '動詞の語幹と助動詞', 'select-span', '{"sentence":{"kanji":"今日はもう寝よう","kana":"きょうはもうねよう"},"answer":{"start":1,"end":2},"prompt":{"en":"\"That''s enough for today, let''s go to bed.\" Which part means \"let''s\"?","it":"«Per oggi basta, andiamo a dormire.» Quale parte significa «facciamo…!»?"},"translation":{"en":"That''s enough for today, let''s go to bed.","it":"Per oggi basta, andiamo a dormire."},"glosses":[{"text":"今日はもう寝","reading":"きょうはもうね","meaning":{"en":"today (は: the topic) + now + sleep (stem of 寝る)","it":"oggi (は: il tema) + ormai + dormire (radicale di 寝る)"}},{"text":"よう","meaning":{"en":"let''s","it":"facciamo…!"}}]}'::jsonb, '意向形', 'Select よう. 寝る ("to sleep") is an ichidan verb (a verb that simply drops る), and its volitional form (the "let''s…" form) drops る and adds よう: 寝 + よう = 寝よう ("let''s sleep").', 'Seleziona よう. 寝る («dormire») è un verbo ichidan (un verbo che perde solo る), e la sua forma volitiva (la forma del «facciamo…!») toglie る e aggiunge よう: 寝 + よう = 寝よう («andiamo a dormire»).'),
  ('abfe497d-aaec-512f-be1c-cc5411af909d', '動詞の語幹と助動詞', 'single-select', '{"sentence":{"kanji":"駅までタクシーを呼ぼう","kana":"えきまでタクシーをよぼう"},"answer":"呼ぼう","distractors":["呼びよう","呼ぶう","呼ばう"],"gap":{"kanji":"駅までタクシーを＿","kana":"えきまでタクシーを＿"},"prompt":{"en":"\"Let''s call a taxi to take us to the station.\" How do you say \"let''s call\" (from 呼ぶ)?","it":"«Chiamiamo un taxi per andare alla stazione.» Come si dice «chiamiamo» (da 呼ぶ)?"},"translation":{"en":"Let''s call a taxi to take us to the station.","it":"Chiamiamo un taxi per andare alla stazione."},"glosses":[{"text":"呼ぼう","reading":"よぼう"},{"text":"呼びよう","reading":"よびよう"},{"text":"呼ぶう","reading":"よぶう"},{"text":"呼ばう","reading":"よばう"}]}'::jsonb, '意向形', '呼ぶ ("to call") is not an ichidan verb (one that simply drops る), so for the volitional form ("let''s…") its last kana changes to the o-sound and う is added: 呼ぶ → 呼ぼ + う = 呼ぼう. よう is only for ichidan verbs, so 呼びよう is wrong.', '呼ぶ («chiamare») non è un verbo ichidan (uno che perde solo る), quindi per la forma volitiva («facciamo…!») l''ultimo kana passa al suono o e si aggiunge う: 呼ぶ → 呼ぼ + う = 呼ぼう. よう è solo per i verbi ichidan, quindi 呼びよう è sbagliato.'),
  ('35d4c988-eba3-5b07-89e7-095d9c53ebaf', '動詞の語幹と助動詞', 'assemble', '{"sentence":{"kanji":"今年こそギターを習おう","kana":"ことしこそギターをならおう"},"answer":["今年こそ","ギターを","習おう"],"alsoAccepted":[["ギターを","今年こそ","習おう"]],"prompt":{"en":"Build: \"This year I''m finally going to learn the guitar.\"","it":"Componi: «Quest''anno imparo la chitarra, finalmente.»"},"translation":{"en":"This year I''m finally going to learn the guitar.","it":"Quest''anno imparo la chitarra, finalmente."},"glosses":[{"text":"今年こそ","reading":"ことしこそ","meaning":{"en":"this year, for sure","it":"quest''anno, finalmente"}},{"text":"ギターを","meaning":{"en":"the guitar (を: the object)","it":"la chitarra (を: l''oggetto)"}},{"text":"習おう","reading":"ならおう","meaning":{"en":"I''ll learn","it":"imparo (ho deciso)"}}]}'::jsonb, '意向形', 'The volitional form is not only "let''s…": said to yourself, it means "I''ll…", a decision. 習う ("to learn") ends in う, which becomes お before the added う: 習う → 習お + う = 習おう. The verb goes last. "ギターを今年こそ習おう" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'La forma volitiva non vuol dire solo «facciamo…!»: detta a sé stessi significa «ora lo faccio», una decisione. 習う («imparare») finisce in う, che davanti alla う aggiunta diventa お: 習う → 習お + う = 習おう. Il verbo va alla fine. Va bene anche «ギターを今年こそ習おう»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('65ce9fba-80c4-5be5-a3d4-bdcd2dc6b00f', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"図書館に本を借りに行く","kana":"としょかんにほんをかりにいく"},"answer":["図書館に","本を","借りに","行く"],"alsoAccepted":[["本を","借りに","図書館に","行く"],["本を","図書館に","借りに","行く"]],"prompt":{"en":"Build: \"I go to the library to borrow a book.\"","it":"Componi: «Vado in biblioteca a prendere in prestito un libro.»"},"translation":{"en":"I go to the library to borrow a book.","it":"Vado in biblioteca a prendere in prestito un libro."},"glosses":[{"text":"図書館に","reading":"としょかんに","meaning":{"en":"to the library","it":"in biblioteca"}},{"text":"本を","reading":"ほんを","meaning":{"en":"a book (を: the object)","it":"un libro (を: l''oggetto)"}},{"text":"借りに","reading":"かりに","meaning":{"en":"to borrow (the purpose)","it":"a prendere in prestito (lo scopo)"}},{"text":"行く","reading":"いく","meaning":{"en":"go","it":"vado"}}]}'::jsonb, '目的を示す「に」', 'There are two に here: 図書館に says where you go, 借りに says why you go. For the purpose, take the i-stem of the verb (the form used before ます: 借ります → 借り) and add に. Then comes a verb of movement, like 行く ("to go"). "本を借りに図書館に行く" and "本を図書館に借りに行く" are also correct: the verb has to stay at the end, and before it these pieces can change places. Only 本を must come before 借りに, never after it: it is the book you borrow.', 'Qui ci sono due に: 図書館に dice dove si va, 借りに dice perché si va. Per lo scopo si prende il radicale in i del verbo (la forma che si usa davanti a ます: 借ります → 借り) e si aggiunge に. Poi viene un verbo di movimento, come 行く («andare»). Vanno bene anche «本を借りに図書館に行く» e «本を図書館に借りに行く»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto. Solo 本を deve venire prima di 借りに, mai dopo: è il libro che prendi in prestito.'),
  ('6fd6cdc9-b3a2-595a-a61b-b9601056c094', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"海に泳ぎに行った","kana":"うみにおよぎにいった"},"answer":"泳ぎに","distractors":["泳ぐに","泳いに","泳ぎで"],"gap":{"kanji":"海に＿行った","kana":"うみに＿いった"},"prompt":{"en":"\"I went to the sea to swim.\" How do you say \"to swim\" (the purpose)?","it":"«Sono andato al mare a nuotare.» Come si dice «a nuotare» (lo scopo)?"},"translation":{"en":"I went to the sea to swim.","it":"Sono andato al mare a nuotare."},"glosses":[{"text":"泳ぎに","reading":"およぎに"},{"text":"泳ぐに","reading":"およぐに"},{"text":"泳いに","reading":"およいに"},{"text":"泳ぎで","reading":"およぎで"}]}'::jsonb, '目的を示す「に」', 'To say why you go somewhere, take the i-stem of the verb (the form used before ます: 泳ぎます → 泳ぎ), add に, then a verb like 行く: 泳ぎに行った = "went to swim". The dictionary form 泳ぐ cannot take に here.', 'Per dire perché si va in un posto si prende il radicale in i del verbo (la forma che si usa davanti a ます: 泳ぎます → 泳ぎ), si aggiunge に e poi un verbo come 行く: 泳ぎに行った = «sono andato a nuotare». La forma base 泳ぐ qui non può prendere に.'),
  ('f8fe3190-e688-51fe-83d9-b05fe9c9fdc5', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"猫が庭にいる","kana":"ねこがにわにいる"},"answer":"に","distractors":["で","を"],"gap":{"kanji":"猫が庭＿いる","kana":"ねこがにわ＿いる"},"prompt":{"en":"\"The cat is in the garden.\" Which particle says where the cat is?","it":"«Il gatto è in giardino.» Quale particella dice dove si trova il gatto?"},"translation":{"en":"The cat is in the garden.","it":"Il gatto è in giardino."}}'::jsonb, '存在の場所を示す「に」', 'With いる ("to be there", for people and animals) and ある (the same, for things), the place is marked by に. で is for the place where you do an action ("eat at home"), and just being somewhere is not an action.', 'Con いる («esserci», per persone e animali) e ある (lo stesso, per le cose), il luogo si segna con に. で serve per il luogo dove si fa un''azione («mangiare a casa»), e il semplice trovarsi in un posto non è un''azione.'),
  ('ff2cd48a-e2f0-5e68-ae7d-5db0bcfc73f1', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"ここに傘がある","kana":"ここにかさがある"},"answer":{"start":0,"end":1},"prompt":{"en":"\"There is an umbrella here.\" Which part says where the umbrella is?","it":"«Qui c''è un ombrello.» Quale parte dice dove si trova l''ombrello?"},"translation":{"en":"There is an umbrella here.","it":"Qui c''è un ombrello."},"glosses":[{"text":"ここに","meaning":{"en":"here (に: the place)","it":"qui (に: il luogo)"}},{"text":"傘","reading":"かさ","meaning":{"en":"umbrella","it":"ombrello"}},{"text":"がある","meaning":{"en":"(が: the subject) + there is","it":"(が: il soggetto) + c''è"}}]}'::jsonb, '存在の場所を示す「に」', 'Select ここに ("here"). ある means "there is" (for things), and the place where the thing is takes に. The thing itself, 傘 ("umbrella"), takes が.', 'Seleziona ここに («qui»). ある significa «c''è» (per le cose), e il luogo in cui si trova la cosa prende に. La cosa stessa, 傘 («ombrello»), prende が.'),
  ('369af471-99a9-5cf0-a96d-b23acb38413b', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"兄は医者になった","kana":"あにはいしゃになった"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"兄は医者＿なった","kana":"あにはいしゃ＿なった"},"prompt":{"en":"\"My older brother became a doctor.\" Which particle marks what he became?","it":"«Mio fratello maggiore è diventato medico.» Quale particella segna ciò che è diventato?"},"translation":{"en":"My older brother became a doctor.","it":"Mio fratello maggiore è diventato medico."}}'::jsonb, '変化の結果を示す「に」', 'なる means "to become". What someone or something becomes is marked by に: 医者になった = "became a doctor". This is how it works after a noun, such as 医者 ("doctor").', 'なる significa «diventare». Ciò che qualcuno o qualcosa diventa si segna con に: 医者になった = «è diventato medico». Funziona così dopo un nome, come 医者 («medico»).'),
  ('dd21cd3e-299e-5f96-9c2c-04ebcfb63da1', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"部屋が明るくなった","kana":"へやがあかるくなった"},"answer":"明るく","distractors":["明るいに","明るに","明るいく"],"gap":{"kanji":"部屋が＿なった","kana":"へやが＿なった"},"prompt":{"en":"\"The room became bright.\" Which form of 明るい (\"bright\") goes before なる (\"to become\")?","it":"«La stanza è diventata luminosa.» Quale forma di 明るい («luminoso») va davanti a なる («diventare»)?"},"translation":{"en":"The room became bright.","it":"La stanza è diventata luminosa."},"glosses":[{"text":"明るく","reading":"あかるく"},{"text":"明るに","reading":"あかるに"},{"text":"明るいに","reading":"あかるいに"},{"text":"明るいく","reading":"あかるいく"}]}'::jsonb, '変化の結果を示す「に」', '明るい is an い-adjective (a word that ends in い and already means "is bright"), and に goes after nouns, not after い-adjectives. Before なる, an い-adjective changes its final い into く: 明るくなった = "became bright".', '明るい è un aggettivo in い (una parola che finisce in い e significa già «è luminoso»), e に va dopo i nomi, non dopo gli aggettivi in い. Davanti a なる, un aggettivo in い cambia la い finale in く: 明るくなった = «è diventata luminosa».'),
  ('76e29e2e-d600-5905-8028-5b2f911e6d34', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"来月京都へ行く","kana":"らいげつきょうとへいく"},"answer":"へ","distractors":["が","の"],"gap":{"kanji":"来月京都＿行く","kana":"らいげつきょうと＿いく"},"prompt":{"en":"\"Next month I''m going to Kyoto.\" Which particle marks the direction?","it":"«Il mese prossimo vado a Kyoto.» Quale particella segna la direzione?"},"translation":{"en":"Next month I''m going to Kyoto.","it":"Il mese prossimo vado a Kyoto."}}'::jsonb, '方向を示す「へ」', 'As a particle, へ is read え, and it marks the direction you move in: 京都へ行く = "go to Kyoto". Here に would also be correct, because both can mark where you go. But へ cannot mark where something is: 庭へいる is wrong.', 'Quando è una particella, へ si legge え e indica la direzione in cui ci si muove: 京都へ行く = «andare a Kyoto». Qui andrebbe bene anche に, perché entrambe possono indicare dove si va. Ma へ non può indicare dove si trova qualcosa: 庭へいる è sbagliato.'),
  ('f335e931-eec1-5296-aecf-0a3b39c0a595', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"来年日本に行きます","kana":"らいねんにほんにいきます"},"answer":["来年","日本に","行きます"],"alsoAccepted":[["日本に","来年","行きます"]],"prompt":{"en":"Build: \"Next year I will go to Japan.\"","it":"Componi: «L''anno prossimo andrò in Giappone.»"},"translation":{"en":"Next year I will go to Japan.","it":"L''anno prossimo andrò in Giappone."},"glosses":[{"text":"来年","reading":"らいねん","meaning":{"en":"next year","it":"l''anno prossimo"}},{"text":"日本に","reading":"にほんに","meaning":{"en":"to Japan","it":"in Giappone"}},{"text":"行きます","reading":"いきます","meaning":{"en":"(will) go (polite)","it":"andrò (cortese)"}}]}'::jsonb, '目的地を示す「に」', 'With a verb of movement such as 行く ("to go"), the place you go to is marked by に: 日本に行きます = "go to Japan". A time word like 来年 ("next year") needs no particle and usually comes first. The verb goes last. "日本に来年行きます" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Con un verbo di movimento come 行く («andare»), il posto in cui si va si segna con に: 日本に行きます = «andare in Giappone». Una parola di tempo come 来年 («l''anno prossimo») non vuole particelle e di solito va all''inizio. Il verbo va alla fine. Va bene anche «日本に来年行きます»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('7f40ad29-ce7c-5b2b-bcc7-da693507d83b', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"うちに帰りたい","kana":"うちにかえりたい"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I want to go home.\" Which part says where you want to go?","it":"«Voglio tornare a casa.» Quale parte dice dove si vuole andare?"},"translation":{"en":"I want to go home.","it":"Voglio tornare a casa."},"glosses":[{"text":"うちに","meaning":{"en":"(to) home","it":"a casa"}},{"text":"帰","reading":"かえ","meaning":{"en":"go back (first part of the verb)","it":"tornare (prima parte del verbo)"}},{"text":"りたい","meaning":{"en":"(end of the verb) + want to","it":"(fine del verbo) + voglio"}}]}'::jsonb, '目的地を示す「に」', 'Select うちに ("home"). 帰る means "to go back", and the place you go back to is the destination, marked by に. The same に marks where you go with 行く ("to go") and 来る ("to come").', 'Seleziona うちに («a casa»). 帰る significa «tornare», e il posto in cui si torna è la destinazione, segnata da に. Lo stesso に indica dove si va anche con 行く («andare») e 来る («venire»).'),
  ('c2ec2adf-2acc-5007-9d27-6e7c7b2bc603', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"ここへ来てください","kana":"ここへきてください"},"answer":{"start":0,"end":1},"prompt":{"en":"\"Please come here.\" Which part shows the direction of the movement?","it":"«Vieni qui, per favore.» Quale parte indica la direzione del movimento?"},"translation":{"en":"Please come here.","it":"Vieni qui, per favore."},"glosses":[{"text":"ここへ","meaning":{"en":"(towards) here","it":"(verso) qui"}},{"text":"来","reading":"き","meaning":{"en":"come (first part of the verb)","it":"venire (prima parte del verbo)"}},{"text":"てください","meaning":{"en":"please (do it)","it":"per favore (fallo)"}}]}'::jsonb, '方向を示す「へ」', 'Select ここへ ("here"). The particle へ, read え, marks the direction you move in; 来る ("to come") is a verb of movement, so it can take へ. に would also work: ここに来てください.', 'Seleziona ここへ («qui»). La particella へ, che si legge え, indica la direzione in cui ci si muove; 来る («venire») è un verbo di movimento, quindi può prendere へ. Andrebbe bene anche に: ここに来てください.'),
  ('fdf8067e-a709-5ec0-aa6b-24676759922c', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"お正月は実家に帰る","kana":"おしょうがつはじっかにかえる"},"answer":"に","distractors":["で","を"],"gap":{"kanji":"お正月は実家＿帰る","kana":"おしょうがつはじっか＿かえる"},"prompt":{"en":"\"For New Year I go back to my parents'' home.\" Which particle marks where you go back to?","it":"«Per Capodanno torno a casa dei miei.» Quale particella indica dove si torna?"},"translation":{"en":"For New Year I go back to my parents'' home.","it":"Per Capodanno torno a casa dei miei."}}'::jsonb, '目的地を示す「に」', '帰る ("to go back home") is a verb of movement, and the place you arrive at takes に: 実家に帰る. で marks where an action happens, and を with a verb of movement marks a place you go through, not where you end up.', '帰る («tornare») è un verbo di movimento, e il posto a cui si arriva prende に: 実家に帰る. で indica dove si svolge un''azione, e を con un verbo di movimento indica un posto che si attraversa, non quello dove si arriva.'),
  ('282e14c7-60f1-5f09-935f-a08fdb5effea', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"バスが駅に着きました","kana":"バスがえきにつきました"},"answer":"に","distractors":["を","で"],"gap":{"kanji":"バスが駅＿着きました","kana":"バスがえき＿つきました"},"prompt":{"en":"\"The bus has arrived at the station.\" Which particle marks where the bus arrived?","it":"«L''autobus è arrivato alla stazione.» Quale particella indica dove è arrivato l''autobus?"},"translation":{"en":"The bus has arrived at the station.","it":"L''autobus è arrivato alla stazione."}}'::jsonb, '目的地を示す「に」', '着く ("to arrive") takes に for the place you arrive at: 駅に着きました = "arrived at the station". The place is the end point of the movement, and that is what に marks. 駅で would describe something happening at the station, not arriving there.', '着く («arrivare») prende に per il posto in cui si arriva: 駅に着きました = «è arrivato alla stazione». Il posto è il punto d''arrivo del movimento, ed è proprio questo che segna に. 駅で descriverebbe qualcosa che succede alla stazione, non l''arrivarci.'),
  ('2ef091c3-ceca-52bb-99bf-d280db078bb4', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"急いで教室に入った","kana":"いそいできょうしつにはいった"},"answer":["急いで","教室に","入った"],"alsoAccepted":[["教室に","急いで","入った"]],"prompt":{"en":"Build: \"I hurried into the classroom.\"","it":"Componi: «Sono entrato in classe di corsa.»"},"translation":{"en":"I hurried into the classroom.","it":"Sono entrato in classe di corsa."},"glosses":[{"text":"急いで","reading":"いそいで","meaning":{"en":"in a hurry","it":"di corsa"}},{"text":"教室に","reading":"きょうしつに","meaning":{"en":"into the classroom","it":"in classe"}},{"text":"入った","reading":"はいった","meaning":{"en":"went in","it":"sono entrato"}}]}'::jsonb, '目的地を示す「に」', '入る ("to go in") takes に for the place you go into: 教室に入った = "went into the classroom". The verb goes last. "教室に急いで入った" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '入る («entrare») prende に per il posto in cui si entra: 教室に入った = «sono entrato in classe». Il verbo va alla fine. Va bene anche «教室に急いで入った»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('be1ac01d-16ad-5e7a-844d-ea7d562d209c', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"ホテルに戻ろう","kana":"ホテルにもどろう"},"answer":{"start":0,"end":1},"prompt":{"en":"\"Let''s go back to the hotel.\" Which part says where you go?","it":"«Torniamo in albergo.» Quale parte dice dove si va?"},"translation":{"en":"Let''s go back to the hotel.","it":"Torniamo in albergo."},"glosses":[{"text":"ホテルに","meaning":{"en":"to the hotel","it":"in albergo"}},{"text":"戻","reading":"もど","meaning":{"en":"go back (first part of the verb)","it":"tornare (prima parte del verbo)"}},{"text":"ろう","meaning":{"en":"(end of the verb) + let''s","it":"(fine del verbo) + facciamo…!"}}]}'::jsonb, '目的地を示す「に」', 'Select ホテルに. 戻る ("to go back") is a verb of movement, and the place you go back to is marked by に. ろう is the end of 戻ろう ("let''s go back").', 'Seleziona ホテルに. 戻る («tornare») è un verbo di movimento, e il posto in cui si torna si segna con に. ろう è la fine di 戻ろう («torniamo»).'),
  ('49fd7485-17dc-5cb1-9b28-bf87822d9cda', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"公園へ写真を撮りに行く","kana":"こうえんへしゃしんをとりにいく"},"answer":"撮りに","distractors":["撮るに","撮りで","撮らに"],"gap":{"kanji":"公園へ写真を＿行く","kana":"こうえんへしゃしんを＿いく"},"prompt":{"en":"\"I''m going to the park to take photos.\" How do you say \"to take\" (the purpose)?","it":"«Vado al parco a fare foto.» Come si dice «a fare» (lo scopo)?"},"translation":{"en":"I''m going to the park to take photos.","it":"Vado al parco a fare foto."},"glosses":[{"text":"撮りに","reading":"とりに"},{"text":"撮るに","reading":"とるに"},{"text":"撮りで","reading":"とりで"},{"text":"撮らに","reading":"とらに"}]}'::jsonb, '目的を示す「に」', 'For the purpose of a movement, use the i-stem of the verb (the form used before ます: 撮ります → 撮り) + に, then a verb such as 行く ("to go"). The dictionary form 撮る cannot take this に, and で does not express a purpose.', 'Per lo scopo di un movimento si usa il radicale in i del verbo (la forma usata davanti a ます: 撮ります → 撮り) + に, e poi un verbo come 行く («andare»). La forma base 撮る non può prendere questo に, e で non esprime uno scopo.'),
  ('814740f4-8050-56ef-803c-99973cae2565', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"空港まで祖父を迎えに行った","kana":"くうこうまでそふをむかえにいった"},"answer":["空港まで","祖父を","迎えに","行った"],"alsoAccepted":[["祖父を","迎えに","空港まで","行った"],["祖父を","空港まで","迎えに","行った"]],"prompt":{"en":"Build: \"I went to the airport to pick up my grandfather.\"","it":"Componi: «Sono andato all''aeroporto a prendere mio nonno.»"},"translation":{"en":"I went to the airport to pick up my grandfather.","it":"Sono andato all''aeroporto a prendere mio nonno."},"glosses":[{"text":"空港まで","reading":"くうこうまで","meaning":{"en":"(as far as) the airport","it":"fino all''aeroporto"}},{"text":"祖父を","reading":"そふを","meaning":{"en":"my grandfather (を: the object)","it":"mio nonno (を: l''oggetto)"}},{"text":"迎えに","reading":"むかえに","meaning":{"en":"to pick up (the purpose)","it":"a prendere (lo scopo)"}},{"text":"行った","reading":"いった","meaning":{"en":"went","it":"sono andato"}}]}'::jsonb, '目的を示す「に」', '迎えに gives the purpose, "to pick up": the i-stem of 迎える (the form used before ます: 迎えます → 迎え) + に. A verb of movement follows at the end: 迎えに行った = "went to pick up". "祖父を迎えに空港まで行った" and "祖父を空港まで迎えに行った" are also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places. 祖父を, though, always comes before 迎えに: he is the person you go to pick up.', '迎えに indica lo scopo, «a prendere»: il radicale in i di 迎える (la forma usata davanti a ます: 迎えます → 迎え) + に. Alla fine segue un verbo di movimento: 迎えに行った = «sono andato a prendere». Vanno bene anche «祖父を迎えに空港まで行った» e «祖父を空港まで迎えに行った»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto. 祖父を però viene sempre prima di 迎えに: è la persona che vai a prendere.'),
  ('9cfed543-63ac-512f-b33d-27be9f1f1fc9', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"あそびに来てね","kana":"あそびにきてね"},"answer":{"start":0,"end":1},"prompt":{"en":"\"Come over and hang out!\" Which part says why you should come?","it":"«Passa a trovarmi, eh!» Quale parte dice perché venire?"},"translation":{"en":"Come over and hang out!","it":"Passa a trovarmi, eh!"},"glosses":[{"text":"あそびに","meaning":{"en":"to hang out (the purpose)","it":"a divertirsi, a trovarmi (lo scopo)"}},{"text":"来","reading":"き","meaning":{"en":"come (first part of the verb)","it":"venire (prima parte del verbo)"}},{"text":"てね","meaning":{"en":"(asking) + , OK?","it":"(invito) + , eh?"}}]}'::jsonb, '目的を示す「に」', 'Select あそびに. あそび is the i-stem of あそぶ ("to play, to hang out"; the form used before ます: あそびます), and with に it gives the purpose of coming: あそびに来て = "come to hang out". In friendly messages it is often written in kana like this.', 'Seleziona あそびに. あそび è il radicale in i di あそぶ («giocare, divertirsi»; la forma usata davanti a ます: あそびます), e con に indica lo scopo del venire: あそびに来て = «vieni a divertirti», cioè «vieni a trovarmi». Nei messaggi tra amici si scrive spesso così, in kana.'),
  ('7dd802a6-c742-58b5-b540-02d50f3f4436', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"ランチに出かけた","kana":"ランチにでかけた"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I went out for lunch.\" Which part says what you went out for?","it":"«Sono uscito a pranzo.» Quale parte dice per cosa si è usciti?"},"translation":{"en":"I went out for lunch.","it":"Sono uscito a pranzo."},"glosses":[{"text":"ランチに","meaning":{"en":"for lunch (the purpose)","it":"a pranzo (lo scopo)"}},{"text":"出","reading":"で","meaning":{"en":"go out (first part of the verb)","it":"uscire (prima parte del verbo)"}},{"text":"かけた","meaning":{"en":"(end of the verb, past)","it":"(fine del verbo, passato)"}}]}'::jsonb, '目的を示す「に」', 'Select ランチに. The purpose に can also follow a noun for an activity, such as ランチ ("lunch"), 買い物 ("shopping") or 散歩 ("a walk"): ランチに出かけた = "went out for lunch". The verb after it is still a verb of movement, 出かける ("to go out").', 'Seleziona ランチに. Il に dello scopo può seguire anche un nome di attività, come ランチ («pranzo»), 買い物 («spesa») o 散歩 («passeggiata»): ランチに出かけた = «sono uscito a pranzo». Il verbo dopo resta un verbo di movimento, 出かける («uscire»).'),
  ('9b8f39b8-60f8-573a-9479-86c81dc9e835', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"冷蔵庫に牛乳がある","kana":"れいぞうこにぎゅうにゅうがある"},"answer":"に","distractors":["で","へ"],"gap":{"kanji":"冷蔵庫＿牛乳がある","kana":"れいぞうこ＿ぎゅうにゅうがある"},"prompt":{"en":"\"There''s milk in the fridge.\" Which particle says where the milk is?","it":"«In frigo c''è del latte.» Quale particella dice dove si trova il latte?"},"translation":{"en":"There''s milk in the fridge.","it":"In frigo c''è del latte."}}'::jsonb, '存在の場所を示す「に」', 'ある ("there is", for things) marks the place with に: 冷蔵庫に = "in the fridge". へ only shows a direction you move in, and で is for the place where an action happens; simply being somewhere is not an action.', 'ある («c''è», per le cose) segna il luogo con に: 冷蔵庫に = «in frigo». へ indica solo la direzione in cui ci si muove, e で è per il luogo dove si svolge un''azione; il semplice trovarsi in un posto non è un''azione.'),
  ('29e25e1f-48b4-5049-8249-e44a8f365e5a', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"川に魚がいる","kana":"かわにさかながいる"},"answer":["川に","魚が","いる"],"alsoAccepted":[["魚が","川に","いる"]],"prompt":{"en":"Build: \"There are fish in the river.\"","it":"Componi: «Nel fiume ci sono dei pesci.»"},"translation":{"en":"There are fish in the river.","it":"Nel fiume ci sono dei pesci."},"glosses":[{"text":"川に","reading":"かわに","meaning":{"en":"in the river","it":"nel fiume"}},{"text":"魚が","reading":"さかなが","meaning":{"en":"fish (が: the subject)","it":"i pesci (が: il soggetto)"}},{"text":"いる","meaning":{"en":"there are (for living things)","it":"ci sono (per gli esseri viventi)"}}]}'::jsonb, '存在の場所を示す「に」', 'Fish are living things, so "there is" is いる, not ある. The place where they are takes に: 川に = "in the river". The verb goes last. "魚が川にいる" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'I pesci sono esseri viventi, quindi «c''è» si dice いる, non ある. Il luogo in cui si trovano prende に: 川に = «nel fiume». Il verbo va alla fine. Va bene anche «魚が川にいる»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('3859411c-39f4-5fc4-8d86-d9355a3729f1', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"鍵は机の上にある","kana":"かぎはつくえのうえにある"},"answer":["鍵は","机の上に","ある"],"prompt":{"en":"Build: \"The key is on the desk.\"","it":"Componi: «La chiave è sulla scrivania.»"},"translation":{"en":"The key is on the desk.","it":"La chiave è sulla scrivania."},"glosses":[{"text":"鍵は","reading":"かぎは","meaning":{"en":"the key (は: the topic)","it":"la chiave (は: il tema)"}},{"text":"机の上に","reading":"つくえのうえに","meaning":{"en":"on the desk","it":"sulla scrivania"}},{"text":"ある","meaning":{"en":"is (there)","it":"c''è, si trova"}}]}'::jsonb, '存在の場所を示す「に」', 'When you say where a known thing is, the thing becomes the topic with は (鍵は), and the place takes に: 机の上に = "on (top of) the desk". ある ("to be there", for things) goes last.', 'Quando si dice dove si trova una cosa già nota, la cosa diventa il tema con は (鍵は), e il luogo prende に: 机の上に = «sopra la scrivania». ある («esserci», per le cose) va alla fine.'),
  ('119305dd-19c0-5169-9a94-59d671b1ced8', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"トイレは二階にあります","kana":"トイレはにかいにあります"},"answer":{"start":1,"end":2},"prompt":{"en":"\"The toilet is upstairs.\" Which part is the place where the toilet is?","it":"«Il bagno è al piano di sopra.» Quale parte è il luogo in cui si trova il bagno?"},"translation":{"en":"The toilet is upstairs.","it":"Il bagno è al piano di sopra."},"glosses":[{"text":"トイレは","meaning":{"en":"the toilet (は: the topic)","it":"il bagno (は: il tema)"}},{"text":"二階","reading":"にかい","meaning":{"en":"the second floor (one floor up)","it":"il primo piano (un piano sopra)"}},{"text":"にあります","meaning":{"en":"(に: the place) + is there (polite)","it":"(に: il luogo) + si trova (cortese)"}}]}'::jsonb, '存在の場所を示す「に」', 'Select 二階. Right after it comes に, which marks the place where something is; あります is the polite form of ある ("to be there", for things). In Japan the ground floor counts as the first floor, so 二階 is one floor up.', 'Seleziona 二階. Subito dopo viene に, che indica il luogo in cui si trova qualcosa; あります è la forma cortese di ある («esserci», per le cose). In Giappone il piano terra conta come primo piano, quindi 二階 è un piano sopra.'),
  ('1fea965f-a9e8-5638-ad2d-30790a8463df', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"町が静かになった","kana":"まちがしずかになった"},"answer":"に","distractors":["く","で"],"gap":{"kanji":"町が静か＿なった","kana":"まちがしずか＿なった"},"prompt":{"en":"\"The town has become quiet.\" What goes between 静か (\"quiet\") and なった (\"became\")?","it":"«La città è diventata silenziosa.» Cosa va fra 静か («silenzioso») e なった («è diventata»)?"},"translation":{"en":"The town has become quiet.","it":"La città è diventata silenziosa."}}'::jsonb, '変化の結果を示す「に」', '静か ("quiet") is a な-adjective: a describing word that behaves like a noun (静かな町 = "a quiet town"). Like a noun, it takes に before なる ("to become"): 静かになった. く is only for い-adjectives, the ones that end in い, like 明るい → 明るくなる.', '静か («tranquillo, silenzioso») è un aggettivo in な: una parola che descrive ma si comporta come un nome (静かな町 = «una città tranquilla»). Come un nome, davanti a なる («diventare») prende に: 静かになった. く è solo per gli aggettivi in い, quelli che finiscono in い, come 明るい → 明るくなる.'),
  ('ba67d607-0003-537c-bd60-c15464bf4d10', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"信号が青になった","kana":"しんごうがあおになった"},"answer":["信号が","青に","なった"],"prompt":{"en":"Build: \"The traffic light turned green.\"","it":"Componi: «Il semaforo è diventato verde.»"},"translation":{"en":"The traffic light turned green.","it":"Il semaforo è diventato verde."},"glosses":[{"text":"信号が","reading":"しんごうが","meaning":{"en":"the traffic light (が: the subject)","it":"il semaforo (が: il soggetto)"}},{"text":"青に","reading":"あおに","meaning":{"en":"(to) green","it":"verde"}},{"text":"なった","meaning":{"en":"became","it":"è diventato"}}]}'::jsonb, '変化の結果を示す「に」', 'What something becomes takes に before なる ("to become"): 青になった = "turned green". Here 青 is used as a noun, the colour itself (in Japanese the green of a traffic light is called 青, "blue"). The subject (信号が) comes first and なった goes last. 青に stays right before なった, because it is what the light becomes.', 'Ciò che una cosa diventa prende に davanti a なる («diventare»): 青になった = «è diventato verde». Qui 青 si usa come nome, il colore stesso (in giapponese il verde del semaforo si chiama 青, «blu»). Il soggetto (信号が) va all''inizio e なった alla fine. 青に sta subito prima di なった, perché è ciò che diventa il semaforo.'),
  ('92ff9c27-a072-5101-bd8e-88ada71ea935', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"息子は来月十歳になる","kana":"むすこはらいげつじゅっさいになる"},"answer":["息子は","来月","十歳に","なる"],"alsoAccepted":[["来月","息子は","十歳に","なる"]],"prompt":{"en":"Build: \"My son turns ten next month.\"","it":"Componi: «Mio figlio compie dieci anni il mese prossimo.»"},"translation":{"en":"My son turns ten next month.","it":"Mio figlio compie dieci anni il mese prossimo."},"glosses":[{"text":"息子は","reading":"むすこは","meaning":{"en":"my son (は: the topic)","it":"mio figlio (は: il tema)"}},{"text":"来月","reading":"らいげつ","meaning":{"en":"next month","it":"il mese prossimo"}},{"text":"十歳に","reading":"じゅっさいに","meaning":{"en":"ten years old","it":"dieci anni"}},{"text":"なる","meaning":{"en":"becomes, turns","it":"diventa, compie"}}]}'::jsonb, '変化の結果を示す「に」', 'In Japanese you "become" an age: 十歳になる = "turn ten", with に marking the result, as in every change with なる ("to become"). A time word such as 来月 ("next month") needs no particle. "来月息子は十歳になる" is also correct: a time word can also go before the topic. It cannot go in between, though: 十歳に and なる stay together, because に marks the result that なる leads to.', 'In giapponese un''età si «diventa»: 十歳になる = «compiere dieci anni», con に che segna il risultato, come in ogni cambiamento con なる («diventare»). Una parola di tempo come 来月 («il mese prossimo») non vuole particelle. Va bene anche «来月息子は十歳になる»: una parola di tempo può andare anche prima del tema. In mezzo invece no: 十歳に e なる stanno sempre attaccati, perché に indica il risultato a cui porta なる.'),
  ('e9381013-ea20-559b-b419-80511b3cc7f8', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"そのパンダはもう大人になった","kana":"そのパンダはもうおとなになった"},"answer":{"start":1,"end":2},"prompt":{"en":"\"That panda is already grown up.\" Which part is what the panda became?","it":"«Quel panda ormai è diventato adulto.» Quale parte è ciò che il panda è diventato?"},"translation":{"en":"That panda is already grown up.","it":"Quel panda ormai è diventato adulto."},"glosses":[{"text":"そのパンダはもう","meaning":{"en":"that panda (は: the topic) + already","it":"quel panda (は: il tema) + ormai"}},{"text":"大人","reading":"おとな","meaning":{"en":"adult","it":"adulto"}},{"text":"になった","meaning":{"en":"(に: the result) + became","it":"(に: il risultato) + è diventato"}}]}'::jsonb, '変化の結果を示す「に」', 'Select 大人 ("adult"). It is the result of the change: it comes right before に and なった ("became"). 大人 is a noun, and a noun takes に before なる ("to become").', 'Seleziona 大人 («adulto»). È il risultato del cambiamento: viene subito prima di に e なった («è diventato»). 大人 è un nome, e un nome prende に davanti a なる («diventare»).'),
  ('a3bf594e-e1c4-5725-a543-f7b617f48b65', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"鳥が南へ飛んでいく","kana":"とりがみなみへとんでいく"},"answer":["鳥が","南へ","飛んでいく"],"alsoAccepted":[["南へ","鳥が","飛んでいく"]],"prompt":{"en":"Build: \"The birds are flying off towards the south.\"","it":"Componi: «Gli uccelli volano via verso sud.»"},"translation":{"en":"The birds are flying off towards the south.","it":"Gli uccelli volano via verso sud."},"glosses":[{"text":"鳥が","reading":"とりが","meaning":{"en":"the birds (が: the subject)","it":"gli uccelli (が: il soggetto)"}},{"text":"南へ","reading":"みなみへ","meaning":{"en":"towards the south","it":"verso sud"}},{"text":"飛んでいく","reading":"とんでいく","meaning":{"en":"fly away","it":"volano via"}}]}'::jsonb, '方向を示す「へ」', 'へ (read え) marks the direction of a movement: 南へ = "towards the south". It fits well here because the birds are heading that way, not arriving at a precise place. The verb goes last. "南へ鳥が飛んでいく" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'へ (si legge え) indica la direzione di un movimento: 南へ = «verso sud». Qui è adatta perché gli uccelli vanno in quella direzione, non arrivano in un posto preciso. Il verbo va alla fine. Va bene anche «南へ鳥が飛んでいく»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('728ad2b1-bb67-5905-8bba-a2ac26d2c6f9', '目的地を示す-に', 'assemble', '{"sentence":{"kanji":"次の角を右へ曲がってください","kana":"つぎのかどをみぎへまがってください"},"answer":["次の角を","右へ","曲がってください"],"prompt":{"en":"Build: \"Please turn right at the next corner.\"","it":"Componi: «Al prossimo angolo giri a destra, per favore.»"},"translation":{"en":"Please turn right at the next corner.","it":"Al prossimo angolo giri a destra, per favore."},"glosses":[{"text":"次の角を","reading":"つぎのかどを","meaning":{"en":"at the next corner (を: the point you pass)","it":"al prossimo angolo (を: il punto da cui si passa)"}},{"text":"右へ","reading":"みぎへ","meaning":{"en":"to the right","it":"a destra"}},{"text":"曲がってください","reading":"まがってください","meaning":{"en":"please turn","it":"giri, per favore"}}]}'::jsonb, '方向を示す「へ」', '右へ = "to the right": へ (read え) shows the direction you turn in, so it goes right before the verb. The corner takes を because it is the point you go past, and it comes first: 次の角を → 右へ → 曲がってください. The polite request 曲がってください ("please turn") goes last.', '右へ = «a destra»: へ (si legge え) indica la direzione in cui si gira, e per questo sta subito prima del verbo. L''angolo prende を perché è il punto da cui si passa, e viene prima: 次の角を → 右へ → 曲がってください. La richiesta cortese 曲がってください («giri, per favore») va alla fine.'),
  ('31d75558-3b0c-52e9-a2be-3c02dd807801', '目的地を示す-に', 'single-select', '{"sentence":{"kanji":"これは祖母へのプレゼントです","kana":"これはそぼへのプレゼントです"},"answer":"へ","distractors":["に","を"],"gap":{"kanji":"これは祖母＿のプレゼントです","kana":"これはそぼ＿のプレゼントです"},"prompt":{"en":"\"This is a present for my grandmother.\" Which particle completes 祖母＿の (\"for my grandmother\")?","it":"«Questo è un regalo per mia nonna.» Quale particella completa 祖母＿の («per mia nonna»)?"},"translation":{"en":"This is a present for my grandmother.","it":"Questo è un regalo per mia nonna."}}'::jsonb, '方向を示す「へ」', 'へ (read え) shows where something is heading, so a present going "to" someone can use it. Before の, only へ works: 祖母へのプレゼント = "a present for grandmother". に cannot be followed by の, so 祖母にのプレゼント is wrong.', 'へ (si legge え) indica dove va qualcosa, quindi un regalo diretto «a» qualcuno può usarla. Davanti a の funziona solo へ: 祖母へのプレゼント = «un regalo per la nonna». に non può essere seguita da の, quindi 祖母にのプレゼント è sbagliato.'),
  ('98e295b4-6f99-5d29-ae79-d490c314a761', '目的地を示す-に', 'select-span', '{"sentence":{"kanji":"うしろへ下がってください","kana":"うしろへさがってください"},"answer":{"start":0,"end":1},"prompt":{"en":"\"Please step back.\" Which part says which way to move?","it":"«Si sposti indietro, per favore.» Quale parte dice in che direzione muoversi?"},"translation":{"en":"Please step back.","it":"Si sposti indietro, per favore."},"glosses":[{"text":"うしろへ","meaning":{"en":"towards the back","it":"verso dietro"}},{"text":"下","reading":"さ","meaning":{"en":"move back (first part of the verb)","it":"arretrare (prima parte del verbo)"}},{"text":"がってください","meaning":{"en":"(end of the verb) + please","it":"(fine del verbo) + per favore"}}]}'::jsonb, '方向を示す「へ」', 'Select うしろへ. うしろ means "behind", and へ (read え) turns it into a direction: "towards the back". 下がる ("to move back") is a movement, so it can take へ.', 'Seleziona うしろへ. うしろ significa «dietro», e へ (si legge え) lo trasforma in una direzione: «verso dietro». 下がる («arretrare») è un movimento, quindi può prendere へ.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('d176c834-1d3d-5076-864b-72adb47f4948', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"図書館で勉強する","kana":"としょかんでべんきょうする"},"answer":"で","distractors":["に","を"],"gap":{"kanji":"図書館＿勉強する","kana":"としょかん＿べんきょうする"},"prompt":{"en":"\"I study at the library.\" Which particle says where the action happens?","it":"«Studio in biblioteca.» Quale particella dice dove avviene l''azione?"},"translation":{"en":"I study at the library.","it":"Studio in biblioteca."}}'::jsonb, '動作の場所を示す「で」', 'で is a particle (a small word after a noun that shows its role) that marks where an action happens. Studying is an action, so the library takes で. に would only say where you go or where something is.', 'で è una particella (una piccola parola dopo un nome che ne indica il ruolo) che segna dove avviene un''azione. Studiare è un''azione, quindi la biblioteca prende で. に direbbe solo dove si va o dove si trova qualcosa.'),
  ('e12190eb-47b7-5eab-b513-73b09b4713aa', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"姉は台所にいる","kana":"あねはだいどころにいる"},"answer":"に","distractors":["で","を"],"gap":{"kanji":"姉は台所＿いる","kana":"あねはだいどころ＿いる"},"prompt":{"en":"\"My older sister is in the kitchen.\" Which particle says where she is?","it":"«Mia sorella maggiore è in cucina.» Quale particella dice dove si trova?"},"translation":{"en":"My older sister is in the kitchen.","it":"Mia sorella maggiore è in cucina."}}'::jsonb, '動作の場所を示す「で」', 'いる means "to be (somewhere)": nobody is doing anything, it only says where she is. For the place where someone simply is, Japanese uses に. Compare 台所で料理する, "cooks in the kitchen": that is an action, so で.', 'いる significa «trovarsi»: nessuno sta facendo qualcosa, dice solo dove si trova la sorella. Per il luogo dove qualcuno semplicemente sta, il giapponese usa に. Confronta 台所で料理する, «cucina in cucina»: lì c''è un''azione, quindi で.'),
  ('52e10f75-c252-59df-b6a8-d4362bae79a6', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"ペンで名前を書いた","kana":"ペンでなまえをかいた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says what was used to write?","it":"Quale parte dice con che cosa si è scritto?"},"translation":{"en":"I wrote my name with a pen.","it":"Ho scritto il mio nome con una penna."},"glosses":[{"text":"ペンで","meaning":{"en":"with a pen","it":"con una penna"}},{"text":"名前を書","reading":"なまえをか","meaning":{"en":"name (what is written) + first part of 書く, \"write\"","it":"nome (ciò che si scrive) + inizio di 書く, «scrivere»"}},{"text":"いた","meaning":{"en":"end of 書いた, \"wrote\"","it":"fine di 書いた, «ho scritto»"}}]}'::jsonb, '手段を示す「で」', 'Select ペンで, "with a pen". Besides the place of an action, で also marks the tool you use to do it. The name is what gets written, so it takes を, the particle for the object (the thing the action is done to).', 'Seleziona ペンで, «con una penna». Oltre al luogo di un''azione, で segna anche lo strumento con cui la fai. Il nome è ciò che viene scritto, quindi prende を, la particella dell''oggetto (la cosa su cui cade l''azione).'),
  ('4c9bdd6a-99e8-52b1-9dd1-e1df78cda4d4', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"自転車で学校に通う","kana":"じてんしゃでがっこうにかよう"},"answer":["自転車で","学校に","通う"],"alsoAccepted":[["学校に","自転車で","通う"]],"prompt":{"en":"Build: \"I go to school by bicycle.\"","it":"Componi: «Vado a scuola in bicicletta.»"},"translation":{"en":"I go to school by bicycle.","it":"Vado a scuola in bicicletta."},"glosses":[{"text":"自転車で","reading":"じてんしゃで","meaning":{"en":"by bicycle","it":"in bicicletta"}},{"text":"学校に","reading":"がっこうに","meaning":{"en":"to school","it":"a scuola"}},{"text":"通う","reading":"かよう","meaning":{"en":"go regularly","it":"andare abitualmente"}}]}'::jsonb, '手段を示す「で」', 'A vehicle is a means, just like a pen or a language, so it takes the particle で: 自転車で, "by bicycle". The place you go to takes に: 学校に, "to school". "学校に自転車で通う" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Un veicolo è un mezzo, proprio come una penna o una lingua, quindi prende la particella で: 自転車で, «in bicicletta». Il luogo dove vai prende に: 学校に, «a scuola». Va bene anche «学校に自転車で通う»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('0bfa5305-e678-52b2-be6c-c6a0e5b761d8', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"英語で手紙を書いた","kana":"えいごでてがみをかいた"},"answer":"で","distractors":["を","が"],"gap":{"kanji":"英語＿手紙を書いた","kana":"えいご＿てがみをかいた"},"prompt":{"en":"\"I wrote a letter in English.\" Which particle goes after the language used?","it":"«Ho scritto una lettera in inglese.» Quale particella va dopo la lingua usata?"},"translation":{"en":"I wrote a letter in English.","it":"Ho scritto una lettera in inglese."}}'::jsonb, '手段を示す「で」', 'The language you speak or write in is a means too, so it takes で: 英語で, "in English". を is already used for the letter, the thing that gets written.', 'Anche la lingua in cui parli o scrivi è un mezzo, quindi prende で: 英語で, «in inglese». を è già usato per la lettera, la cosa che viene scritta.'),
  ('8369e4be-0eaf-5345-8615-b6b8d8a98d93', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"パンと牛乳を買った","kana":"パンとぎゅうにゅうをかった"},"answer":"と","distractors":["を","へ"],"gap":{"kanji":"パン＿牛乳を買った","kana":"パン＿ぎゅうにゅうをかった"},"prompt":{"en":"\"I bought bread and milk.\" Which particle joins the two nouns?","it":"«Ho comprato pane e latte.» Quale particella unisce i due nomi?"},"translation":{"en":"I bought bread and milk.","it":"Ho comprato pane e latte."}}'::jsonb, '名詞をつなぐ「と」', 'と between two nouns means "and": パンと牛乳, "bread and milk". It only makes a list. The を after the last noun makes the whole list the object of 買った (the things bought).', 'と fra due nomi significa «e»: パンと牛乳, «pane e latte». Serve solo a fare un elenco. Il を dopo l''ultimo nome rende tutto l''elenco l''oggetto di 買った (le cose comprate).'),
  ('dd3ffd65-32ba-5b83-b664-6ed29a402cdb', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"兄と弟が川で泳いでいる","kana":"あにとおとうとがかわでおよいでいる"},"answer":["兄と","弟が","川で","泳いでいる"],"alsoAccepted":[["川で","兄と","弟が","泳いでいる"]],"prompt":{"en":"Build: \"My older and younger brothers are swimming in the river.\"","it":"Componi: «Il fratello maggiore e il minore stanno nuotando nel fiume.»"},"translation":{"en":"My older and younger brothers are swimming in the river.","it":"Il fratello maggiore e il minore stanno nuotando nel fiume."},"glosses":[{"text":"兄と","reading":"あにと","meaning":{"en":"older brother and","it":"fratello maggiore e"}},{"text":"弟が","reading":"おとうとが","meaning":{"en":"younger brother + が (who does it)","it":"fratello minore + が (chi lo fa)"}},{"text":"川で","reading":"かわで","meaning":{"en":"in the river","it":"nel fiume"}},{"text":"泳いでいる","reading":"およいでいる","meaning":{"en":"are swimming","it":"stanno nuotando"}}]}'::jsonb, '名詞をつなぐ「と」', '兄と弟 means "older brother and younger brother": と joins them into one group. が after the group marks both as the subject (who does the action). 川で says where they swim: it is an action, so で. "川で兄と弟が泳いでいる" is also correct: the verb stays at the end, and 川で can come first. 兄と, though, stays right before 弟が: if you split them, と would mean "with" instead of "and".', '兄と弟 significa «fratello maggiore e fratello minore»: と li unisce in un solo gruppo. が dopo il gruppo li segna entrambi come soggetto (chi fa l''azione). 川で dice dove nuotano: è un''azione, quindi で. Va bene anche «川で兄と弟が泳いでいる»: il verbo resta in fondo, e 川で può andare all''inizio. 兄と invece resta subito prima di 弟が: se li separi, と vuol dire «con» invece di «e».'),
  ('645e1b4a-08c3-5488-9072-ca1e40bda4aa', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"レストランで晩ご飯を食べた","kana":"レストランでばんごはんをたべた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says where the action happened?","it":"Quale parte dice dove è avvenuta l''azione?"},"translation":{"en":"I ate dinner at a restaurant.","it":"Ho cenato al ristorante."},"glosses":[{"text":"レストランで","meaning":{"en":"at a restaurant","it":"al ristorante"}},{"text":"晩ご飯を食","reading":"ばんごはんをた","meaning":{"en":"dinner (what is eaten) + first part of 食べる, \"eat\"","it":"cena (ciò che si mangia) + inizio di 食べる, «mangiare»"}},{"text":"べた","meaning":{"en":"end of 食べた, \"ate\"","it":"fine di 食べた, «ho mangiato»"}}]}'::jsonb, '動作の場所を示す「で」', 'Select レストランで, "at a restaurant". Eating is an action, and the place where an action happens takes the particle で (a small word that marks where it happens). Without an action, for example with いる, "to be there", the place would take に.', 'Seleziona レストランで, «al ristorante». Mangiare è un''azione, e il luogo dove avviene un''azione prende la particella で (una piccola parola che segna dove avviene). Senza un''azione, per esempio con いる, «trovarsi», il luogo prenderebbe に.'),
  ('cae1f7df-e77a-5547-ab1f-82628cce9bba', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"バスで学校に行く","kana":"バスでがっこうにいく"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part says how I get there?","it":"Quale parte dice con che mezzo ci vado?"},"translation":{"en":"I go to school by bus.","it":"Vado a scuola in autobus."},"glosses":[{"text":"バスで","meaning":{"en":"by bus","it":"in autobus"}},{"text":"学校に行","reading":"がっこうにい","meaning":{"en":"to school + first part of 行く, \"go\"","it":"a scuola + inizio di 行く, «andare»"}},{"text":"く","meaning":{"en":"end of 行く","it":"fine di 行く"}}]}'::jsonb, '手段を示す「で」', 'Select バスで, "by bus". The particle で also marks the means you use: a tool, a language or, as here, a vehicle. The place you go to takes に: 学校に.', 'Seleziona バスで, «in autobus». La particella で segna anche il mezzo che usi: uno strumento, una lingua o, come qui, un veicolo. Il luogo dove vai prende に: 学校に.'),
  ('55f9a8e1-380e-5eb0-9665-a1d228d2631a', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"机の上に本とノートがある","kana":"つくえのうえにほんとノートがある"},"answer":["机の上に","本と","ノートが","ある"],"alsoAccepted":[["本と","ノートが","机の上に","ある"]],"prompt":{"en":"Build: \"There are a book and a notebook on the desk.\"","it":"Componi: «Sulla scrivania ci sono un libro e un quaderno.»"},"translation":{"en":"There are a book and a notebook on the desk.","it":"Sulla scrivania ci sono un libro e un quaderno."},"glosses":[{"text":"机の上に","reading":"つくえのうえに","meaning":{"en":"on the desk","it":"sulla scrivania"}},{"text":"本と","reading":"ほんと","meaning":{"en":"a book and","it":"un libro e"}},{"text":"ノートが","meaning":{"en":"notebook + が (what is there)","it":"quaderno + が (ciò che c''è)"}},{"text":"ある","meaning":{"en":"there is, there are (for things)","it":"c''è, ci sono (per le cose)"}}]}'::jsonb, '名詞をつなぐ「と」', '本とノート means "a book and a notebook": と joins two nouns into a list. が after the list marks what is there, and ある says that things are in a place. The place takes に, because ある is not an action. "本とノートが机の上にある" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places. Only 本と stays right before ノートが, because と joins the two nouns into one list.', '本とノート significa «un libro e un quaderno»: と unisce due nomi in un elenco. が dopo l''elenco segna ciò che c''è, e ある dice che delle cose si trovano in un luogo. Il luogo prende に, perché ある non è un''azione. Va bene anche «本とノートが机の上にある»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto. Solo 本と resta subito prima di ノートが, perché と unisce i due nomi in un elenco.'),
  ('ca8d8c70-be18-5918-84bd-2a70a521d968', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"コンビニで働いている","kana":"コンビニではたらいている"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I work at a convenience store.\" Which part says where the work happens?","it":"«Lavoro in un minimarket.» Quale parte dice dove si svolge il lavoro?"},"translation":{"en":"I work at a convenience store.","it":"Lavoro in un minimarket."},"glosses":[{"text":"コンビニで","meaning":{"en":"at a convenience store","it":"in un minimarket"}},{"text":"働","reading":"はたら","meaning":{"en":"work (kanji of 働く)","it":"lavorare (kanji di 働く)"}},{"text":"いている","meaning":{"en":"end of 働いている, \"work (as a job)\"","it":"fine di 働いている, «lavoro (come impiego)»"}}]}'::jsonb, '動作の場所を示す「で」', 'Select コンビニで, "at a convenience store". Working is an action, so the place where it happens takes で. 働いている is in the ている form (the form for what is going on), and here it means a job you have now.', 'Seleziona コンビニで, «in un minimarket». Lavorare è un''azione, quindi il luogo dove si svolge prende で. 働いている è nella forma in ている (quella per ciò che è in corso), e qui indica un lavoro che hai adesso.'),
  ('84dcb76a-24a7-515f-a300-da03415129dc', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"駅の前で写真を撮った","kana":"えきのまえでしゃしんをとった"},"answer":["駅の前で","写真を","撮った"],"alsoAccepted":[["写真を","駅の前で","撮った"]],"prompt":{"en":"Build: \"I took a photo in front of the station.\"","it":"Componi: «Ho fatto una foto davanti alla stazione.»"},"translation":{"en":"I took a photo in front of the station.","it":"Ho fatto una foto davanti alla stazione."},"glosses":[{"text":"駅の前で","reading":"えきのまえで","meaning":{"en":"in front of the station","it":"davanti alla stazione"}},{"text":"写真を","reading":"しゃしんを","meaning":{"en":"photo + を (what is taken)","it":"foto + を (ciò che si scatta)"}},{"text":"撮った","reading":"とった","meaning":{"en":"took (a photo)","it":"ho scattato"}}]}'::jsonb, '動作の場所を示す「で」', 'Taking a photo is an action, so the place where you do it takes で: 駅の前で, "in front of the station". The photo is the object (the thing the action is done to), so it takes を. "写真を駅の前で撮った" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Fare una foto è un''azione, quindi il luogo dove la fai prende で: 駅の前で, «davanti alla stazione». La foto è l''oggetto (la cosa su cui cade l''azione), quindi prende を. Va bene anche «写真を駅の前で撮った»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('b6e13d6c-03b2-5039-8b06-7b0fce2a7415', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"父は庭で野菜を育てている","kana":"ちちはにわでやさいをそだてている"},"answer":["父は","庭で","野菜を","育てている"],"alsoAccepted":[["父は","野菜を","庭で","育てている"],["庭で","父は","野菜を","育てている"]],"prompt":{"en":"Build: \"My father grows vegetables in the garden.\"","it":"Componi: «Mio padre coltiva verdure in giardino.»"},"translation":{"en":"My father grows vegetables in the garden.","it":"Mio padre coltiva verdure in giardino."},"glosses":[{"text":"父は","reading":"ちちは","meaning":{"en":"my father (topic)","it":"mio padre (tema)"}},{"text":"庭で","reading":"にわで","meaning":{"en":"in the garden","it":"in giardino"}},{"text":"野菜を","reading":"やさいを","meaning":{"en":"vegetables + を (what is grown)","it":"verdure + を (ciò che si coltiva)"}},{"text":"育てている","reading":"そだてている","meaning":{"en":"grows, is growing","it":"coltiva"}}]}'::jsonb, '動作の場所を示す「で」', 'Growing vegetables is an action that happens in the garden, so the garden takes で: 庭で. 父は is the topic, the person the sentence is about, and it usually comes first. If the sentence only said where the vegetables are, with ある, the garden would take に. "父は野菜を庭で育てている" and "庭で父は野菜を育てている" are also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Coltivare verdure è un''azione che avviene in giardino, quindi il giardino prende で: 庭で. 父は è il tema, la persona di cui parla la frase, e di solito sta all''inizio. Se la frase dicesse solo dove si trovano le verdure, con ある, il giardino prenderebbe に. Vanno bene anche «父は野菜を庭で育てている» e «庭で父は野菜を育てている»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('8252c255-d96b-5699-8e6b-13354500631e', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"電子レンジでご飯を温めた","kana":"でんしレンジでごはんをあたためた"},"answer":"で","distractors":["に","を"],"gap":{"kanji":"電子レンジ＿ご飯を温めた","kana":"でんしレンジ＿ごはんをあたためた"},"prompt":{"en":"\"I heated the rice in the microwave.\" Which particle goes after the tool used?","it":"«Ho scaldato il riso nel microonde.» Quale particella va dopo lo strumento usato?"},"translation":{"en":"I heated the rice in the microwave.","it":"Ho scaldato il riso nel microonde."}}'::jsonb, '手段を示す「で」', 'The microwave is the tool you use to heat the rice, and a tool takes で: 電子レンジで. を is already taken by ご飯, the thing that gets heated. 電子レンジに would fit with 入れる, "put into", not with 温める, "heat".', 'Il microonde è lo strumento con cui scaldi il riso, e uno strumento prende で: 電子レンジで. を è già preso da ご飯, la cosa che viene scaldata. 電子レンジに andrebbe con 入れる, «mettere dentro», non con 温める, «scaldare».'),
  ('0bb8f87b-f52b-5b2e-aefd-258825d52ff3', '動作の場所を示す-で', 'assemble', '{"sentence":{"kanji":"スマホで天気を調べた","kana":"スマホでてんきをしらべた"},"answer":["スマホで","天気を","調べた"],"alsoAccepted":[["天気を","スマホで","調べた"]],"prompt":{"en":"Build: \"I checked the weather on my phone.\"","it":"Componi: «Ho controllato il meteo con il telefono.»"},"translation":{"en":"I checked the weather on my phone.","it":"Ho controllato il meteo con il telefono."},"glosses":[{"text":"スマホで","meaning":{"en":"with my smartphone","it":"con lo smartphone"}},{"text":"天気を","reading":"てんきを","meaning":{"en":"weather + を (what is checked)","it":"meteo + を (ciò che si controlla)"}},{"text":"調べた","reading":"しらべた","meaning":{"en":"checked, looked up","it":"ho controllato"}}]}'::jsonb, '手段を示す「で」', 'スマホ, "smartphone", is the tool you use to look things up, so it takes で: スマホで, "with my phone". The weather is the thing checked, so it takes を. "天気をスマホで調べた" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'スマホ, «smartphone», è lo strumento con cui cerchi le informazioni, quindi prende で: スマホで, «con il telefono». Il meteo è la cosa controllata, quindi prende を. Va bene anche «天気をスマホで調べた»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('b11a4a73-7882-57f5-ba38-150bc1b00e8b', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"コーヒーとケーキを注文した","kana":"コーヒーとケーキをちゅうもんした"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I ordered coffee and cake.\" Which part lists what was ordered?","it":"«Ho ordinato caffè e torta.» Quale parte elenca ciò che è stato ordinato?"},"translation":{"en":"I ordered coffee and cake.","it":"Ho ordinato caffè e torta."},"glosses":[{"text":"コーヒーとケーキを","meaning":{"en":"coffee and cake + を (what is ordered)","it":"caffè e torta + を (ciò che si ordina)"}},{"text":"注文","reading":"ちゅうもん","meaning":{"en":"order (the kanji of 注文する)","it":"ordinazione (i kanji di 注文する)"}},{"text":"した","meaning":{"en":"did: 注文した, \"ordered\"","it":"ha fatto: 注文した, «ho ordinato»"}}]}'::jsonb, '名詞をつなぐ「と」', 'Select コーヒーとケーキを. と between two nouns means "and" and joins them into one list: コーヒーとケーキ, "coffee and cake". The を after the list makes both things the object of 注文した, "ordered".', 'Seleziona コーヒーとケーキを. と fra due nomi significa «e» e li unisce in un solo elenco: コーヒーとケーキ, «caffè e torta». Il を dopo l''elenco rende entrambe le cose l''oggetto di 注文した, «ho ordinato».'),
  ('f002bf8e-20ac-5521-8b38-169b3e6a6659', '動作の場所を示す-で', 'select-span', '{"sentence":{"kanji":"ねこといぬが庭で遊んでいる","kana":"ねこといぬがにわであそんでいる"},"answer":{"start":0,"end":1},"prompt":{"en":"\"The cat and the dog are playing in the garden.\" Which part says who is playing?","it":"«Il gatto e il cane giocano in giardino.» Quale parte dice chi sta giocando?"},"translation":{"en":"The cat and the dog are playing in the garden.","it":"Il gatto e il cane giocano in giardino."},"glosses":[{"text":"ねこといぬが","meaning":{"en":"the cat and the dog + が (who does it)","it":"il gatto e il cane + が (chi lo fa)"}},{"text":"庭で遊","reading":"にわであそ","meaning":{"en":"in the garden + first part of 遊ぶ, \"play\"","it":"in giardino + inizio di 遊ぶ, «giocare»"}},{"text":"んでいる","meaning":{"en":"end of 遊んでいる, \"are playing\"","it":"fine di 遊んでいる, «stanno giocando»"}}]}'::jsonb, '名詞をつなぐ「と」', 'Select ねこといぬが. と joins ねこ, "cat", and いぬ, "dog", into one group, and が after the group marks both as the subject (who does the action). 庭で says where they play: playing is an action, so で.', 'Seleziona ねこといぬが. と unisce ねこ, «gatto», e いぬ, «cane», in un solo gruppo, e が dopo il gruppo li segna entrambi come soggetto (chi fa l''azione). 庭で dice dove giocano: giocare è un''azione, quindi で.'),
  ('bf11ea4e-33e0-5ca7-8364-d38bde9496e4', '動作の場所を示す-で', 'single-select', '{"sentence":{"kanji":"北海道と沖縄を旅行した","kana":"ほっかいどうとおきなわをりょこうした"},"answer":"と","distractors":["で","を"],"gap":{"kanji":"北海道＿沖縄を旅行した","kana":"ほっかいどう＿おきなわをりょこうした"},"prompt":{"en":"\"I travelled around Hokkaido and Okinawa.\" Which particle joins the two places?","it":"«Ho viaggiato in Hokkaido e a Okinawa.» Quale particella unisce i due luoghi?"},"translation":{"en":"I travelled around Hokkaido and Okinawa.","it":"Ho viaggiato in Hokkaido e a Okinawa."}}'::jsonb, '名詞をつなぐ「と」', 'Hokkaido and Okinawa are both places you travelled around, so と joins them into one list: 北海道と沖縄, "Hokkaido and Okinawa". The を after the list marks both as the places travelled. を after 北海道 would not join the two nouns, and で would say that the trip to Okinawa happened in Hokkaido, which makes no sense.', 'Hokkaido e Okinawa sono entrambi luoghi che hai girato, quindi と li unisce in un solo elenco: 北海道と沖縄, «Hokkaido e Okinawa». Il を dopo l''elenco li segna entrambi come luoghi del viaggio. を dopo 北海道 non unirebbe i due nomi, e で direbbe che il viaggio a Okinawa si è svolto in Hokkaido, che non ha senso.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('53fc7beb-c295-5291-89ec-7310f54c0e85', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"私は犬が好きだ","kana":"わたしはいぬがすきだ"},"answer":"が","distractors":["を","で"],"gap":{"kanji":"私は犬＿好きだ","kana":"わたしはいぬ＿すきだ"},"prompt":{"en":"\"I like dogs.\" Which particle goes after what is liked?","it":"«Mi piacciono i cani.» Quale particella va dopo ciò che piace?"},"translation":{"en":"I like dogs.","it":"Mi piacciono i cani."}}'::jsonb, '感情・理解の述語と「が」', '好き ("liked") is not a verb but a な-adjective: a describing word that ends the sentence with だ, "is". を is only for the object of a verb (the thing an action is done to), so what is liked takes が: 犬が好きだ. 私は is the topic: who the sentence is about.', '好き («che piace») non è un verbo ma un aggettivo in な: una parola che descrive e chiude la frase con だ, cioè «è». を serve solo per l''oggetto di un verbo (la cosa su cui cade l''azione), quindi ciò che piace prende が: 犬が好きだ. 私は è il tema: la persona di cui parla la frase.'),
  ('e3af00c5-e946-563c-bbf1-d525bb7067c2', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"弟は漢字が分かる","kana":"おとうとはかんじがわかる"},"answer":"が","distractors":["を","で"],"gap":{"kanji":"弟は漢字＿分かる","kana":"おとうとはかんじ＿わかる"},"prompt":{"en":"\"My younger brother understands kanji.\" Which particle goes after what is understood?","it":"«Mio fratello minore capisce i kanji.» Quale particella va dopo ciò che si capisce?"},"translation":{"en":"My younger brother understands kanji.","it":"Mio fratello minore capisce i kanji."}}'::jsonb, '感情・理解の述語と「が」', '分かる means "to be clear, understandable": it describes a state, not an action done to something. So what is understood takes が, never を: 漢字が分かる. 弟は is the topic: who the sentence is about.', '分かる significa «essere chiaro, comprensibile»: descrive uno stato, non un''azione fatta su qualcosa. Per questo ciò che si capisce prende が, mai を: 漢字が分かる. 弟は è il tema: la persona di cui parla la frase.'),
  ('f8a17f20-6a3c-5b1f-abde-422365eb833a', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"新しい自転車がほしい","kana":"あたらしいじてんしゃがほしい"},"answer":["新しい","自転車が","ほしい"],"prompt":{"en":"Build: \"I want a new bicycle.\"","it":"Componi: «Voglio una bicicletta nuova.»"},"translation":{"en":"I want a new bicycle.","it":"Voglio una bicicletta nuova."},"glosses":[{"text":"新しい","reading":"あたらしい","meaning":{"en":"new","it":"nuova"}},{"text":"自転車が","reading":"じてんしゃが","meaning":{"en":"bicycle + が (what is wanted)","it":"bicicletta + が (ciò che si vuole)"}},{"text":"ほしい","meaning":{"en":"wanted (I want)","it":"desiderato (voglio)"}}]}'::jsonb, '欲求の「ほしい」と「たい」', 'ほしい ("wanted") ends in い: it is an い-adjective (a describing word ending in い), not a verb. So the thing you want takes が: 自転車がほしい. If no one else is named, the wish is the speaker''s: "I want". 新しい, "new", goes right before the noun it describes: 新しい自転車.', 'ほしい («desiderato») finisce in い: è un aggettivo in い (una parola che descrive e finisce in い), non un verbo. Per questo la cosa che vuoi prende が: 自転車がほしい. Se non si nomina nessun altro, il desiderio è di chi parla: «voglio». 新しい, «nuova», va subito prima del nome che descrive: 新しい自転車.'),
  ('cfc027a4-598d-522e-aeff-53f35b8f2e4f', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"ラーメンが食べたい","kana":"ラーメンがたべたい"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the thing that is wanted?","it":"Quale parte è la cosa desiderata?"},"translation":{"en":"I want to eat ramen.","it":"Voglio mangiare il ramen."},"glosses":[{"text":"ラーメンが","meaning":{"en":"ramen + が (what is wanted)","it":"ramen + が (ciò che si vuole)"}},{"text":"食","reading":"た","meaning":{"en":"eat (kanji of 食べる)","it":"mangiare (kanji di 食べる)"}},{"text":"べたい","meaning":{"en":"rest of 食べ + たい, \"want to\"","it":"resto di 食べ + たい, «voler fare»"}}]}'::jsonb, '欲求の「ほしい」と「たい」', 'Select ラーメンが, the thing you want. 食べたい is 食べ (from 食べる, "eat") + たい, "want to"; たい ends in い and works like an adjective, so what you want can take が. ラーメンを食べたい is also correct; が is the more traditional choice.', 'Seleziona ラーメンが, ciò che si vuole. 食べたい è 食べ (da 食べる, «mangiare») + たい, «voler fare»; たい finisce in い e funziona come un aggettivo, quindi ciò che vuoi può prendere が. Anche ラーメンを食べたい è corretto; が è la scelta più tradizionale.'),
  ('9c045dfa-041f-5013-ac0a-02f0d02c79ed', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"妹が新しいゲームをほしがっている","kana":"いもうとがあたらしいゲームをほしがっている"},"answer":"ほしがっている","distractors":["ほしい","ほしいだ","ほしくている"],"gap":{"kanji":"妹が新しいゲームを＿","kana":"いもうとがあたらしいゲームを＿"},"prompt":{"en":"\"My younger sister wants a new game.\" How do you say that someone else wants something?","it":"«Mia sorella minore vuole un gioco nuovo.» Come si dice che un''altra persona vuole qualcosa?"},"translation":{"en":"My younger sister wants a new game.","it":"Mia sorella minore vuole un gioco nuovo."}}'::jsonb, '他人の感情を示す「がる」', 'ほしい and たい express only the speaker''s own feelings: you can''t know from the inside what another person feels. For someone else, drop the final い and add がる, "to show signs of": ほしい → ほしがる, here as ほしがっている, "is wanting". ほしがる is a verb, so the thing wanted takes を.', 'ほしい e たい esprimono solo i sentimenti di chi parla: quello che prova un altro non lo puoi sapere da dentro. Per un''altra persona si toglie la い finale e si aggiunge がる, «mostrare segni di»: ほしい → ほしがる, qui ほしがっている, «sta desiderando». ほしがる è un verbo, quindi la cosa voluta prende を.'),
  ('433e230a-0f7d-5b8b-9da7-1f844e6d758c', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"子供が外で遊びたがっている","kana":"こどもがそとであそびたがっている"},"answer":"遊びたがっている","distractors":["遊びたい","遊びたいだ","遊ぶたがっている"],"gap":{"kanji":"子供が外で＿","kana":"こどもがそとで＿"},"prompt":{"en":"\"The child wants to play outside.\" How do you describe the child''s wish?","it":"«Il bambino vuole giocare fuori.» Come si descrive il desiderio del bambino?"},"translation":{"en":"The child wants to play outside.","it":"Il bambino vuole giocare fuori."},"glosses":[{"text":"遊びたがっている","reading":"あそびたがっている"},{"text":"遊びたい","reading":"あそびたい"},{"text":"遊びたいだ","reading":"あそびたいだ"},{"text":"遊ぶたがっている","reading":"あそぶたがっている"}]}'::jsonb, '他人の感情を示す「がる」', '遊びたい ("I want to play") can only describe the speaker''s wish. For the child, たい drops its い and takes がる: 遊びたがる, "shows that they want to play". Here it is in the ている form, which describes what is going on now: 遊びたがっている.', '遊びたい («voglio giocare») descrive solo il desiderio di chi parla. Per il bambino, たい perde la い e prende がる: 遊びたがる, «mostra di voler giocare». Qui è nella forma in ている, che descrive ciò che succede adesso: 遊びたがっている.'),
  ('9d13b41f-8fa9-52c8-af21-43348680ed89', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"スポーツが好きです","kana":"スポーツがすきです"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the thing that is liked?","it":"Quale parte è ciò che piace?"},"translation":{"en":"I like sports.","it":"Mi piace lo sport."},"glosses":[{"text":"スポーツが","meaning":{"en":"sports + が (what is liked)","it":"sport + が (ciò che piace)"}},{"text":"好","reading":"す","meaning":{"en":"liked (kanji of 好き)","it":"che piace (kanji di 好き)"}},{"text":"きです","meaning":{"en":"end of 好き + です, polite \"is\"","it":"fine di 好き + です, «è» cortese"}}]}'::jsonb, '感情・理解の述語と「が」', 'Select スポーツが. 好き ("liked") is a な-adjective, a describing word, not a verb, so it has no object with を. What is liked takes が: スポーツが好きです, where です is a polite "is".', 'Seleziona スポーツが. 好き («che piace») è un aggettivo in な, una parola che descrive, non un verbo, quindi non ha un oggetto con を. Ciò che piace prende が: スポーツが好きです, dove です è «è» in forma cortese.'),
  ('49892eb0-946c-5fb5-8514-e3459fc00663', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"ねこが外に出たがっている","kana":"ねこがそとにでたがっている"},"answer":{"start":2,"end":3},"prompt":{"en":"Which part shows that the wish belongs to someone else, not the speaker?","it":"Quale parte mostra che il desiderio è di qualcun altro, non di chi parla?"},"translation":{"en":"The cat wants to go outside.","it":"Il gatto vuole uscire."},"glosses":[{"text":"ねこが","meaning":{"en":"cat + が (who wants it)","it":"gatto + が (chi lo vuole)"}},{"text":"外に出","reading":"そとにで","meaning":{"en":"outside + first part of 出る, \"go out\"","it":"fuori + inizio di 出る, «uscire»"}},{"text":"たがっている","meaning":{"en":"wants to (as seen from outside)","it":"vuole (visto da fuori)"}}]}'::jsonb, '他人の感情を示す「がる」', 'Select たがっている. 出たい would mean "I want to go out", the speaker''s own wish. For anyone else, even a cat, たい becomes たがる, "shows that it wants to", here as たがっている, "is showing it now".', 'Seleziona たがっている. 出たい significherebbe «voglio uscire», il desiderio di chi parla. Per chiunque altro, anche un gatto, たい diventa たがる, «mostra di voler fare», qui たがっている, «lo sta mostrando adesso».'),
  ('839acd0d-8db3-5e15-8a53-1ad6ed96d9ef', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"私は日本語が少し分かる","kana":"わたしはにほんごがすこしわかる"},"answer":["私は","日本語が","少し","分かる"],"alsoAccepted":[["私は","少し","日本語が","分かる"]],"prompt":{"en":"Build: \"I understand a little Japanese.\"","it":"Componi: «Capisco un po'' di giapponese.»"},"translation":{"en":"I understand a little Japanese.","it":"Capisco un po'' di giapponese."},"glosses":[{"text":"私は","reading":"わたしは","meaning":{"en":"I (topic)","it":"io (tema)"}},{"text":"日本語が","reading":"にほんごが","meaning":{"en":"Japanese + が (what is understood)","it":"giapponese + が (ciò che si capisce)"}},{"text":"少し","reading":"すこし","meaning":{"en":"a little","it":"un po''"}},{"text":"分かる","reading":"わかる","meaning":{"en":"understand","it":"capire"}}]}'::jsonb, '感情・理解の述語と「が」', '分かる ("understand") describes a state, so what is understood takes が, not を: 日本語が分かる. 私は is the topic, the person the sentence is about. 少し, "a little", says how much you understand: it can go right before 分かる or before 日本語が. "私は少し日本語が分かる" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '分かる («capire») descrive uno stato, quindi ciò che si capisce prende が, non を: 日本語が分かる. 私は è il tema, la persona di cui parla la frase. 少し, «un po''», dice quanto capisci: può andare subito prima di 分かる oppure prima di 日本語が. Va bene anche «私は少し日本語が分かる»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('54bbee0f-608f-5d7b-b294-0fe2522f7c29', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"夏休みに日本へ行きたい","kana":"なつやすみににほんへいきたい"},"answer":["夏休みに","日本へ","行きたい"],"alsoAccepted":[["日本へ","夏休みに","行きたい"]],"prompt":{"en":"Build: \"I want to go to Japan in the summer holidays.\"","it":"Componi: «Nelle vacanze estive voglio andare in Giappone.»"},"translation":{"en":"I want to go to Japan in the summer holidays.","it":"Nelle vacanze estive voglio andare in Giappone."},"glosses":[{"text":"夏休みに","reading":"なつやすみに","meaning":{"en":"in the summer holidays","it":"nelle vacanze estive"}},{"text":"日本へ","reading":"にほんへ","meaning":{"en":"to Japan","it":"in Giappone"}},{"text":"行きたい","reading":"いきたい","meaning":{"en":"want to go","it":"voler andare"}}]}'::jsonb, '欲求の「ほしい」と「たい」', 'To say "want to do", take the verb''s i-stem (the part before ます: 行きます → 行き) and add たい: 行きたい, "want to go". In a statement, たい is always the speaker''s own wish. The place you head to takes へ, "towards". "日本へ夏休みに行きたい" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'Per dire «voglio fare», si prende il radicale in i del verbo (la parte davanti a ます: 行きます → 行き) e si aggiunge たい: 行きたい, «voglio andare». In un''affermazione, たい è sempre il desiderio di chi parla. Il luogo verso cui vai prende へ, «verso». Va bene anche «日本へ夏休みに行きたい»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('2c5cfacf-adb4-5612-bcfb-c077ef8c9d6b', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"トマトが嫌いだ","kana":"トマトがきらいだ"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I don''t like tomatoes.\" Which part is the thing that is disliked?","it":"«Non mi piacciono i pomodori.» Quale parte è ciò che non piace?"},"translation":{"en":"I don''t like tomatoes.","it":"Non mi piacciono i pomodori."},"glosses":[{"text":"トマトが","meaning":{"en":"tomatoes + が (what is disliked)","it":"pomodori + が (ciò che non piace)"}},{"text":"嫌","reading":"きら","meaning":{"en":"disliked (kanji of 嫌い)","it":"sgradito (kanji di 嫌い)"}},{"text":"いだ","meaning":{"en":"end of 嫌い + だ, \"is\"","it":"fine di 嫌い + だ, «è»"}}]}'::jsonb, '感情・理解の述語と「が」', 'Select トマトが. 嫌い ("disliked") ends in い but is a な-adjective: a describing word that ends the sentence with だ, "is". Like 好き, it is not a verb, so what you dislike takes が, not を.', 'Seleziona トマトが. 嫌い («sgradito») finisce in い ma è un aggettivo in な: una parola che descrive e chiude la frase con だ, «è». Come 好き, non è un verbo, quindi ciò che non ti piace prende が, non を.'),
  ('ec472e2c-35ee-5677-8642-78d1b1f033e4', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"田中さんは辛い料理が好きだ","kana":"たなかさんはからいりょうりがすきだ"},"answer":["田中さんは","辛い","料理が","好きだ"],"prompt":{"en":"Build: \"Tanaka likes spicy food.\"","it":"Componi: «A Tanaka piace il cibo piccante.»"},"translation":{"en":"Tanaka likes spicy food.","it":"A Tanaka piace il cibo piccante."},"glosses":[{"text":"田中さんは","reading":"たなかさんは","meaning":{"en":"Tanaka (topic)","it":"Tanaka (tema)"}},{"text":"辛い","reading":"からい","meaning":{"en":"spicy","it":"piccante"}},{"text":"料理が","reading":"りょうりが","meaning":{"en":"food, dishes + が (what is liked)","it":"piatti + が (ciò che piace)"}},{"text":"好きだ","reading":"すきだ","meaning":{"en":"is liked (likes)","it":"piace"}}]}'::jsonb, '感情・理解の述語と「が」', '好き ("liked") is a な-adjective, not a verb, so what is liked takes が: 料理が好きだ. 田中さんは is the topic, the person the sentence is about. 辛い, "spicy", goes right before the noun it describes: 辛い料理, "spicy food".', '好き («che piace») è un aggettivo in な, non un verbo, quindi ciò che piace prende が: 料理が好きだ. 田中さんは è il tema, la persona di cui parla la frase. 辛い, «piccante», va subito prima del nome che descrive: 辛い料理, «cibo piccante».'),
  ('0ec2bd7e-deaf-53d6-80de-98691d09f2e2', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"冷たい水がほしい","kana":"つめたいみずがほしい"},"answer":"ほしい","distractors":["ほしがる","ほしいだ"],"gap":{"kanji":"冷たい水が＿","kana":"つめたいみずが＿"},"prompt":{"en":"\"I want some cold water.\" Which word says that the speaker wants it?","it":"«Voglio dell''acqua fredda.» Quale parola dice che chi parla la vuole?"},"translation":{"en":"I want some cold water.","it":"Voglio dell''acqua fredda."}}'::jsonb, '欲求の「ほしい」と「たい」', 'ほしい ("wanted") is an い-adjective (a describing word ending in い) and says what the speaker wants: 水がほしい. It ends the sentence on its own: in plain speech an い-adjective does not take だ, so ほしいだ is wrong. ほしがる is for other people''s wishes, seen from outside, and it takes を, not が.', 'ほしい («desiderato») è un aggettivo in い (una parola che descrive e finisce in い) e dice ciò che vuole chi parla: 水がほしい. Chiude la frase da solo: nel parlato semplice un aggettivo in い non prende だ, quindi ほしいだ è sbagliato. ほしがる è per i desideri degli altri, visti da fuori, e prende を, non が.'),
  ('8a2168c8-0f88-57f9-87d3-fefd784a8ee9', '感情-理解の述語と-が', 'single-select', '{"sentence":{"kanji":"いつか富士山に登りたい","kana":"いつかふじさんにのぼりたい"},"answer":"登りたい","distractors":["登るたい","登りほしい","登りたがる"],"gap":{"kanji":"いつか富士山に＿","kana":"いつかふじさんに＿"},"prompt":{"en":"\"Someday I want to climb Mount Fuji.\" How do you say \"I want to climb\"?","it":"«Un giorno voglio scalare il monte Fuji.» Come si dice «voglio scalare»?"},"translation":{"en":"Someday I want to climb Mount Fuji.","it":"Un giorno voglio scalare il monte Fuji."},"glosses":[{"text":"登りたい","reading":"のぼりたい"},{"text":"登るたい","reading":"のぼるたい"},{"text":"登りほしい","reading":"のぼりほしい"},{"text":"登りたがる","reading":"のぼりたがる"}]}'::jsonb, '欲求の「ほしい」と「たい」', 'To say "want to do", take the verb''s i-stem (the part before ます: 登ります → 登り) and add たい: 登りたい. たい never goes after the dictionary form, so 登るたい is wrong. ほしい is for things you want, not actions. 登りたがる would describe someone else''s wish, not the speaker''s.', 'Per dire «voglio fare», si prende il radicale in i del verbo (la parte davanti a ます: 登ります → 登り) e si aggiunge たい: 登りたい. たい non va mai dopo la forma del dizionario, quindi 登るたい è sbagliato. ほしい è per le cose che vuoi, non per le azioni. 登りたがる descriverebbe il desiderio di un''altra persona, non di chi parla.'),
  ('69422d6f-6ba6-5969-9aa7-2e1b8df883a1', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"テニスを始めたい","kana":"テニスをはじめたい"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I want to start playing tennis.\" Which part says that the speaker wants to do it?","it":"«Voglio cominciare a giocare a tennis.» Quale parte dice che chi parla vuole farlo?"},"translation":{"en":"I want to start playing tennis.","it":"Voglio cominciare a giocare a tennis."},"glosses":[{"text":"テニスを","meaning":{"en":"tennis + を (what you start)","it":"tennis + を (ciò che inizi)"}},{"text":"始","reading":"はじ","meaning":{"en":"start (kanji of 始める)","it":"iniziare (kanji di 始める)"}},{"text":"めたい","meaning":{"en":"end of 始め + たい, \"want to\"","it":"fine di 始め + たい, «voler fare»"}}]}'::jsonb, '欲求の「ほしい」と「たい」', 'Select めたい. 始める, "start", drops る and becomes 始め; adding たい gives 始めたい, "I want to start". In a statement, たい always says the speaker''s own wish. Here the thing you want to start keeps を, the particle it has with 始める.', 'Seleziona めたい. 始める, «iniziare», perde る e diventa 始め; aggiungendo たい si ottiene 始めたい, «voglio iniziare». In un''affermazione, たい dice sempre il desiderio di chi parla. Qui la cosa che vuoi iniziare tiene を, la particella che ha con 始める.'),
  ('5954f170-56ab-5fb9-b88f-0a8225239039', '感情-理解の述語と-が', 'select-span', '{"sentence":{"kanji":"おばあちゃんが寒がっている","kana":"おばあちゃんがさむがっている"},"answer":{"start":2,"end":3},"prompt":{"en":"\"Grandma is feeling cold.\" Which part shows that we see her feeling from the outside?","it":"«La nonna ha freddo.» Quale parte mostra che vediamo ciò che prova da fuori?"},"translation":{"en":"Grandma is feeling cold.","it":"La nonna ha freddo."},"glosses":[{"text":"おばあちゃんが","meaning":{"en":"grandma + が (who feels it)","it":"la nonna + が (chi lo prova)"}},{"text":"寒","reading":"さむ","meaning":{"en":"cold (kanji of 寒い)","it":"freddo (kanji di 寒い)"}},{"text":"がっている","meaning":{"en":"shows signs of (as seen from outside)","it":"mostra segni di (visto da fuori)"}}]}'::jsonb, '他人の感情を示す「がる」', 'Select がっている. 寒い, "cold", says how the speaker feels. For someone else, drop the final い and add がる, "to show signs of": 寒がる, here as 寒がっている, "is showing that she feels cold". がる works with feeling words like 寒い, not only with ほしい and たい.', 'Seleziona がっている. 寒い, «freddo», dice come si sente chi parla. Per un''altra persona si toglie la い finale e si aggiunge がる, «mostrare segni di»: 寒がる, qui 寒がっている, «mostra di avere freddo». がる funziona con le parole che esprimono sensazioni come 寒い, non solo con ほしい e たい.'),
  ('a55ed941-4488-553f-8372-5373dc4e3518', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"子どもたちがプールに入りたがっている","kana":"こどもたちがプールにはいりたがっている"},"answer":["子どもたちが","プールに","入りたがっている"],"alsoAccepted":[["プールに","子どもたちが","入りたがっている"]],"prompt":{"en":"Build: \"The children want to get into the pool.\"","it":"Componi: «I bambini vogliono entrare in piscina.»"},"translation":{"en":"The children want to get into the pool.","it":"I bambini vogliono entrare in piscina."},"glosses":[{"text":"子どもたちが","reading":"こどもたちが","meaning":{"en":"the children + が (who wants it)","it":"i bambini + が (chi lo vuole)"}},{"text":"プールに","meaning":{"en":"into the pool","it":"in piscina"}},{"text":"入りたがっている","reading":"はいりたがっている","meaning":{"en":"want to get in (as seen from outside)","it":"vogliono entrare (visto da fuori)"}}]}'::jsonb, '他人の感情を示す「がる」', '入りたい would be the speaker''s own wish, "I want to get in". For the children, たい drops its い and takes がる: 入りたがる, here as 入りたがっている, what they are showing right now. The place you enter takes に: プールに. "プールに子どもたちが入りたがっている" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '入りたい sarebbe il desiderio di chi parla, «voglio entrare». Per i bambini, たい perde la い e prende がる: 入りたがる, qui 入りたがっている, ciò che stanno mostrando adesso. Il luogo in cui si entra prende に: プールに. Va bene anche «プールに子どもたちが入りたがっている»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('df2d6e23-0215-5c27-a84d-f3f08df25b90', '感情-理解の述語と-が', 'assemble', '{"sentence":{"kanji":"娘が犬を飼いたがっている","kana":"むすめがいぬをかいたがっている"},"answer":["娘が","犬を","飼いたがっている"],"prompt":{"en":"Build: \"My daughter wants to have a dog.\"","it":"Componi: «Mia figlia vuole prendere un cane.»"},"translation":{"en":"My daughter wants to have a dog.","it":"Mia figlia vuole prendere un cane."},"glosses":[{"text":"娘が","reading":"むすめが","meaning":{"en":"my daughter + が (who wants it)","it":"mia figlia + が (chi lo vuole)"}},{"text":"犬を","reading":"いぬを","meaning":{"en":"dog + を (what she wants to keep)","it":"cane + を (ciò che vuole tenere)"}},{"text":"飼いたがっている","reading":"かいたがっている","meaning":{"en":"wants to keep (a pet), as seen from outside","it":"vuole tenere (un animale), visto da fuori"}}]}'::jsonb, '他人の感情を示す「がる」', '飼う means "keep (a pet)". 飼いたい would be the speaker''s wish; for the daughter it becomes 飼いたがる, here as 飼いたがっている. たがる makes a verb, so the dog takes を, the particle for the object (the thing the action is done to).', '飼う significa «tenere (un animale)». 飼いたい sarebbe il desiderio di chi parla; per la figlia diventa 飼いたがる, qui 飼いたがっている. たがる forma un verbo, quindi il cane prende を, la particella dell''oggetto (la cosa su cui cade l''azione).')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('b1fa153e-1704-5115-b2ea-fcb8cb5e0483', '可能形', 'single-select', '{"sentence":{"kanji":"この川で泳げる","kana":"このかわでおよげる"},"answer":"泳げる","distractors":["泳ぎる","泳ぐれる","泳げられる"],"gap":{"kanji":"この川で＿","kana":"このかわで＿"},"prompt":{"en":"\"You can swim in this river.\" What is the potential form of 泳ぐ?","it":"«In questo fiume si può nuotare.» Qual è la forma potenziale di 泳ぐ?"},"translation":{"en":"You can swim in this river.","it":"In questo fiume si può nuotare."},"glosses":[{"text":"泳げる","reading":"およげる"},{"text":"泳げられる","reading":"およげられる"},{"text":"泳ぐれる","reading":"およぐれる"},{"text":"泳ぎる","reading":"およぎる"}]}'::jsonb, '可能形', 'The potential form is the verb form that means "can do": 泳げる = "can swim". 泳ぐ is a godan verb (a verb whose last kana changes, like 書く, 読む): the final u-sound becomes an e-sound, ぐ → げ, and る is added. The new verb 泳げる then works like 食べる.', 'La forma potenziale è la forma del verbo che dice «posso fare»: 泳げる = «si può nuotare». 泳ぐ è un verbo godan (un verbo il cui ultimo kana cambia, come 書く, 読む): il suono finale in u diventa in e, ぐ → げ, e si aggiunge る. Il nuovo verbo 泳げる poi si comporta come 食べる.'),
  ('e2e3e4f9-6c89-55ea-a10b-e438b2cbfa7c', '可能形', 'single-select', '{"sentence":{"kanji":"この魚は生で食べられる","kana":"このさかなはなまでたべられる"},"answer":"食べられる","distractors":["食べえる","食べらる","食べされる"],"gap":{"kanji":"この魚は生で＿","kana":"このさかなはなまで＿"},"prompt":{"en":"\"This fish can be eaten raw.\" What is the potential form of 食べる?","it":"«Questo pesce si può mangiare crudo.» Qual è la forma potenziale di 食べる?"},"translation":{"en":"This fish can be eaten raw.","it":"Questo pesce si può mangiare crudo."},"glosses":[{"text":"食べられる","reading":"たべられる"},{"text":"食べされる","reading":"たべされる"},{"text":"食べらる","reading":"たべらる"},{"text":"食べえる","reading":"たべえる"}]}'::jsonb, '可能形', 'The potential form means "can do". 食べる is an ichidan verb (a verb ending in -eru or -iru that simply drops る, like 見る, 寝る): remove る and add られる, 食べられる, "can be eaten". In casual speech you also hear 食べれる, but 食べられる is the standard form.', 'La forma potenziale dice «posso fare». 食べる è un verbo ichidan (un verbo in -eru o -iru che perde semplicemente る, come 見る, 寝る): si toglie る e si aggiunge られる, 食べられる, «si può mangiare». Nel parlato informale si sente anche 食べれる, ma la forma standard è 食べられる.'),
  ('86dd7435-ccdf-554c-951f-5a0c3815cda7', '可能形', 'single-select', '{"sentence":{"kanji":"兄は中国語ができる","kana":"あにはちゅうごくごができる"},"answer":"できる","distractors":["するれる","しれる","すられる"],"gap":{"kanji":"兄は中国語が＿","kana":"あにはちゅうごくごが＿"},"prompt":{"en":"\"My older brother can speak Chinese.\" What is the potential form of する (\"do\")?","it":"«Mio fratello maggiore sa il cinese.» Qual è la forma potenziale di する («fare»)?"},"translation":{"en":"My older brother can speak Chinese.","it":"Mio fratello maggiore sa il cinese."}}'::jsonb, '不規則動詞の可能形', 'する ("to do") is irregular: its potential form ("can do") is a different verb, できる. What someone can do takes が: 中国語ができる, "Chinese is something he can do", so "he can speak Chinese".', 'する («fare») è irregolare: la sua forma potenziale («poter fare») è un verbo diverso, できる. Ciò che si sa o si può fare prende が: 中国語ができる, «il cinese è una cosa che sa fare», cioè «sa parlare cinese».'),
  ('84c9b0a0-3ca9-517a-801b-c339fed2146e', '可能形', 'select-span', '{"sentence":{"kanji":"ひらがなが読める","kana":"ひらがながよめる"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the thing that can be read?","it":"Quale parte è ciò che si riesce a leggere?"},"translation":{"en":"I can read hiragana.","it":"So leggere lo hiragana."},"glosses":[{"text":"ひらがなが","meaning":{"en":"hiragana + が (what can be read)","it":"hiragana + が (ciò che si sa leggere)"}},{"text":"読","reading":"よ","meaning":{"en":"read (kanji of 読む)","it":"leggere (kanji di 読む)"}},{"text":"める","meaning":{"en":"end of 読める, \"can read\"","it":"fine di 読める, «saper leggere»"}}]}'::jsonb, '可能形と「が」', 'Select ひらがなが. 読める ("can read") is the potential form of 読む: it describes an ability, a state, more than an action. So the thing you can read usually takes が instead of を.', 'Seleziona ひらがなが. 読める («saper leggere») è la forma potenziale di 読む: descrive una capacità, uno stato, più che un''azione. Per questo ciò che si sa leggere di solito prende が invece di を.'),
  ('b3a6d49e-13cf-516e-a87e-a19b5e30bcfd', '可能形', 'single-select', '{"sentence":{"kanji":"昨日はよく眠れなかった","kana":"きのうはよくねむれなかった"},"answer":"眠れなかった","distractors":["眠りれなかった","眠るなかった","眠れないかった"],"gap":{"kanji":"昨日はよく＿","kana":"きのうはよく＿"},"prompt":{"en":"\"I couldn''t sleep well yesterday.\" How do you say \"couldn''t sleep\"?","it":"«Ieri non sono riuscito a dormire bene.» Come si dice «non sono riuscito a dormire»?"},"translation":{"en":"I couldn''t sleep well yesterday.","it":"Ieri non sono riuscito a dormire bene."},"glosses":[{"text":"眠れなかった","reading":"ねむれなかった"},{"text":"眠れないかった","reading":"ねむれないかった"},{"text":"眠りれなかった","reading":"ねむりれなかった"},{"text":"眠るなかった","reading":"ねむるなかった"}]}'::jsonb, '可能形', '眠れる ("can sleep") is the potential form of 眠る. Every potential form works like 食べる: drop る and add ない for "not", then ない becomes なかった for the past. 眠れる → 眠れない → 眠れなかった, "couldn''t sleep".', '眠れる («riuscire a dormire») è la forma potenziale di 眠る. Ogni forma potenziale si comporta come 食べる: si toglie る e si aggiunge ない per il «non», poi ない diventa なかった per il passato. 眠れる → 眠れない → 眠れなかった, «non sono riuscito a dormire».'),
  ('03e003e9-bc42-5550-98fa-1a83f70cbce6', '可能形', 'assemble', '{"sentence":{"kanji":"日曜日は友達に会えない","kana":"にちようびはともだちにあえない"},"answer":["日曜日は","友達に","会えない"],"prompt":{"en":"Build: \"On Sunday I can''t meet my friends.\"","it":"Componi: «Domenica non posso vedere i miei amici.»"},"translation":{"en":"On Sunday I can''t meet my friends.","it":"Domenica non posso vedere i miei amici."},"glosses":[{"text":"日曜日は","reading":"にちようびは","meaning":{"en":"on Sunday (topic)","it":"domenica (tema)"}},{"text":"友達に","reading":"ともだちに","meaning":{"en":"friends (whom you meet)","it":"gli amici (chi si vede)"}},{"text":"会えない","reading":"あえない","meaning":{"en":"can''t meet","it":"non poter vedere"}}]}'::jsonb, '可能形', '会う ("meet") → 会える ("can meet", the potential form) → 会えない ("can''t meet"). The person you meet takes に: 友達に会う. 日曜日 is the topic here (what we are talking about), so it takes は.', '会う («incontrare») → 会える («poter incontrare», la forma potenziale) → 会えない («non poter incontrare»). La persona che incontri prende に: 友達に会う. Qui 日曜日 è il tema (ciò di cui si parla), quindi prende は.'),
  ('0239c596-9ece-5ceb-a7fb-7bd19a34c098', '可能形', 'single-select', '{"sentence":{"kanji":"明日は来られる","kana":"あしたはこられる"},"answer":"来られる","distractors":["来えれる","来れられる","来られれる"],"gap":{"kanji":"明日は＿","kana":"あしたは＿"},"prompt":{"en":"\"I can come tomorrow.\" What is the potential form of 来る (\"come\")?","it":"«Domani posso venire.» Qual è la forma potenziale di 来る («venire»)?"},"translation":{"en":"I can come tomorrow.","it":"Domani posso venire."},"glosses":[{"text":"来られる","reading":"こられる"},{"text":"来れられる","reading":"これられる"},{"text":"来られれる","reading":"こられれる"},{"text":"来えれる","reading":"こえれる"}]}'::jsonb, '不規則動詞の可能形', '来る ("to come") is irregular. Its potential form ("can come") is 来られる, read こられる: the kanji stays the same, but its reading changes from く to こ. The only other irregular verb is する, whose potential is できる.', '来る («venire») è irregolare. La sua forma potenziale («poter venire») è 来られる, letto こられる: il kanji resta uguale, ma la lettura passa da く a こ. L''unico altro verbo irregolare è する, il cui potenziale è できる.'),
  ('b898bda1-619c-58e6-98ba-28d15df1918c', '可能形', 'select-span', '{"sentence":{"kanji":"カタカナが書ける","kana":"カタカナがかける"},"answer":{"start":2,"end":3},"prompt":{"en":"Which part turns 書く (\"write\") into \"can write\"?","it":"Quale parte trasforma 書く («scrivere») in «saper scrivere»?"},"translation":{"en":"I can write katakana.","it":"So scrivere il katakana."},"glosses":[{"text":"カタカナが","meaning":{"en":"katakana + が (what you can write)","it":"katakana + が (ciò che sai scrivere)"}},{"text":"書","reading":"か","meaning":{"en":"write (kanji of 書く)","it":"scrivere (kanji di 書く)"}},{"text":"ける","meaning":{"en":"end of the verb 書ける","it":"fine del verbo 書ける"}}]}'::jsonb, '可能形', 'Select ける. 書く is a godan verb (its last kana changes): the final く becomes け and る is added, 書ける, "can write". This ending is the potential form, the verb form that means "can do".', 'Seleziona ける. 書く è un verbo godan (il suo ultimo kana cambia): la く finale diventa け e si aggiunge る, 書ける, «saper scrivere». Questa desinenza è la forma potenziale, la forma del verbo che dice «posso fare».'),
  ('3f4da328-ca65-57c9-90ef-ce224e87939b', '可能形', 'assemble', '{"sentence":{"kanji":"私は漢字がまだ読めない","kana":"わたしはかんじがまだよめない"},"answer":["私は","漢字が","まだ","読めない"],"alsoAccepted":[["私は","まだ","漢字が","読めない"],["まだ","私は","漢字が","読めない"]],"prompt":{"en":"Build: \"I still can''t read kanji.\"","it":"Componi: «Non so ancora leggere i kanji.»"},"translation":{"en":"I still can''t read kanji.","it":"Non so ancora leggere i kanji."},"glosses":[{"text":"私は","reading":"わたしは","meaning":{"en":"I (topic)","it":"io (tema)"}},{"text":"漢字が","reading":"かんじが","meaning":{"en":"kanji + が (what you can''t read)","it":"kanji + が (ciò che non sai leggere)"}},{"text":"まだ","meaning":{"en":"still, not yet","it":"ancora"}},{"text":"読めない","reading":"よめない","meaning":{"en":"can''t read","it":"non saper leggere"}}]}'::jsonb, '可能形と「が」', '読める is the potential form of 読む ("can read"), and 読めない is its negative, "can''t read". A potential form describes an ability, so the thing read takes が: 漢字が. まだ with a negative means "not yet". The verb has to stay at the end, but まだ can move: "私はまだ漢字が読めない" and "まだ私は漢字が読めない" are also correct. 私は, the topic, stays before 漢字が.', '読める è la forma potenziale di 読む («saper leggere»), e 読めない è la sua negazione, «non saper leggere». Una forma potenziale descrive una capacità, quindi la cosa letta prende が: 漢字が. まだ con una negazione significa «non ancora». Il verbo deve restare in fondo, ma まだ può cambiare posto: vanno bene anche «私はまだ漢字が読めない» e «まだ私は漢字が読めない». 私は, il tema, resta prima di 漢字が.'),
  ('7f6a7bab-f5c1-5cab-a1a7-91ff60493323', '可能形', 'assemble', '{"sentence":{"kanji":"友達もパーティーに来られる","kana":"ともだちもパーティーにこられる"},"answer":["友達も","パーティーに","来られる"],"alsoAccepted":[["パーティーに","友達も","来られる"]],"prompt":{"en":"Build: \"My friends can come to the party too.\"","it":"Componi: «Anche i miei amici possono venire alla festa.»"},"translation":{"en":"My friends can come to the party too.","it":"Anche i miei amici possono venire alla festa."},"glosses":[{"text":"友達も","reading":"ともだちも","meaning":{"en":"friends too","it":"anche gli amici"}},{"text":"パーティーに","meaning":{"en":"to the party","it":"alla festa"}},{"text":"来られる","reading":"こられる","meaning":{"en":"can come","it":"poter venire"}}]}'::jsonb, '不規則動詞の可能形', '来る ("come") is irregular: its potential form ("can come") is 来られる, read こられる. The place you come to takes に: パーティーに. も after 友達 means "too" and takes the place of が. "パーティーに友達も来られる" is also correct: before the verb, these two pieces can change places.', '来る («venire») è irregolare: la sua forma potenziale («poter venire») è 来られる, letto こられる. Il luogo dove si viene prende に: パーティーに. も dopo 友達 significa «anche» e prende il posto di が. Va bene anche «パーティーに友達も来られる»: prima del verbo questi due pezzi possono scambiarsi di posto.'),
  ('735a95ad-824e-5a7b-a11c-49966a45cfa6', '可能形', 'assemble', '{"sentence":{"kanji":"この公園では自転車に乗れない","kana":"このこうえんではじてんしゃにのれない"},"answer":["この公園では","自転車に","乗れない"],"prompt":{"en":"Build: \"You can''t ride a bicycle in this park.\"","it":"Componi: «In questo parco non si può andare in bicicletta.»"},"translation":{"en":"You can''t ride a bicycle in this park.","it":"In questo parco non si può andare in bicicletta."},"glosses":[{"text":"この公園では","reading":"このこうえんでは","meaning":{"en":"in this park (topic)","it":"in questo parco (tema)"}},{"text":"自転車に","reading":"じてんしゃに","meaning":{"en":"bicycle + に (what you get on)","it":"bicicletta + に (ciò su cui sali)"}},{"text":"乗れない","reading":"のれない","meaning":{"en":"can''t ride","it":"non si può andare"}}]}'::jsonb, '可能形', '乗る ("ride, get on") is a godan verb (its last kana changes): る becomes れ and る is added, 乗れる, the potential form (the form that means "can do"). Its negative is 乗れない, "can''t ride". What you ride takes に: 自転車に乗る.', '乗る («salire, andare su») è un verbo godan (il suo ultimo kana cambia): る diventa れ e si aggiunge る, 乗れる, la forma potenziale (la forma che dice «posso fare»). La sua negazione è 乗れない, «non poter andare». Ciò su cui sali prende に: 自転車に乗る.'),
  ('1c45c275-9e5a-5064-9c20-69fbaaf26ab8', '可能形', 'select-span', '{"sentence":{"kanji":"このアプリで曲が聞ける","kana":"このアプリできょくがきける"},"answer":{"start":2,"end":3},"prompt":{"en":"\"With this app you can listen to songs.\" Which part turns 聞く (\"listen\") into \"can listen\"?","it":"«Con questa app si possono ascoltare canzoni.» Quale parte trasforma 聞く («ascoltare») in «poter ascoltare»?"},"translation":{"en":"With this app you can listen to songs.","it":"Con questa app si possono ascoltare canzoni."},"glosses":[{"text":"このアプリで","meaning":{"en":"with this app","it":"con questa app"}},{"text":"曲が聞","reading":"きょくがき","meaning":{"en":"songs + が (what you can listen to) + first part of 聞く","it":"canzoni + が (ciò che si può ascoltare) + inizio di 聞く"}},{"text":"ける","meaning":{"en":"end of 聞ける, \"can listen\"","it":"fine di 聞ける, «poter ascoltare»"}}]}'::jsonb, '可能形', 'Select ける. 聞く is a godan verb (its last kana changes): the final く becomes け and る is added, 聞ける, "can listen". This ending is the potential form, the form that means "can do". The app is the tool you use, so it takes で.', 'Seleziona ける. 聞く è un verbo godan (il suo ultimo kana cambia): la く finale diventa け e si aggiunge る, 聞ける, «poter ascoltare». Questa desinenza è la forma potenziale, la forma che dice «posso fare». La app è lo strumento che usi, quindi prende で.'),
  ('070dbe9d-d3df-5eb9-8cd6-6723ed07df13', '可能形', 'select-span', '{"sentence":{"kanji":"ロンさんは運転ができる","kana":"ロンさんはうんてんができる"},"answer":{"start":2,"end":3},"prompt":{"en":"\"Ron can drive.\" Which part says that he is able to do it?","it":"«Ron sa guidare.» Quale parte dice che è capace di farlo?"},"translation":{"en":"Ron can drive.","it":"Ron sa guidare."},"glosses":[{"text":"ロンさんは","meaning":{"en":"Ron (topic)","it":"Ron (tema)"}},{"text":"運転","reading":"うんてん","meaning":{"en":"driving","it":"la guida"}},{"text":"ができる","meaning":{"en":"が + できる, \"can do\"","it":"が + できる, «saper fare»"}}]}'::jsonb, '不規則動詞の可能形', 'Select ができる. 運転する means "drive" (運転, "driving", + する, "do"). する is irregular: its potential form (the form that means "can do") is a different verb, できる. What someone can do takes が: 運転ができる.', 'Seleziona ができる. 運転する significa «guidare» (運転, «la guida», + する, «fare»). する è irregolare: la sua forma potenziale (la forma che dice «posso fare») è un verbo diverso, できる. Ciò che qualcuno sa fare prende が: 運転ができる.'),
  ('b893dde8-1469-512a-bb24-4509b093ded7', '可能形', 'select-span', '{"sentence":{"kanji":"あしたの練習には来られない","kana":"あしたのれんしゅうにはこられない"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I can''t come to tomorrow''s practice.\" Which part turns 来る (\"come\") into \"can''t come\"?","it":"«Non posso venire all''allenamento di domani.» Quale parte trasforma 来る («venire») in «non poter venire»?"},"translation":{"en":"I can''t come to tomorrow''s practice.","it":"Non posso venire all''allenamento di domani."},"glosses":[{"text":"あしたの","meaning":{"en":"tomorrow''s","it":"di domani"}},{"text":"練習には来","reading":"れんしゅうにはこ","meaning":{"en":"practice + には (there, as the topic) + 来, read こ here","it":"allenamento + には (lì, come tema) + 来, qui letto こ"}},{"text":"られない","meaning":{"en":"can''t (end of 来られない)","it":"non poter (fine di 来られない)"}}]}'::jsonb, '不規則動詞の可能形', 'Select られない. 来る is irregular: its potential form ("can come") is 来られる, and the kanji is read こ instead of く. Like every potential form, it drops る and adds ない for "not": 来られない, "can''t come".', 'Seleziona られない. 来る è irregolare: la sua forma potenziale («poter venire») è 来られる, e il kanji si legge こ invece di く. Come ogni forma potenziale, perde る e aggiunge ない per il «non»: 来られない, «non poter venire».'),
  ('35c21569-5f10-5be7-a8ee-da66cd1c7c13', '可能形', 'assemble', '{"sentence":{"kanji":"図書館では電話ができない","kana":"としょかんではでんわができない"},"answer":["図書館では","電話が","できない"],"prompt":{"en":"Build: \"You can''t make phone calls in the library.\"","it":"Componi: «In biblioteca non si può telefonare.»"},"translation":{"en":"You can''t make phone calls in the library.","it":"In biblioteca non si può telefonare."},"glosses":[{"text":"図書館では","reading":"としょかんでは","meaning":{"en":"in the library (topic)","it":"in biblioteca (tema)"}},{"text":"電話が","reading":"でんわが","meaning":{"en":"phone call + が (what can''t be done)","it":"telefonata + が (ciò che non si può fare)"}},{"text":"できない","meaning":{"en":"can''t do","it":"non si può fare"}}]}'::jsonb, '不規則動詞の可能形', '電話する means "make a phone call". する is irregular: its potential form ("can do") is a different verb, できる, and its negative is できない, "can''t do". What can or can''t be done takes が: 電話ができない.', '電話する significa «telefonare». する è irregolare: la sua forma potenziale («poter fare») è un verbo diverso, できる, e la sua negazione è できない, «non poter fare». Ciò che si può o non si può fare prende が: 電話ができない.'),
  ('008ead80-e09b-5992-9da9-23c129318c6a', '可能形', 'single-select', '{"sentence":{"kanji":"ケンさんはギターが弾ける","kana":"ケンさんはギターがひける"},"answer":"弾ける","distractors":["弾く","弾きる"],"gap":{"kanji":"ケンさんはギターが＿","kana":"ケンさんはギターが＿"},"prompt":{"en":"\"Ken can play the guitar.\" Which verb form fits after ギターが?","it":"«Ken sa suonare la chitarra.» Quale forma del verbo va dopo ギターが?"},"translation":{"en":"Ken can play the guitar.","it":"Ken sa suonare la chitarra."},"glosses":[{"text":"弾ける","reading":"ひける"},{"text":"弾く","reading":"ひく"},{"text":"弾きる","reading":"ひきる"}]}'::jsonb, '可能形と「が」', '弾ける is the potential form of 弾く, "play (an instrument)": く becomes け and る is added. A potential form describes an ability, a state, so what you can play can take が: ギターが弾ける. The plain verb 弾く is an action and needs を, ギターを弾く, so after が it is wrong. 弾きる is not a real form.', '弾ける è la forma potenziale di 弾く, «suonare (uno strumento)»: く diventa け e si aggiunge る. Una forma potenziale descrive una capacità, uno stato, quindi ciò che sai suonare può prendere が: ギターが弾ける. Il verbo semplice 弾く è un''azione e vuole を, ギターを弾く, quindi dopo が è sbagliato. 弾きる non è una forma che esiste.'),
  ('3f0cf7e3-fb5d-577d-9bfa-e4fa1f4f627d', '可能形', 'single-select', '{"sentence":{"kanji":"ゆいちゃんはもう自分の名前が書ける","kana":"ゆいちゃんはもうじぶんのなまえがかける"},"answer":"が","distractors":["で","に"],"gap":{"kanji":"ゆいちゃんはもう自分の名前＿書ける","kana":"ゆいちゃんはもうじぶんのなまえ＿かける"},"prompt":{"en":"\"Yui can already write her own name.\" Which particle goes after what she can write?","it":"«Yui sa già scrivere il suo nome.» Quale particella va dopo ciò che sa scrivere?"},"translation":{"en":"Yui can already write her own name.","it":"Yui sa già scrivere il suo nome."}}'::jsonb, '可能形と「が」', '書ける ("can write") is the potential form of 書く. It describes an ability, so what you can write usually takes が: 名前が書ける. You will also hear 名前を書ける, which is correct too. で would make the name the tool you write with, and に the place you write on.', '書ける («saper scrivere») è la forma potenziale di 書く. Descrive una capacità, quindi ciò che sai scrivere di solito prende が: 名前が書ける. Si sente anche 名前を書ける, che è corretto lo stesso. で farebbe del nome lo strumento con cui scrivi, e に il posto su cui scrivi.'),
  ('886a6525-e061-5001-8aab-15f8149f944c', '可能形', 'select-span', '{"sentence":{"kanji":"オムレツが作れる","kana":"オムレツがつくれる"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I can make an omelette.\" Which part is the thing I can make?","it":"«So fare l''omelette.» Quale parte è ciò che so fare?"},"translation":{"en":"I can make an omelette.","it":"So fare l''omelette."},"glosses":[{"text":"オムレツが","meaning":{"en":"omelette + が (what I can make)","it":"omelette + が (ciò che so fare)"}},{"text":"作","reading":"つく","meaning":{"en":"make (kanji of 作る)","it":"fare, preparare (kanji di 作る)"}},{"text":"れる","meaning":{"en":"end of 作れる, \"can make\"","it":"fine di 作れる, «saper fare»"}}]}'::jsonb, '可能形と「が」', 'Select オムレツが. 作れる is the potential form of 作る, "make": it describes an ability more than an action. So the thing you can make usually takes が instead of を.', 'Seleziona オムレツが. 作れる è la forma potenziale di 作る, «fare, preparare»: descrive una capacità più che un''azione. Per questo ciò che sai fare di solito prende が invece di を.'),
  ('7ceefddf-d6cb-5960-a886-101e68f07ec7', '可能形', 'assemble', '{"sentence":{"kanji":"山の上ではきれいな星が見られる","kana":"やまのうえではきれいなほしがみられる"},"answer":["山の上では","きれいな","星が","見られる"],"prompt":{"en":"Build: \"On the mountain top you can see beautiful stars.\"","it":"Componi: «In cima alla montagna si possono vedere stelle bellissime.»"},"translation":{"en":"On the mountain top you can see beautiful stars.","it":"In cima alla montagna si possono vedere stelle bellissime."},"glosses":[{"text":"山の上では","reading":"やまのうえでは","meaning":{"en":"on the mountain top (topic)","it":"in cima alla montagna (tema)"}},{"text":"きれいな","meaning":{"en":"beautiful","it":"bellissime"}},{"text":"星が","reading":"ほしが","meaning":{"en":"stars + が (what can be seen)","it":"stelle + が (ciò che si può vedere)"}},{"text":"見られる","reading":"みられる","meaning":{"en":"can see","it":"si possono vedere"}}]}'::jsonb, '可能形と「が」', '見られる is the potential form of 見る, "see". 見る is an ichidan verb (it ends in -iru or -eru and simply drops る), so it adds られる. With a potential form, what can be seen takes が: 星が見られる. きれいな, "beautiful", goes right before the noun it describes.', '見られる è la forma potenziale di 見る, «vedere». 見る è un verbo ichidan (finisce in -iru o -eru e perde semplicemente る), quindi aggiunge られる. Con una forma potenziale, ciò che si può vedere prende が: 星が見られる. きれいな, «bellissime», va subito prima del nome che descrive.')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  kind = excluded.kind,
  payload = excluded.payload,
  grammar_point = excluded.grammar_point,
  explanation_en = excluded.explanation_en,
  explanation_it = excluded.explanation_it;

insert into exercise (id, lesson_id, kind, payload, grammar_point, explanation_en, explanation_it) values
  ('8b92cea7-e170-59d5-af03-0d9948f66eec', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"朝ごはんを食べて学校に行った","kana":"あさごはんをたべてがっこうにいった"},"answer":["朝ごはんを","食べて","学校に","行った"],"prompt":{"en":"Build: \"I ate breakfast and went to school.\"","it":"Componi: «Ho fatto colazione e sono andato a scuola.»"},"translation":{"en":"I ate breakfast and went to school.","it":"Ho fatto colazione e sono andato a scuola."},"glosses":[{"text":"朝ごはんを","reading":"あさごはんを","meaning":{"en":"breakfast + を (what is eaten)","it":"colazione + を (ciò che si mangia)"}},{"text":"食べて","reading":"たべて","meaning":{"en":"eat, and then","it":"mangiare, e poi"}},{"text":"学校に","reading":"がっこうに","meaning":{"en":"to school","it":"a scuola"}},{"text":"行った","reading":"いった","meaning":{"en":"went","it":"sono andato"}}]}'::jsonb, 'て形で節をつなぐ', '食べて is the te-form of 食べる: the verb form ending in て/で that links one action to the next, like "and then". The te-form has no tense of its own: the past た at the end, 行った, makes both actions past. Each piece stays right before its own verb: 朝ごはんを before 食べて, 学校に before 行った.', '食べて è la forma in て di 食べる: la forma del verbo in て/で che collega un''azione alla successiva, come «e poi». La forma in て non ha un tempo suo: il passato た in fondo, 行った, rende passate entrambe le azioni. Ogni pezzo sta subito prima del suo verbo: 朝ごはんを prima di 食べて, 学校に prima di 行った.'),
  ('5037d864-083c-5c3d-babd-d31145d5d7c1', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"窓を開けて外を見た","kana":"まどをあけてそとをみた"},"answer":"開けて","distractors":["開けって","開きて","開けるて"],"gap":{"kanji":"窓を＿外を見た","kana":"まどを＿そとをみた"},"prompt":{"en":"\"I opened the window and looked outside.\" Which form of 開ける (\"open\") links the two actions?","it":"«Ho aperto la finestra e ho guardato fuori.» Quale forma di 開ける («aprire») collega le due azioni?"},"translation":{"en":"I opened the window and looked outside.","it":"Ho aperto la finestra e ho guardato fuori."},"glosses":[{"text":"開けて","reading":"あけて"},{"text":"開けるて","reading":"あけるて"},{"text":"開けって","reading":"あけって"},{"text":"開きて","reading":"あきて"}]}'::jsonb, 'て形で節をつなぐ', 'The te-form (the verb form in て/で) links one action to the next. 開ける is an ichidan verb (it ends in -eru and simply drops る), so 開ける → 開けて. Only the last verb, 見た, is in the past, and that covers both actions.', 'La forma in て (la forma del verbo in て/で) collega un''azione alla successiva. 開ける è un verbo ichidan (finisce in -eru e perde semplicemente る), quindi 開ける → 開けて. Solo l''ultimo verbo, 見た, è al passato, e vale per entrambe le azioni.'),
  ('ade2203c-7d24-5132-8eb2-3fd07457c52b', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"友達が私の宿題を手伝ってくれた","kana":"ともだちがわたしのしゅくだいをてつだってくれた"},"answer":"くれた","distractors":["あげた"],"gap":{"kanji":"友達が私の宿題を手伝って＿","kana":"ともだちがわたしのしゅくだいをてつだって＿"},"prompt":{"en":"\"A friend helped me with my homework.\" Which verb says the favour was done for me?","it":"«Un amico mi ha aiutato con i compiti.» Quale verbo dice che il favore è stato fatto a me?"},"translation":{"en":"A friend helped me with my homework.","it":"Un amico mi ha aiutato con i compiti."}}'::jsonb, '恩恵を受ける「てくれる」', 'The te-form of a verb (here 手伝って, from 手伝う "help") + くれる means someone does something for me, or for my family or group: 手伝ってくれた, "helped me". あげる works the other way, from me to others, so it is wrong when the favour comes to me.', 'La forma in て di un verbo (qui 手伝って, da 手伝う «aiutare») + くれる significa che qualcuno fa qualcosa per me, o per la mia famiglia o il mio gruppo: 手伝ってくれた, «mi ha aiutato». あげる va nell''altro senso, da me agli altri, quindi è sbagliato quando il favore arriva a me.'),
  ('c2fb3ce9-039f-5f33-81e5-87058ea852c3', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"父が夕飯を作ってくれた","kana":"ちちがゆうはんをつくってくれた"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part says the dinner was made for the speaker?","it":"Quale parte dice che la cena è stata preparata per chi parla?"},"translation":{"en":"My father made dinner for me.","it":"Mio padre mi ha preparato la cena."},"glosses":[{"text":"父が夕飯を作","reading":"ちちがゆうはんをつく","meaning":{"en":"father + が, dinner + を, first part of 作る, \"make\"","it":"padre + が, cena + を, inizio di 作る, «preparare»"}},{"text":"ってくれた","meaning":{"en":"end of 作って + くれた, \"did for me\"","it":"fine di 作って + くれた, «ha fatto per me»"}}]}'::jsonb, '恩恵を受ける「てくれる」', 'Select ってくれた: 作って is the te-form of 作る ("make"), and くれた means "did for me". Together they say the dinner was made for the speaker, with no need for a word meaning "for me".', 'Seleziona ってくれた: 作って è la forma in て di 作る («preparare»), e くれた significa «ha fatto per me». Insieme dicono che la cena è stata preparata per chi parla, senza bisogno di una parola per «per me».'),
  ('9cfd0154-9276-5de8-8f67-efcf5be968fe', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"私は妹に絵本を読んであげた","kana":"わたしはいもうとにえほんをよんであげた"},"answer":"あげた","distractors":["くれた"],"gap":{"kanji":"私は妹に絵本を読んで＿","kana":"わたしはいもうとにえほんをよんで＿"},"prompt":{"en":"\"I read a picture book to my younger sister.\" Which verb says I did it for her?","it":"«Ho letto un libro illustrato a mia sorella minore.» Quale verbo dice che l''ho fatto per lei?"},"translation":{"en":"I read a picture book to my younger sister.","it":"Ho letto un libro illustrato a mia sorella minore."}}'::jsonb, '恩恵を与える「てあげる」', 'The te-form of a verb (here 読んで, from 読む "read") + あげる means I, or someone, do something for another person: 読んであげた, "read to her, for her sake". くれる is only for favours that come toward me.', 'La forma in て di un verbo (qui 読んで, da 読む «leggere») + あげる significa che io, o qualcuno, faccio qualcosa per un''altra persona: 読んであげた, «le ho letto, per lei». くれる è solo per i favori che arrivano a me.'),
  ('25d90831-d6f2-5de8-9121-c357c506b9c6', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"兄は忙しくて手伝ってくれなかった","kana":"あにはいそがしくててつだってくれなかった"},"answer":["兄は","忙しくて","手伝ってくれなかった"],"prompt":{"en":"Build: \"My older brother was busy and didn''t help me.\"","it":"Componi: «Mio fratello maggiore era impegnato e non mi ha aiutato.»"},"translation":{"en":"My older brother was busy and didn''t help me.","it":"Mio fratello maggiore era impegnato e non mi ha aiutato."},"glosses":[{"text":"兄は","reading":"あには","meaning":{"en":"older brother (topic)","it":"fratello maggiore (tema)"}},{"text":"忙しくて","reading":"いそがしくて","meaning":{"en":"was busy, and so","it":"era impegnato, e quindi"}},{"text":"手伝ってくれなかった","reading":"てつだってくれなかった","meaning":{"en":"didn''t help me","it":"non mi ha aiutato"}}]}'::jsonb, '恩恵を受ける「てくれる」', 'い-adjectives (describing words ending in い) have a te-form too: 忙しい → 忙しくて, here meaning "was busy, so…". 手伝ってくれなかった is the negative past of てくれる: "didn''t help me". The tense at the very end covers both parts.', 'Anche gli aggettivi in い (parole che descrivono e finiscono in い) hanno una forma in て: 忙しい → 忙しくて, qui «era impegnato, quindi…». 手伝ってくれなかった è il passato negativo di てくれる: «non mi ha aiutato». Il tempo in fondo alla frase vale per entrambe le parti.'),
  ('312afbbc-b8f0-59ee-a09e-6e8eb342a12c', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"駅まで歩いて電車に乗った","kana":"えきまであるいてでんしゃにのった"},"answer":"歩いて","distractors":["歩きて","歩って","歩くて"],"gap":{"kanji":"駅まで＿電車に乗った","kana":"えきまで＿でんしゃにのった"},"prompt":{"en":"\"I walked to the station and got on the train.\" Which form of 歩く (\"walk\") links the two actions?","it":"«Sono andato a piedi alla stazione e ho preso il treno.» Quale forma di 歩く («camminare») collega le due azioni?"},"translation":{"en":"I walked to the station and got on the train.","it":"Sono andato a piedi alla stazione e ho preso il treno."},"glosses":[{"text":"歩いて","reading":"あるいて"},{"text":"歩きて","reading":"あるきて"},{"text":"歩って","reading":"あるって"},{"text":"歩くて","reading":"あるくて"}]}'::jsonb, 'て形で節をつなぐ', 'The te-form (the verb form in て/で) links one action to the next. 歩く is a godan verb (its last kana changes) ending in く, and these make the te-form with いて: 歩く → 歩いて. The past た of 乗った, at the end, makes both actions past.', 'La forma in て (la forma del verbo in て/で) collega un''azione alla successiva. 歩く è un verbo godan (il suo ultimo kana cambia) che finisce in く, e questi fanno la forma in て con いて: 歩く → 歩いて. Il passato た di 乗った, in fondo, rende passate entrambe le azioni.'),
  ('0eb60d4f-ce2d-5ac5-997e-c8e0001041c6', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"シャワーをあびて寝た","kana":"シャワーをあびてねた"},"answer":{"start":0,"end":1},"prompt":{"en":"Which part is the first of the two actions?","it":"Quale parte è la prima delle due azioni?"},"translation":{"en":"I took a shower and went to bed.","it":"Ho fatto la doccia e sono andato a letto."},"glosses":[{"text":"シャワーをあびて","meaning":{"en":"take a shower, and then","it":"fare la doccia, e poi"}},{"text":"寝","reading":"ね","meaning":{"en":"sleep, go to bed (kanji of 寝る)","it":"dormire, andare a letto (kanji di 寝る)"}},{"text":"た","meaning":{"en":"past ending: 寝た","it":"desinenza del passato: 寝た"}}]}'::jsonb, 'て形で節をつなぐ', 'Select シャワーをあびて. あびて is the te-form of あびる ("take a shower"): the verb form in て that links one action to the next, "and then". The second action is 寝た, "went to bed", and its past た covers both.', 'Seleziona シャワーをあびて. あびて è la forma in て di あびる («fare la doccia»): la forma del verbo in て che collega un''azione alla successiva, «e poi». La seconda azione è 寝た, «sono andato a letto», e il suo passato た vale per entrambe.'),
  ('66d19244-8c4c-5e90-815e-c203337c0c72', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"母に花を買ってあげた","kana":"ははにはなをかってあげた"},"answer":{"start":1,"end":2},"prompt":{"en":"Which part says I did it for someone else?","it":"Quale parte dice che l''ho fatto per qualcun altro?"},"translation":{"en":"I bought flowers for my mother.","it":"Ho comprato dei fiori per mia madre."},"glosses":[{"text":"母に花を買","reading":"ははにはなをか","meaning":{"en":"mother + に (for whom), flowers + を, first part of 買う, \"buy\"","it":"madre + に (per chi), fiori + を, inizio di 買う, «comprare»"}},{"text":"ってあげた","meaning":{"en":"end of 買って + あげた, \"did for someone\"","it":"fine di 買って + あげた, «ho fatto per qualcuno»"}}]}'::jsonb, '恩恵を与える「てあげる」', 'Select ってあげた: 買って is the te-form of 買う ("buy"), and あげた means "did for someone". Together they say I bought the flowers for my mother''s sake. The person who receives the favour takes に: 母に.', 'Seleziona ってあげた: 買って è la forma in て di 買う («comprare»), e あげた significa «ho fatto per qualcuno». Insieme dicono che ho comprato i fiori per mia madre. La persona che riceve il favore prende に: 母に.'),
  ('48249e92-0897-59d2-a709-9ddf88e4a483', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"弟に傘を貸してあげた","kana":"おとうとにかさをかしてあげた"},"answer":["弟に","傘を","貸してあげた"],"alsoAccepted":[["傘を","弟に","貸してあげた"]],"prompt":{"en":"Build: \"I lent my umbrella to my younger brother.\"","it":"Componi: «Ho prestato l''ombrello a mio fratello minore.»"},"translation":{"en":"I lent my umbrella to my younger brother.","it":"Ho prestato l''ombrello a mio fratello minore."},"glosses":[{"text":"弟に","reading":"おとうとに","meaning":{"en":"to my younger brother","it":"a mio fratello minore"}},{"text":"傘を","reading":"かさを","meaning":{"en":"umbrella + を (what is lent)","it":"ombrello + を (ciò che si presta)"}},{"text":"貸してあげた","reading":"かしてあげた","meaning":{"en":"lent (as a favour)","it":"ho prestato (come favore)"}}]}'::jsonb, '恩恵を与える「てあげる」', '貸して is the te-form of 貸す ("lend"), and あげた adds that I did it for him, as a favour. The person who receives it takes に: 弟に. The thing lent takes を, the particle for the object (the thing the action is done to). "傘を弟に貸してあげた" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', '貸して è la forma in て di 貸す («prestare»), e あげた aggiunge che l''ho fatto per lui, come favore. Chi lo riceve prende に: 弟に. La cosa prestata prende を, la particella dell''oggetto (la cosa su cui cade l''azione). Va bene anche «傘を弟に貸してあげた»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.'),
  ('2d59b10e-a36e-5531-82ec-43efdfc146d9', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"コートをぬいで座った","kana":"コートをぬいですわった"},"answer":{"start":0,"end":1},"prompt":{"en":"\"I took off my coat and sat down.\" Which part is the first of the two actions?","it":"«Mi sono tolto il cappotto e mi sono seduto.» Quale parte è la prima delle due azioni?"},"translation":{"en":"I took off my coat and sat down.","it":"Mi sono tolto il cappotto e mi sono seduto."},"glosses":[{"text":"コートをぬいで","meaning":{"en":"take off the coat, and then","it":"togliere il cappotto, e poi"}},{"text":"座","reading":"すわ","meaning":{"en":"sit (kanji of 座る)","it":"sedersi (kanji di 座る)"}},{"text":"った","meaning":{"en":"past ending: 座った","it":"desinenza del passato: 座った"}}]}'::jsonb, 'て形で節をつなぐ', 'Select コートをぬいで. ぬいで is the te-form of ぬぐ, "take off (clothes)": verbs ending in ぐ make it with いで, so with で instead of て. The te-form links this action to the next one, 座った, "sat down", and its past た covers both.', 'Seleziona コートをぬいで. ぬいで è la forma in て di ぬぐ, «togliersi (un vestito)»: i verbi in ぐ la fanno con いで, quindi con で invece di て. La forma in て collega questa azione alla successiva, 座った, «mi sono seduto», e il suo passato た vale per entrambe.'),
  ('cdbb06ca-6813-502c-8727-269da9c58e56', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"顔を洗って歯をみがいた","kana":"かおをあらってはをみがいた"},"answer":["顔を","洗って","歯を","みがいた"],"prompt":{"en":"Build: \"I washed my face and brushed my teeth.\"","it":"Componi: «Mi sono lavato il viso e mi sono spazzolato i denti.»"},"translation":{"en":"I washed my face and brushed my teeth.","it":"Mi sono lavato il viso e mi sono spazzolato i denti."},"glosses":[{"text":"顔を","reading":"かおを","meaning":{"en":"face + を (what is washed)","it":"viso + を (ciò che si lava)"}},{"text":"洗って","reading":"あらって","meaning":{"en":"wash, and then","it":"lavare, e poi"}},{"text":"歯を","reading":"はを","meaning":{"en":"teeth + を (what is brushed)","it":"denti + を (ciò che si spazzola)"}},{"text":"みがいた","meaning":{"en":"brushed","it":"ho spazzolato"}}]}'::jsonb, 'て形で節をつなぐ', '洗って is the te-form of 洗う, "wash": verbs ending in う make it with って. It links the first action to the second, like "and then". Only the last verb, みがいた, "brushed", is in the past, and its た covers both actions. Each piece stays right before its own verb: 顔を before 洗って, 歯を before みがいた.', '洗って è la forma in て di 洗う, «lavare»: i verbi in う la fanno con って. Collega la prima azione alla seconda, come «e poi». Solo l''ultimo verbo, みがいた, «ho spazzolato», è al passato, e il suo た vale per entrambe le azioni. Ogni pezzo sta subito prima del suo verbo: 顔を prima di 洗って, 歯を prima di みがいた.'),
  ('55476034-eba3-54b4-9b61-ef6442776d64', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"駅員さんが道を教えてくれた","kana":"えきいんさんがみちをおしえてくれた"},"answer":"教えてくれた","distractors":["教えてあげた","教えくれた","教えるくれた"],"gap":{"kanji":"駅員さんが道を＿","kana":"えきいんさんがみちを＿"},"prompt":{"en":"\"A station worker showed me the way.\" Which form says it was done for me?","it":"«Un addetto della stazione mi ha indicato la strada.» Quale forma dice che è stato fatto per me?"},"translation":{"en":"A station worker showed me the way.","it":"Un addetto della stazione mi ha indicato la strada."},"glosses":[{"text":"教えてくれた","reading":"おしえてくれた"},{"text":"教えてあげた","reading":"おしえてあげた"},{"text":"教えくれた","reading":"おしえくれた"},{"text":"教えるくれた","reading":"おしえるくれた"}]}'::jsonb, '恩恵を受ける「てくれる」', 'くれる goes after the te-form of a verb (the form in て: 教えて, from 教える, "tell, show"): 教えてくれた, "showed me, for my sake". Without て, 教えくれた and 教えるくれた are not possible. 教えてあげた would mean the favour went from him to someone else, not to me.', 'くれる va dopo la forma in て di un verbo (教えて, da 教える, «insegnare, indicare»): 教えてくれた, «mi ha indicato, per me». Senza て, 教えくれた e 教えるくれた non sono possibili. 教えてあげた vorrebbe dire che il favore è andato da lui a qualcun altro, non a me.'),
  ('ec0dbf26-0aba-52f9-bba7-b2689acaec12', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"となりのおばさんがりんごを分けてくれた","kana":"となりのおばさんがりんごをわけてくれた"},"answer":{"start":2,"end":3},"prompt":{"en":"\"The lady next door shared some apples with me.\" Which part says she did it for the speaker?","it":"«La signora della porta accanto mi ha dato un po'' delle sue mele.» Quale parte dice che l''ha fatto per chi parla?"},"translation":{"en":"The lady next door shared some apples with me.","it":"La signora della porta accanto mi ha dato un po'' delle sue mele."},"glosses":[{"text":"となりのおばさんがりんごを","meaning":{"en":"the lady next door + が (who does it), apples + を","it":"la signora accanto + が (chi lo fa), mele + を"}},{"text":"分","reading":"わ","meaning":{"en":"share, divide (kanji of 分ける)","it":"dividere (kanji di 分ける)"}},{"text":"けてくれた","meaning":{"en":"end of 分けて + くれた, \"did for me\"","it":"fine di 分けて + くれた, «ha fatto per me»"}}]}'::jsonb, '恩恵を受ける「てくれる」', 'Select けてくれた: 分けて is the te-form of 分ける, "share", and くれた means "did for me". So the favour comes toward the speaker, even though no word in the sentence says "me".', 'Seleziona けてくれた: 分けて è la forma in て di 分ける, «dividere, condividere», e くれた significa «ha fatto per me». Quindi il favore arriva a chi parla, anche se nessuna parola della frase dice «me».'),
  ('d48788a5-0a8e-506f-bf43-8b778a3e1f67', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"山田さんが駅まで車で送ってくれた","kana":"やまださんがえきまでくるまでおくってくれた"},"answer":["山田さんが","駅まで","車で","送ってくれた"],"alsoAccepted":[["山田さんが","車で","駅まで","送ってくれた"],["駅まで","山田さんが","車で","送ってくれた"],["車で","山田さんが","駅まで","送ってくれた"],["駅まで","車で","山田さんが","送ってくれた"],["車で","駅まで","山田さんが","送ってくれた"]],"prompt":{"en":"Build: \"Yamada gave me a lift to the station by car.\"","it":"Componi: «Yamada mi ha accompagnato in macchina fino alla stazione.»"},"translation":{"en":"Yamada gave me a lift to the station by car.","it":"Yamada mi ha accompagnato in macchina fino alla stazione."},"glosses":[{"text":"山田さんが","reading":"やまださんが","meaning":{"en":"Yamada + が (who does it)","it":"Yamada + が (chi lo fa)"}},{"text":"駅まで","reading":"えきまで","meaning":{"en":"as far as the station","it":"fino alla stazione"}},{"text":"車で","reading":"くるまで","meaning":{"en":"by car","it":"in macchina"}},{"text":"送ってくれた","reading":"おくってくれた","meaning":{"en":"took me there (for me)","it":"mi ha accompagnato (per me)"}}]}'::jsonb, '恩恵を受ける「てくれる」', '送る here means "take someone somewhere". 送ってくれた is its te-form + くれた: Yamada did it for me. The car is the means, so it takes で; まで means "as far as". The verb has to stay at the end, but before it 山田さんが, 駅まで and 車で can go in any order: "山田さんが車で駅まで送ってくれた", "駅まで山田さんが車で送ってくれた" and the others are also correct.', '送る qui significa «accompagnare qualcuno». 送ってくれた è la sua forma in て + くれた: Yamada l''ha fatto per me. La macchina è il mezzo, quindi prende で; まで significa «fino a». Il verbo deve restare in fondo, ma prima di lui 山田さんが, 駅まで e 車で possono stare in qualsiasi ordine: vanno bene anche «山田さんが車で駅まで送ってくれた», «駅まで山田さんが車で送ってくれた» e gli altri.'),
  ('10777724-9154-57ee-b084-02ca253adb62', 'て形で節をつなぐ', 'single-select', '{"sentence":{"kanji":"子どもの荷物を持ってあげた","kana":"こどものにもつをもってあげた"},"answer":"持ってあげた","distractors":["持ってくれた","持つあげた"],"gap":{"kanji":"子どもの荷物を＿","kana":"こどものにもつを＿"},"prompt":{"en":"\"I carried the child''s bag for them.\" Which form says I did it for someone else?","it":"«Ho portato la borsa al bambino.» Quale forma dice che l''ho fatto per qualcun altro?"},"translation":{"en":"I carried the child''s bag for them.","it":"Ho portato la borsa al bambino."},"glosses":[{"text":"持ってあげた","reading":"もってあげた"},{"text":"持ってくれた","reading":"もってくれた"},{"text":"持つあげた","reading":"もつあげた"}]}'::jsonb, '恩恵を与える「てあげる」', 'あげる goes after the te-form of a verb (持って, from 持つ, "hold, carry"): 持ってあげた, "carried it for them". The favour goes from me to someone else. 持ってくれた would mean someone did it for me, and 持つあげた is wrong because あげる needs the te-form.', 'あげる va dopo la forma in て di un verbo (持って, da 持つ, «tenere, portare»): 持ってあげた, «l''ho portata per lui». Il favore va da me a un''altra persona. 持ってくれた vorrebbe dire che qualcuno l''ha fatto per me, e 持つあげた è sbagliato perché あげる vuole la forma in て.'),
  ('597024e7-a618-539d-9071-7cb50c07e303', 'て形で節をつなぐ', 'select-span', '{"sentence":{"kanji":"ルームメイトに料理を作ってあげた","kana":"ルームメイトにりょうりをつくってあげた"},"answer":{"start":2,"end":3},"prompt":{"en":"\"I cooked for my roommate.\" Which part of the verb says the speaker did it for someone else?","it":"«Ho cucinato per il mio coinquilino.» Quale parte del verbo dice che chi parla l''ha fatto per qualcun altro?"},"translation":{"en":"I cooked for my roommate.","it":"Ho cucinato per il mio coinquilino."},"glosses":[{"text":"ルームメイトに","meaning":{"en":"to my roommate (who receives it)","it":"al coinquilino (chi lo riceve)"}},{"text":"料理を作","reading":"りょうりをつく","meaning":{"en":"food + を, first part of 作る, \"make\"","it":"cibo + を, inizio di 作る, «preparare»"}},{"text":"ってあげた","meaning":{"en":"end of 作って + あげた, \"did for someone\"","it":"fine di 作って + あげた, «ho fatto per qualcuno»"}}]}'::jsonb, '恩恵を与える「てあげる」', 'Select ってあげた: 作って is the te-form of 作る, "make", and あげた means "did for someone". The person who receives the favour takes に: ルームメイトに.', 'Seleziona ってあげた: 作って è la forma in て di 作る, «preparare», e あげた significa «ho fatto per qualcuno». La persona che riceve il favore prende に: ルームメイトに.'),
  ('e2fa74fe-6a37-5fdd-aa74-2d7ba1cf1cb6', 'て形で節をつなぐ', 'assemble', '{"sentence":{"kanji":"同僚にコーヒーをいれてあげた","kana":"どうりょうにコーヒーをいれてあげた"},"answer":["同僚に","コーヒーを","いれてあげた"],"alsoAccepted":[["コーヒーを","同僚に","いれてあげた"]],"prompt":{"en":"Build: \"I made coffee for my colleague.\"","it":"Componi: «Ho preparato il caffè per il mio collega.»"},"translation":{"en":"I made coffee for my colleague.","it":"Ho preparato il caffè per il mio collega."},"glosses":[{"text":"同僚に","reading":"どうりょうに","meaning":{"en":"to my colleague (who receives it)","it":"al collega (chi lo riceve)"}},{"text":"コーヒーを","meaning":{"en":"coffee + を (what is made)","it":"caffè + を (ciò che si prepara)"}},{"text":"いれてあげた","meaning":{"en":"made (coffee) for them","it":"ho preparato (per lui)"}}]}'::jsonb, '恩恵を与える「てあげる」', 'コーヒーをいれる means "make coffee". いれて is its te-form, and あげた adds that I did it for my colleague. The person who receives the favour takes に: 同僚に. "コーヒーを同僚にいれてあげた" is also correct: in Japanese the verb has to stay at the end, but before it these pieces can change places.', 'コーヒーをいれる significa «preparare il caffè». いれて è la sua forma in て, e あげた aggiunge che l''ho fatto per il collega. La persona che riceve il favore prende に: 同僚に. Va bene anche «コーヒーを同僚にいれてあげた»: in giapponese conta che il verbo resti in fondo, e prima del verbo questi pezzi possono cambiare posto.')
